function createTerminalTabSession(projectId, { startupDirectory = '' } = {}) {
  const nextNumber = Number(state.terminalTabCounters[projectId] || 0) + 1;
  const inheritedDirectory = String(startupDirectory || '').trim();
  state.terminalTabCounters[projectId] = nextNumber;
  return blankTerminalSession(projectId, {
    label: `Terminal ${nextNumber}`,
    startupDirectory: inheritedDirectory ? normalizeRemoteShellPath(inheritedDirectory) : ''
  });
}

function getTerminalTabs(projectId = state.activeProject?.id, create = false) {
  if (!projectId) return null;
  const stored = state.terminalSessions[projectId];
  if (stored && !Array.isArray(stored)) {
    stored.tabId ||= `terminal-tab-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    stored.label ||= 'Terminal 1';
    stored.startupDirectory ||= '';
    state.terminalSessions[projectId] = [stored];
    state.terminalTabCounters[projectId] = Math.max(1, Number(state.terminalTabCounters[projectId] || 0));
  }
  if (!state.terminalSessions[projectId] && create) {
    const session = createTerminalTabSession(projectId);
    state.terminalSessions[projectId] = [session];
    state.activeTerminalTabIds[projectId] = session.tabId;
  }
  return state.terminalSessions[projectId] || null;
}

function getTerminalSession(projectId = state.activeProject?.id, create = false) {
  const tabs = getTerminalTabs(projectId, create);
  if (!tabs?.length) return null;
  const activeTabId = state.activeTerminalTabIds[projectId];
  const activeSession = tabs.find((session) => session.tabId === activeTabId) || tabs[0];
  state.activeTerminalTabIds[projectId] = activeSession.tabId;
  return activeSession;
}

function getTerminalSessionById(sessionId) {
  const projectId = state.terminalSessionProjectIds[sessionId];
  return projectId ? getTerminalTabs(projectId)?.find((session) => session.sessionId === sessionId) || null : null;
}

function getFtpSession(projectId = state.activeProject?.id, create = false) {
  if (!projectId) return null;
  if (!state.ftpSessions[projectId] && create) state.ftpSessions[projectId] = blankFtpSession(projectId);
  return state.ftpSessions[projectId] || null;
}

function projectConnectionState(projectId) {
  const terminalSessions = getTerminalTabs(projectId);
  const ftpSession = getFtpSession(projectId);
  return {
    ssh: Boolean(terminalSessions?.some((session) => session.sessionId && session.connected)),
    ftp: Boolean(ftpSession?.sessionId && ftpSession.connected),
    rdp: Boolean(state.rdpProjectId === projectId && state.rdpSessionId && state.rdpStatus === 'connected')
  };
}

function isVisibleTerminalSession(session) {
  return Boolean(
    session?.projectId &&
    state.activeProject?.id === session.projectId &&
    state.activeTerminalTabIds[session.projectId] === session.tabId
  );
}

function normalizeRemoteShellPath(remotePath = '.') {
  const source = String(remotePath || '.').trim().replace(/\\/g, '/');
  if (!source) return '.';
  const absolute = source.startsWith('/');
  const stack = [];
  for (const segment of source.split('/')) {
    if (!segment || segment === '.') continue;
    if (segment === '..') {
      if (stack.length) stack.pop();
      continue;
    }
    stack.push(segment);
  }

  if (absolute) return stack.length ? `/${stack.join('/')}` : '/';
  return stack.length ? stack.join('/') : '.';
}

function joinRemoteShellPath(parentPath = '.', childPath = '') {
  const child = String(childPath || '').trim().replace(/\\/g, '/');
  if (!child) return normalizeRemoteShellPath(parentPath);
  if (child.startsWith('/')) return normalizeRemoteShellPath(child);

  const base = normalizeRemoteShellPath(parentPath);
  if (base === '.' || !base) return normalizeRemoteShellPath(child);
  if (base === '/') return normalizeRemoteShellPath(`/${child}`);
  return normalizeRemoteShellPath(`${base}/${child}`);
}

function remoteShellBaseName(remotePath = '') {
  const normalized = normalizeRemoteShellPath(remotePath);
  if (!normalized || normalized === '.' || normalized === '/') return '';
  return normalized.split('/').filter(Boolean).pop() || '';
}

function stripShellQuotes(value = '') {
  const text = String(value || '').trim();
  if (!text) return '';
  if ((text.startsWith('"') && text.endsWith('"')) || (text.startsWith("'") && text.endsWith("'"))) {
    return text.slice(1, -1);
  }
  return text;
}

function formatByteCount(bytes = 0) {
  const value = Number(bytes || 0);
  if (!Number.isFinite(value) || value <= 0) return '0 B';
  if (value < 1024) return `${value} B`;
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`;
  if (value < 1024 * 1024 * 1024) return `${(value / (1024 * 1024)).toFixed(1)} MB`;
  return `${(value / (1024 * 1024 * 1024)).toFixed(1)} GB`;
}

function setTerminalUploadState(
  session,
  patch = { active: false, fileName: '', remotePath: '', transferredBytes: 0, totalBytes: 0, percent: 0 }
) {
  if (!session) return;
  const current = session.upload || blankTerminalUploadState();
  session.upload = {
    ...current,
    ...patch
  };
  if (isVisibleTerminalSession(session)) renderSshUploadPanel(session);
}

function setTerminalSessionDirectory(session, directory, { setHome = false } = {}) {
  if (!session) return;
  const normalized = normalizeRemoteShellPath(directory);
  if (!normalized) return;
  const previous = String(session.currentDirectory || '');
  if (previous && previous !== normalized) session.previousDirectory = previous;
  session.currentDirectory = normalized;
  if (setHome || !session.homeDirectory) session.homeDirectory = normalized;
  if (isVisibleTerminalSession(session)) {
    renderSshUploadPanel(session);
    refreshSshDirectory(session, normalized).catch(() => {});
  }
}

function renderSshUploadPanel(session = getTerminalSession()) {
  if (!els.sshUploadButton) return;
  const connected = Boolean(session?.sessionId && session?.connected);
  const waitingForPathUpdate = Boolean(session?.pendingDirectoryCandidate);
  const currentPath = String(session?.currentDirectory || session?.homeDirectory || '').trim();
  els.sshDirectoryPath.value = waitingForPathUpdate
    ? String(session?.pendingDirectoryCandidate || currentPath)
    : currentPath;
  els.sshDirectoryPath.disabled = !connected || waitingForPathUpdate;
  els.sshDirectoryUpButton.disabled = !connected || waitingForPathUpdate || !currentPath || currentPath === '/';
  els.sshDirectoryRefreshButton.disabled = !connected || waitingForPathUpdate || !currentPath;
  const selectedDirectoryEntry = session?.directoryEntries?.find((entry) => entry.path === session.directorySelectedPath);
  els.sshDirectoryDownloadButton.disabled = !connected || waitingForPathUpdate || !selectedDirectoryEntry;

  const upload = session?.upload || blankTerminalUploadState();
  const uploadInFlight = Boolean(upload.active || pendingActions.has('terminal:upload'));
  const canUpload = Boolean(connected && currentPath && !waitingForPathUpdate && !uploadInFlight);
  els.sshUploadButton.disabled = !canUpload;

  els.sshUploadProgress.classList.toggle('hidden', !upload.active);
  els.sshUploadCancelButton.classList.toggle('hidden', !upload.active);
  els.sshUploadCancelButton.disabled = Boolean(!upload.active || upload.cancelRequested);
  els.sshUploadCancelButton.textContent = upload.cancelRequested ? 'Cancelling...' : 'Cancel upload';
  renderSshDirectory(session);
  if (!upload.active) return;

  const percent = Math.max(0, Math.min(100, Number(upload.percent || 0)));
  const transferred = Number(upload.transferredBytes || 0);
  const total = Number(upload.totalBytes || 0);
  els.sshUploadProgressFile.textContent = upload.fileName ? `Uploading ${upload.fileName}` : 'Uploading file';
  els.sshUploadProgressPercent.textContent = `${percent}%`;
  els.sshUploadProgressBar.style.width = `${percent}%`;
  els.sshUploadProgressDetail.textContent = `${formatByteCount(transferred)} of ${formatByteCount(total)}${
    upload.remotePath ? ` to ${upload.remotePath}` : ''
  }`;
}

function setSshRailView(view) {
  const nextView = ['directory', 'scripts'].includes(view) ? view : 'directory';
  state.sshRailView = nextView;
  els.sshDirectoryPanel.classList.toggle('hidden', nextView !== 'directory');
  els.sshScriptPanel.classList.toggle('hidden', nextView !== 'scripts');
  els.sshDirectoryTab.classList.toggle('active', nextView === 'directory');
  els.sshScriptTab.classList.toggle('active', nextView === 'scripts');
  els.sshDirectoryTab.setAttribute('aria-selected', String(nextView === 'directory'));
  els.sshScriptTab.setAttribute('aria-selected', String(nextView === 'scripts'));
}

function renderSshDirectory(session = getTerminalSession()) {
  if (!els.sshDirectoryList) return;
  const connected = Boolean(session?.sessionId && session?.connected);
  const currentPath = String(session?.currentDirectory || session?.homeDirectory || '').trim();
  els.sshDirectoryList.innerHTML = '';

  if (!connected) {
    els.sshDirectoryStatus.textContent = 'Connect SSH to browse files.';
    return;
  }
  if (session.pendingDirectoryCandidate || session.directoryLoading) {
    els.sshDirectoryStatus.textContent = session.pendingDirectoryCandidate ? 'Opening directory...' : 'Loading directory...';
    return;
  }
  if (session.directoryError) {
    els.sshDirectoryStatus.textContent = session.directoryError;
    return;
  }

  const entries = session.directoryPath === currentPath ? session.directoryEntries : [];
  els.sshDirectoryStatus.textContent = entries.length
    ? `${entries.length} item${entries.length === 1 ? '' : 's'}`
    : 'This directory is empty.';
  for (const entry of entries) {
    const row = document.createElement('button');
    row.type = 'button';
    row.className = `ssh-directory-row ${entry.path === session.directorySelectedPath ? 'selected' : ''}`;
    row.dataset.entryPath = entry.path;
    row.dataset.entryType = entry.type;
    row.dataset.entryName = entry.name;
    row.innerHTML = `
      <span class="ssh-directory-name">${icon(entry.type === 'directory' ? 'folder-open' : 'file')}<strong>${escapeHtml(entry.name)}</strong></span>
      <span class="ssh-directory-meta">${entry.type === 'directory' ? 'Folder' : formatByteCount(entry.size)}</span>
    `;
    row.addEventListener('click', () => {
      if (entry.type === 'directory') {
        session.directorySelectedPath = '';
        openSshDirectoryPath(entry.path).catch((error) => showAlert(error.message || 'Could not open server directory.'));
      } else {
        session.directorySelectedPath = entry.path;
        openSshEditorFile(entry).catch((error) => showAlert(error.message || 'Could not open server file.'));
      }
    });
    row.addEventListener('contextmenu', (event) => {
      event.preventDefault();
      session.directorySelectedPath = entry.path;
      renderSshUploadPanel(session);
      showSshDirectoryContextMenu(event, entry);
    });
    els.sshDirectoryList.appendChild(row);
  }
}

async function refreshSshDirectory(session = getTerminalSession(), pathOverride = '') {
  if (!session?.sessionId || !session.connected) {
    renderSshDirectory(session);
    return;
  }
  const remotePath = normalizeRemoteShellPath(pathOverride || session.currentDirectory || session.homeDirectory || '.');
  const requestId = Number(session.directoryRequestId || 0) + 1;
  session.directoryRequestId = requestId;
  session.directoryLoading = true;
  session.directoryError = '';
  if (isVisibleTerminalSession(session)) renderSshDirectory(session);
  try {
    const result = await window.deployerx.listTerminalDirectory({ sessionId: session.sessionId, path: remotePath });
    if (session.directoryRequestId !== requestId) return;
    session.directoryPath = normalizeRemoteShellPath(result.path || remotePath);
    session.directoryParentPath = normalizeRemoteShellPath(result.parentPath || parentFtpPath(session.directoryPath));
    session.directoryEntries = Array.isArray(result.items) ? result.items : [];
    if (!session.directoryEntries.some((entry) => entry.path === session.directorySelectedPath)) session.directorySelectedPath = '';
  } catch (error) {
    if (session.directoryRequestId !== requestId) return;
    session.directoryError = error.message || 'Could not load this directory.';
  } finally {
    if (session.directoryRequestId === requestId) session.directoryLoading = false;
    if (isVisibleTerminalSession(session)) renderSshDirectory(session);
  }
}

function quoteShellPath(remotePath) {
  return `'${String(remotePath || '').replace(/'/g, `'\\''`)}'`;
}

async function openSshDirectoryPath(remotePath) {
  const session = getTerminalSession();
  if (!session?.sessionId || !session.connected) return;
  const normalizedPath = normalizeRemoteShellPath(remotePath);
  session.pendingDirectoryCandidate = normalizedPath;
  renderSshUploadPanel(session);
  renderSshDirectory(session);
  await sendTerminalInput(`cd -- ${quoteShellPath(normalizedPath)}\r`, session.sessionId);
}

function sshEditorLanguage(filePath = '') {
  const extension = String(filePath).split('.').pop()?.toLowerCase() || '';
  return {
    js: 'javascript', cjs: 'javascript', mjs: 'javascript', jsx: 'javascript',
    ts: 'typescript', tsx: 'typescript', json: 'json', css: 'css', scss: 'scss',
    html: 'html', htm: 'html', xml: 'xml', yml: 'yaml', yaml: 'yaml',
    md: 'markdown', sh: 'shell', bash: 'shell', py: 'python', php: 'php',
    sql: 'sql', dockerfile: 'dockerfile'
  }[extension] || 'plaintext';
}

let sshEditorMonacoEditor = null;
let sshEditorMonacoModel = null;
let sshEditorAutosaveTimer = null;
let sshEditorSuppressChange = false;
let sshEditorSavePromise = null;

function sshEditorValue() {
  return sshEditorMonacoModel?.getValue() ?? els.sshEditorTextarea.value;
}

function setSshEditorValue(value, filePath = '') {
  const text = String(value ?? '');
  els.sshEditorTextarea.value = text;
  if (sshEditorMonacoModel) {
    sshEditorSuppressChange = true;
    sshEditorMonacoModel.setValue(text);
    if (window.monaco?.editor) window.monaco.editor.setModelLanguage(sshEditorMonacoModel, sshEditorLanguage(filePath));
    sshEditorSuppressChange = false;
  }
}

function initializeSshEditorMonaco() {
  const amdRequire = window.require;
  if (typeof amdRequire !== 'function' || typeof amdRequire.config !== 'function') return;
  const vsPath = new URL('../../node_modules/monaco-editor/min/vs', window.location.href).href.replace(/\/$/, '');
  amdRequire.config({ paths: { vs: vsPath } });
  amdRequire(['vs/editor/editor.main'], () => {
    if (!window.monaco?.editor || sshEditorMonacoEditor) return;
    sshEditorMonacoModel = window.monaco.editor.createModel(els.sshEditorTextarea.value, 'plaintext');
    sshEditorMonacoEditor = window.monaco.editor.create(els.sshEditorMonaco, {
      model: sshEditorMonacoModel,
      theme: databaseQueryMonacoTheme(),
      ariaLabel: 'Server file editor',
      automaticLayout: true,
      minimap: { enabled: false },
      fontFamily: "Consolas, 'Courier New', monospace",
      fontSize: 13,
      lineHeight: 21,
      lineNumbersMinChars: 3,
      padding: { top: 10, bottom: 10 },
      scrollBeyondLastLine: false,
      tabSize: 2,
      insertSpaces: true
    });
    sshEditorMonacoModel.onDidChangeContent(() => {
      els.sshEditorTextarea.value = sshEditorMonacoModel.getValue();
      if (!sshEditorSuppressChange) markSshEditorDirty();
    });
    sshEditorMonacoEditor.addCommand(window.monaco.KeyMod.CtrlCmd | window.monaco.KeyCode.KeyS, () => {
      saveSshEditorFile().catch(() => {});
    });
    els.sshEditorMonaco.classList.remove('hidden');
    els.sshEditorMonaco.setAttribute('aria-hidden', 'false');
    els.sshEditorHost.classList.add('monaco-ready');
  });
}

function markSshEditorDirty() {
  if (!state.sshEditor.path) return;
  state.sshEditor.dirty = true;
  els.sshEditorStatus.textContent = 'Unsaved changes';
  clearTimeout(sshEditorAutosaveTimer);
  sshEditorAutosaveTimer = setTimeout(() => saveSshEditorFile().catch(() => {}), 900);
}

async function openSshEditorFile(entry) {
  const session = getTerminalSession();
  if (!entry?.path || !session?.sessionId || !session.connected) return;
  if (state.sshEditor.dirty) {
    await saveSshEditorFile();
    if (state.sshEditor.dirty) await saveSshEditorFile();
    if (state.sshEditor.dirty) throw new Error('Save the current file before opening another file.');
  }
  showView('ssh-file');
  els.sshEditorFileName.textContent = entry.name || remoteShellBaseName(entry.path) || 'File';
  els.sshEditorFileName.title = entry.path;
  els.sshEditorPath.textContent = entry.path;
  els.sshEditorStatus.textContent = 'Loading...';
  els.sshEditorSaveButton.disabled = true;
  els.sshEditorDownloadButton.disabled = true;
  try {
    const result = await window.deployerx.readTerminalFile({ sessionId: session.sessionId, path: entry.path });
    state.sshEditor = { sessionId: session.sessionId, path: result.path || entry.path, dirty: false, saving: false };
    setSshEditorValue(result.content || '', result.path || entry.path);
    els.sshEditorStatus.textContent = 'Saved';
    els.sshEditorSaveButton.disabled = false;
    els.sshEditorDownloadButton.disabled = false;
    requestAnimationFrame(() => {
      sshEditorMonacoEditor?.layout();
      sshEditorMonacoEditor?.focus();
    });
  } catch (error) {
    showView('project');
    throw error;
  }
}

async function downloadSshFile({ sessionId = '', path = '', name = '' } = {}) {
  const terminalSession = getTerminalSessionById(sessionId) || getTerminalSession();
  const remotePath = normalizeRemoteShellPath(path);
  if (!terminalSession?.sessionId || !terminalSession.connected || !remotePath || remotePath === '.') return;
  const localPath = await window.deployerx.selectTerminalDownload(name || remoteShellBaseName(remotePath) || 'download');
  if (!localPath) return;
  await withFileActivity(`Downloading ${name || remoteShellBaseName(remotePath)}...`, () =>
    window.deployerx.downloadTerminalFile({ sessionId: terminalSession.sessionId, path: remotePath, localPath })
  );
  showToast(`Downloaded ${name || remoteShellBaseName(remotePath)}`);
}

function selectedSshDirectoryEntry(session = getTerminalSession()) {
  return session?.directoryEntries?.find((entry) => entry.path === session.directorySelectedPath) || null;
}

async function openSshDirectoryEntry(entry) {
  if (!entry) return;
  if (entry.type === 'directory') {
    await openSshDirectoryPath(entry.path);
    return;
  }
  await openSshEditorFile(entry);
}

async function openSshDirectoryEntryWith(entry) {
  const session = getTerminalSession();
  if (!entry || entry.type === 'directory' || !session?.sessionId || !session.connected) return;
  await withFileActivity(`Opening ${entry.name}...`, () =>
    window.deployerx.openTerminalEntryWith({ sessionId: session.sessionId, entry })
  );
}

async function downloadSshDirectoryEntry(entry) {
  const session = getTerminalSession();
  if (!entry || !session?.sessionId || !session.connected) return;
  if (entry.type !== 'directory') {
    await downloadSshFile({ sessionId: session.sessionId, path: entry.path, name: entry.name });
    return;
  }

  const localDirectory = await window.deployerx.selectLocalFolder();
  if (!localDirectory) return;
  const result = await withFileActivity(`Downloading ${entry.name}...`, () =>
    window.deployerx.downloadTerminalEntryToDirectory({
      sessionId: session.sessionId,
      entry,
      localDirectory
    })
  );
  showToast(`Downloaded ${entry.name} to ${result.localPath}`);
}

async function renameSshDirectoryEntry(entry) {
  const session = getTerminalSession();
  if (!entry || !session?.sessionId || !session.connected) return;
  const name = promptFileName('Rename server item', entry.name);
  if (!name || name === entry.name) return;
  await window.deployerx.renameTerminalEntry({ sessionId: session.sessionId, entry, name });
  session.directorySelectedPath = '';
  await refreshSshDirectory(session);
  showToast('Server item renamed');
}

async function deleteSshDirectoryEntry(entry) {
  const session = getTerminalSession();
  if (!entry || !session?.sessionId || !session.connected) return;
  const ok = await confirmDangerousAction(
    `Delete server "${entry.name}"?`,
    entry.type === 'directory' ? 'This deletes the server folder and all of its contents.' : 'This action cannot be undone.',
    'Delete'
  );
  if (!ok) return;
  await withFileActivity(`Deleting ${entry.name}...`, () =>
    window.deployerx.deleteTerminalEntry({ sessionId: session.sessionId, entry })
  );
  session.directorySelectedPath = '';
  await refreshSshDirectory(session);
  showToast('Server item deleted');
}

async function createSshDirectory() {
  const session = getTerminalSession();
  const remoteDirectory = String(session?.currentDirectory || session?.homeDirectory || '').trim();
  if (!session?.sessionId || !session.connected || !remoteDirectory) return;
  const name = promptFileName('New folder name');
  if (!name) return;
  await window.deployerx.makeTerminalDirectory({ sessionId: session.sessionId, remoteDirectory, name });
  await refreshSshDirectory(session);
  showToast('Server folder created');
}

function getSshDirectoryContextItems(entry = null) {
  const session = getTerminalSession();
  const connected = Boolean(session?.sessionId && session.connected);
  const ready = Boolean(connected && !session.pendingDirectoryCandidate && !session.directoryLoading);
  return [
    { label: 'Open', disabled: !ready || !entry, action: () => openSshDirectoryEntry(entry) },
    { label: 'Open with...', disabled: !ready || !entry || entry.type === 'directory', action: () => openSshDirectoryEntryWith(entry) },
    { label: 'Download', disabled: !ready || !entry, action: () => downloadSshDirectoryEntry(entry) },
    { label: 'Rename', disabled: !ready || !entry, action: () => renameSshDirectoryEntry(entry) },
    { label: 'Delete', disabled: !ready || !entry, action: () => deleteSshDirectoryEntry(entry) },
    { label: 'Refresh', disabled: !ready, action: () => refreshSshDirectory(session) },
    { label: 'Upload file', disabled: !ready || Boolean(session?.upload?.active), action: () => uploadFileToCurrentSshPath() },
    { label: 'New folder', disabled: !ready, action: () => createSshDirectory() }
  ];
}

function showSshDirectoryContextMenu(event, entry = null) {
  showContextMenuItems(event, getSshDirectoryContextItems(entry));
}

function saveSshEditorFile() {
  if (sshEditorSavePromise) return sshEditorSavePromise;
  const editorState = state.sshEditor;
  if (!editorState.path) return Promise.resolve();
  const session = getTerminalSessionById(editorState.sessionId);
  if (!session?.connected) {
    els.sshEditorStatus.textContent = 'SSH disconnected';
    return Promise.resolve();
  }
  clearTimeout(sshEditorAutosaveTimer);
  const content = sshEditorValue();
  editorState.saving = true;
  els.sshEditorSaveButton.disabled = true;
  els.sshEditorStatus.textContent = 'Saving...';
  const operation = (async () => {
    try {
      await window.deployerx.writeTerminalFile({ sessionId: session.sessionId, path: editorState.path, content });
      if (state.sshEditor !== editorState) return;
      const unchanged = content === sshEditorValue();
      editorState.dirty = !unchanged;
      els.sshEditorStatus.textContent = unchanged ? 'Saved to server' : 'Unsaved changes';
      if (!unchanged) sshEditorAutosaveTimer = setTimeout(() => saveSshEditorFile().catch(() => {}), 900);
    } catch (error) {
      editorState.dirty = true;
      if (state.sshEditor === editorState) els.sshEditorStatus.textContent = error.message || 'Save failed';
      throw error;
    } finally {
      editorState.saving = false;
      if (state.sshEditor === editorState) els.sshEditorSaveButton.disabled = false;
    }
  })();
  sshEditorSavePromise = operation;
  return operation.finally(() => {
    if (sshEditorSavePromise === operation) sshEditorSavePromise = null;
  });
}

function resolveShellCdTarget(rawTarget, session) {
  const source = String(rawTarget || '').trim().replace(/^--\s+/, '');
  const currentPath = String(session?.pendingDirectoryCandidate || session?.currentDirectory || session?.homeDirectory || '').trim();
  const homePath = String(session?.homeDirectory || '').trim();
  const previousPath = String(session?.previousDirectory || '').trim();

  if (!source || source === '~') return homePath || currentPath;
  if (source === '-') return previousPath;
  if (source.startsWith('/')) return normalizeRemoteShellPath(source);
  if (source === '~/') return homePath || currentPath;
  if (source.startsWith('~/')) {
    const relative = source.slice(2);
    return joinRemoteShellPath(homePath || currentPath || '.', relative);
  }
  if (source.startsWith('~')) return '';
  if (!currentPath) return '';
  return joinRemoteShellPath(currentPath, source);
}

function trackShellCommand(command, session) {
  if (!session) return;
  const raw = String(command || '').trim();
  if (!raw) return;

  session.awaitingPwd = /^pwd(?:\s|$)/.test(raw);
  const cdMatch = raw.match(/^cd(?:\s+(.*))?$/);
  if (!cdMatch) {
    renderSshUploadPanel(session);
    return;
  }

  const rawTarget = stripShellQuotes(String(cdMatch[1] || '').replace(/^--\s+/, ''));
  const nextDirectory = resolveShellCdTarget(rawTarget, session);
  if (nextDirectory) session.pendingDirectoryCandidate = normalizeRemoteShellPath(nextDirectory);
  renderSshUploadPanel(session);
}

function trackTerminalInputChunk(input, sessionId = state.activeTerminalSessionId) {
  const terminalSession = getTerminalSessionById(sessionId) || getTerminalSession();
  if (!terminalSession) return;

  const chunk = String(input || '');
  for (const char of chunk) {
    if (char === '\u0003') {
      terminalSession.commandBuffer = '';
      terminalSession.pendingDirectoryCandidate = '';
      terminalSession.awaitingPwd = false;
      continue;
    }
    if (char === '\u0015') {
      terminalSession.commandBuffer = '';
      continue;
    }
    if (char === '\u007f' || char === '\b') {
      terminalSession.commandBuffer = String(terminalSession.commandBuffer || '').slice(0, -1);
      continue;
    }
    if (char === '\r' || char === '\n') {
      const command = String(terminalSession.commandBuffer || '');
      terminalSession.commandBuffer = '';
      trackShellCommand(command, terminalSession);
      continue;
    }
    if (char >= ' ') terminalSession.commandBuffer = `${terminalSession.commandBuffer || ''}${char}`;
  }
}

function promptPathTokenFromLine(line = '') {
  const prompt = String(line || '').trimEnd();
  if (!prompt) return '';
  let match = prompt.match(/^\[[^\]\r\n]+?\s+([^\]\r\n]+)\]\s*[#$]\s*$/);
  if (match?.[1]) return match[1].trim();
  match = prompt.match(/^[A-Za-z0-9_.-]+@[\w.-]+:(~?[^\r\n#$]*)[#$]\s*$/);
  if (match?.[1]) return match[1].trim();
  match = prompt.match(/^[A-Za-z0-9_.-]+@[\w.-]+\s+(~?[^\r\n#$]*)[#$]\s*$/);
  if (match?.[1]) return match[1].trim();
  return '';
}

function reconcilePromptPath(session, promptToken = '') {
  if (!session) return;
  const token = String(promptToken || '').trim();
  if (!token) return;

  if (token.startsWith('/') || token.startsWith('~/') || token === '~') {
    const resolved = token === '~' ? session.homeDirectory : resolveShellCdTarget(token, session);
    if (resolved) setTerminalSessionDirectory(session, resolved);
    session.pendingDirectoryCandidate = '';
    return;
  }

  const pendingDirectory = String(session.pendingDirectoryCandidate || '');
  if (pendingDirectory && remoteShellBaseName(pendingDirectory) === token) {
    setTerminalSessionDirectory(session, pendingDirectory);
    session.pendingDirectoryCandidate = '';
    return;
  }

  const currentDirectory = String(session.currentDirectory || '');
  if (currentDirectory && remoteShellBaseName(currentDirectory) === token) {
    session.pendingDirectoryCandidate = '';
    renderSshUploadPanel(session);
    return;
  }

  if (pendingDirectory) {
    session.pendingDirectoryCandidate = '';
    renderSshUploadPanel(session);
  }
}

function syncTerminalDirectoryFromOutput(visibleText, session) {
  if (!session) return;
  const lines = String(visibleText || '')
    .split('\n')
    .map((line) => line.replace(/\r/g, '').trim())
    .filter(Boolean);

  for (const line of lines.slice(-8)) {
    if (session.awaitingPwd && line.startsWith('/')) {
      setTerminalSessionDirectory(session, line);
      session.awaitingPwd = false;
      session.pendingDirectoryCandidate = '';
      break;
    }
  }

  const promptToken = promptPathTokenFromLine(lines[lines.length - 1] || '');
  if (promptToken && session.directoryPromptMarkerSeen) {
    session.directoryPromptMarkerSeen = false;
    return;
  }
  if (promptToken) reconcilePromptPath(session, promptToken);
}

function consumeTerminalDirectoryMarkers(rawText, session) {
  if (!session) return false;
  let buffer = `${session.directoryMarkerBuffer || ''}${String(rawText || '')}`.slice(-2048);
  const markerPattern = /\x1b\]1337;DeployerXPwd=([^\x07\x1b\r\n]+)(?:\x07|\x1b\\)/g;
  let match;
  let consumedUntil = 0;
  while ((match = markerPattern.exec(buffer))) {
    consumedUntil = markerPattern.lastIndex;
    const directory = normalizeRemoteShellPath(match[1]);
    if (directory) {
      session.pendingDirectoryCandidate = '';
      session.awaitingPwd = false;
      session.directoryPromptMarkerSeen = true;
      setTerminalSessionDirectory(session, directory);
    }
  }
  session.directoryMarkerBuffer = consumedUntil ? buffer.slice(consumedUntil) : buffer.slice(-512);
  return consumedUntil > 0;
}

async function ensureTerminalHomeDirectory(sessionId = state.activeTerminalSessionId) {
  const terminalSession = getTerminalSessionById(sessionId) || getTerminalSession();
  if (!terminalSession?.sessionId || terminalSession.homeDirectory) return terminalSession?.homeDirectory || '';
  const response = await window.deployerx.getTerminalHomeDirectory(terminalSession.sessionId);
  const homeDirectory = normalizeRemoteShellPath(response?.path || '');
  if (!homeDirectory) return '';
  setTerminalSessionDirectory(terminalSession, homeDirectory, { setHome: true });
  return homeDirectory;
}

function applyTerminalSessionToState(projectId) {
  const terminalSession = getTerminalSession(projectId);
  state.activeTerminalSessionId = terminalSession?.sessionId || null;
  state.terminalConnected = Boolean(terminalSession?.connected);
  state.pendingTerminalInput = terminalSession?.pendingInput || '';
  state.terminalOutputBuffer = terminalSession?.outputBuffer || '';
  state.terminalRawBuffer = terminalSession?.rawBuffer || '';
}

function renderVisibleTerminalSession(session = getTerminalSession()) {
  terminal.reset();
  terminal.clear();
  terminal.write(session?.output || 'Ready.\r\n');
  renderTerminalTabs(session?.projectId);
}

function renderTerminalTabs(projectId = state.activeProject?.id) {
  if (!els.terminalTabs || !els.terminalNewTabButton) return;
  if (projectId && state.activeProject?.id !== projectId) return;
  const tabs = getTerminalTabs(projectId, Boolean(projectId));
  const activeTabId = projectId ? state.activeTerminalTabIds[projectId] : '';
  els.terminalTabs.replaceChildren();

  for (const session of tabs || []) {
    const tab = document.createElement('div');
    const isActive = session.tabId === activeTabId;
    const isConnecting = Boolean(session.sessionId && !session.connected);
    tab.className = `terminal-tab${isActive ? ' active' : ''}${session.connected ? ' connected' : ''}${isConnecting ? ' connecting' : ''}`;
    tab.dataset.terminalTabId = session.tabId;
    tab.innerHTML = `
      <button class="terminal-tab-select" type="button" role="tab" aria-controls="terminal" aria-selected="${isActive}" tabindex="${isActive ? '0' : '-1'}" data-terminal-tab-select="${escapeHtml(session.tabId)}">
        <span class="terminal-tab-status" aria-hidden="true"></span>
        <span class="terminal-tab-label">${escapeHtml(session.label || 'Terminal')}</span>
      </button>
      <button class="terminal-tab-close" type="button" aria-label="Close ${escapeHtml(session.label || 'terminal')}" title="Close terminal" data-terminal-tab-close="${escapeHtml(session.tabId)}">
        ${icon('x')}
      </button>`;
    els.terminalTabs.appendChild(tab);
  }

  els.terminalNewTabButton.disabled = !projectId || isRdpProject();
  els.terminalTabs.querySelector('.terminal-tab.active')?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
}

function activateTerminalTab(tabId, { focus = true } = {}) {
  const projectId = state.activeProject?.id;
  const session = getTerminalTabs(projectId)?.find((item) => item.tabId === tabId);
  if (!session) return;
  state.activeTerminalTabIds[projectId] = session.tabId;
  applyTerminalSessionToState(projectId);
  renderVisibleTerminalSession(session);
  updateTerminalStatus(session.status || (session.connected ? 'Connected' : 'Not connected'), session.connected);
  if (session.connected && session.sessionId) {
    if (!session.homeDirectory) ensureTerminalHomeDirectory(session.sessionId).catch(() => {});
    else refreshSshDirectory(session).catch(() => {});
  }
  requestAnimationFrame(() => {
    fitTerminal();
    resizeActiveTerminal();
    if (focus) terminal.focus();
  });
}

async function openNewTerminalTab() {
  const projectId = state.activeProject?.id;
  if (!projectId || isRdpProject()) return;
  const currentSession = getTerminalSession(projectId);
  const startupDirectory = String(
    currentSession?.currentDirectory || currentSession?.homeDirectory || currentSession?.startupDirectory || ''
  );
  const session = createTerminalTabSession(projectId, { startupDirectory });
  getTerminalTabs(projectId, true).push(session);
  state.activeTerminalTabIds[projectId] = session.tabId;
  activateTerminalTab(session.tabId);
  await connectTerminal();
}

async function closeTerminalTab(tabId) {
  const projectId = state.activeProject?.id;
  const tabs = getTerminalTabs(projectId);
  const index = tabs?.findIndex((session) => session.tabId === tabId) ?? -1;
  if (index < 0) return;
  const session = tabs[index];
  const wasActive = state.activeTerminalTabIds[projectId] === tabId;

  if (session.sessionId) {
    const ok = await confirmDangerousAction(
      `Close ${session.label || 'this terminal'}?`,
      'Running commands in this terminal session will be stopped.',
      'Close terminal'
    );
    if (!ok) return;
    if (state.scriptTerminalSessionId === session.sessionId) stopScriptQueue();
    await window.deployerx.stopTerminal(session.sessionId);
    removeTerminalSessionRegistration(session.sessionId);
  }

  tabs.splice(index, 1);
  if (!tabs.length) {
    state.terminalTabCounters[projectId] = 0;
    const replacement = createTerminalTabSession(projectId);
    tabs.push(replacement);
  }
  if (!wasActive) {
    renderTerminalTabs(projectId);
    renderProjects();
    return;
  }
  const nextSession = tabs[Math.min(index, tabs.length - 1)];
  state.activeTerminalTabIds[projectId] = nextSession.tabId;
  activateTerminalTab(nextSession.tabId);
}

function removeTerminalSessionRegistration(sessionId) {
  if (!sessionId) return;
  delete state.terminalSessionProjectIds[sessionId];
}

async function disconnectProjectConnections(projectId) {
  if (state.rdpSessionId && state.rdpProjectId === projectId) {
    activeRdpClient?.disconnect();
    activeRdpClient = null;
    try {
      await window.deployerx.stopRdp(state.rdpSessionId);
    } catch {}
    state.rdpSessionId = null;
    state.rdpProjectId = '';
    state.rdpStatus = 'disconnected';
  }

  const terminalSessions = getTerminalTabs(projectId);
  for (const terminalSession of terminalSessions || []) {
    if (!terminalSession.sessionId) continue;
    try {
      await window.deployerx.stopTerminal(terminalSession.sessionId);
    } catch {}
    removeTerminalSessionRegistration(terminalSession.sessionId);
  }

  const ftpSession = getFtpSession(projectId);
  if (ftpSession?.sessionId) {
    try {
      await window.deployerx.ftpDisconnect(ftpSession.sessionId);
    } catch {}
  }

  if (projectId) {
    state.terminalTabCounters[projectId] = 0;
    const terminalSession = createTerminalTabSession(projectId);
    state.terminalSessions[projectId] = [terminalSession];
    state.activeTerminalTabIds[projectId] = terminalSession.tabId;
    state.ftpSessions[projectId] = blankFtpSession(projectId);
  }

  if (state.activeProject?.id === projectId) {
    applyTerminalSessionToState(projectId);
    applyFtpSessionToState(projectId);
  }
}

async function disconnectAllProjectConnections() {
  const projectIds = [...new Set([...Object.keys(state.terminalSessions), ...Object.keys(state.ftpSessions), state.rdpProjectId].filter(Boolean))];
  for (const projectId of projectIds) {
    await disconnectProjectConnections(projectId);
  }
}

