  els.backupClickHouseRestoreTarget.innerHTML = targets.map((connection) => `<option value="${escapeHtml(connection.id)}">${escapeHtml(connection.name)} - ClickHouse ${escapeHtml(connection.lastTest?.endpointIdentity?.version || '')} - disk ${escapeHtml(connection.clickhouseDestinationTrust?.diskName || '')}</option>`).join('');
