  els.backupInfluxDb3EnterpriseLegacyRestoreStatus.classList.add('hidden');
  els.backupInfluxDb3EnterpriseLegacyRestoreError.classList.toggle('hidden', targets.length > 0);
  els.backupInfluxDb3EnterpriseLegacyRestoreStartButton.disabled = true;
  if (!targets.length) els.backupInfluxDb3EnterpriseLegacyRestoreError.textContent = 'Enroll a tested stopped-cluster proof for an empty alternate Enterprise target before recovery.';
