      const plan = await window.deployerx.previewBackupScyllaManagerRestore({ recoveryPointId: point.id, targetConnectionId: els.backupScyllaManagerRestoreTarget.value, selectedTables: selection, dataCenterMapping: backupScyllaManagerList(els.backupScyllaManagerRestoreDcMapping.value) });
      els.backupScyllaManagerRestorePreview.innerHTML = `<div><span>Snapshot</span><strong>${escapeHtml(plan.snapshotTag)}</strong></div><div><span>Managed clusters</span><strong>${escapeHtml(`${plan.sourceManagedClusterId} to ${plan.targetManagedClusterId}`)}</strong></div><div><span>Compatibility</span><strong>${plan.managerCompatibility && plan.scyllaCompatibility ? 'Manager and ScyllaDB majors compatible' : 'Blocked'}</strong></div><div><span>Phases</span><strong>Schema, table re-dry-run, tables, native validation</strong></div><div><span>Scope</span><strong>${escapeHtml(plan.selection.join(', '))}</strong></div><div><span>Rollback</span><strong>Not supported; restored data is preserved</strong></div>`;
      els.backupScyllaManagerRestorePreview.classList.remove('hidden'); els.backupScyllaManagerRestoreStartButton.disabled = false;
