async function startBackupSearchSnapshotRestore(event) {
  event.preventDefault();
  const point = selectedRecoveryPoint();
  if (!point || els.backupSearchSnapshotRestoreStartButton.disabled) return;
  const confirmed = await confirmDangerousAction('Restore the native snapshot to an alternate namespace?', `${point.searchSnapshot?.snapshotName || point.jobName}\nEvery index and data stream will use the previewed prefix. Existing targets are never replaced.`, 'Restore snapshot');
  if (!confirmed) return;
  els.backupSearchSnapshotRestoreError.classList.add('hidden');
  els.backupSearchSnapshotRestoreStartButton.disabled = true;
  els.backupSearchSnapshotRestoreCancelButton.disabled = true;
  els.backupSearchSnapshotRestoreStatus.textContent = 'Starting native snapshot restore...';
  els.backupSearchSnapshotRestoreStatus.classList.remove('hidden');
  try {
    const started = await window.deployerx.startBackupSearchSnapshotRestore({ recoveryPointId: point.id, targetConnectionId: els.backupSearchSnapshotRestoreTarget.value, renamePrefix: els.backupSearchSnapshotRestorePrefix.value.trim(), confirmationText: 'RESTORE SEARCH ALTERNATE' });
    state.backupRecovery.activeRestore = started;
    els.backupSearchSnapshotRestoreCancelButton.disabled = false;
    els.backupSearchSnapshotRestoreStatus.textContent = 'Restoring and validating native snapshot resources...';
    const completed = await window.deployerx.waitBackupSearchSnapshotRestore(started.id);
    state.backupRecovery.activeRestore = completed;
    if (['failed', 'interrupted'].includes(completed.state)) throw new Error(completed.result?.error?.safeMessage || 'The search snapshot restore failed.');
    els.backupSearchSnapshotRestoreStatus.textContent = completed.state === 'canceled' ? 'Restore monitoring canceled. Inspect the alternate namespace; created resources were preserved.' : `${completed.validation?.restoredResources?.length || 0} resources restored and validated${completed.state === 'warning' ? ' with allocation warnings' : ''}.`;
    els.backupSearchSnapshotRestoreCancelButton.textContent = 'Done';
    await loadBackupActivity();
  } catch (error) {
    els.backupSearchSnapshotRestoreError.textContent = error.message || 'Could not restore the search snapshot.';
    els.backupSearchSnapshotRestoreError.classList.remove('hidden');
    els.backupSearchSnapshotRestoreStartButton.disabled = false;
  } finally {
    els.backupSearchSnapshotRestoreCancelButton.disabled = false;
  }
}

async function cancelOrCloseBackupSearchSnapshotRestore() {
  const active = state.backupRecovery.activeRestore;
  if (!active || ['succeeded', 'warning', 'failed', 'canceled', 'interrupted'].includes(active.state)) return closeBackupSearchSnapshotRestore();
  els.backupSearchSnapshotRestoreCancelButton.disabled = true;
  els.backupSearchSnapshotRestoreStatus.textContent = 'Canceling monitoring. Already-created alternate resources will be preserved...';
  try {
    state.backupRecovery.activeRestore = await window.deployerx.cancelBackupSearchSnapshotRestore(active.id);
    els.backupSearchSnapshotRestoreStatus.textContent = 'Restore canceled. Inspect the alternate namespace before deciding whether to remove created resources.';
    els.backupSearchSnapshotRestoreCancelButton.textContent = 'Done';
    await loadBackupActivity();
  } catch (error) {
    els.backupSearchSnapshotRestoreError.textContent = error.message || 'Could not cancel the search restore.';
    els.backupSearchSnapshotRestoreError.classList.remove('hidden');
  } finally {
    els.backupSearchSnapshotRestoreCancelButton.disabled = false;
  }
}

async function deleteExpiredBackupSearchSnapshot() {
  const point = selectedRecoveryPoint();
  if (!point) return;
  const plan = await window.deployerx.planBackupSearchSnapshotRetention(point.id);
  const confirmed = await confirmDangerousAction('Delete the expired native snapshot?', `${plan.repositoryName}/${plan.snapshotName}\nSnapshot UUID ${plan.snapshotUuid}\nThe authenticated DeployerX metadata recovery point will remain as deletion evidence.`, 'Delete native snapshot');
  if (!confirmed) return;
  const completed = await window.deployerx.executeBackupSearchSnapshotRetention(point.id, plan.planId);
  state.backupRecovery.points = state.backupRecovery.points.map((candidate) => candidate.id === point.id ? { ...candidate, retention: completed.recoveryPoint.retention } : candidate);
  els.backupSearchSnapshotRetentionButton.classList.add('hidden');
  renderBackupRecoveryPoints();
  showToast('Expired native snapshot deleted with ownership evidence recorded.');
}

function backupSearchSnapshotVerificationMode() {
  return els.backupSearchSnapshotVerificationForm.querySelector('input[name="backupSearchSnapshotVerificationMode"]:checked')?.value || 'search-snapshot-metadata';
}

function syncBackupSearchSnapshotVerificationMode() {
  const drill = backupSearchSnapshotVerificationMode() === 'search-snapshot-full-drill';
  els.backupSearchSnapshotVerificationTargetField.classList.toggle('hidden', !drill);
  els.backupSearchSnapshotVerificationTarget.required = drill;
  els.backupSearchSnapshotVerificationStartButton.textContent = drill ? 'Run full restore drill' : 'Run metadata validation';
  els.backupSearchSnapshotVerificationStartButton.disabled = drill && !els.backupSearchSnapshotVerificationTarget.value;
}

function closeBackupSearchSnapshotVerification() {
  const active = state.backupRecovery.activeVerification;
  if (active && !['succeeded', 'warning', 'failed', 'canceled', 'interrupted'].includes(active.state)) return;
  setModalVisible(false, els.backupSearchSnapshotVerificationModal);
}

async function openBackupSearchSnapshotVerification() {
  const point = selectedRecoveryPoint();
  if (!point) return;
  if (window.deployerx?.listBackupSearchSnapshotConnections) state.backupSearchSnapshotConnections = await window.deployerx.listBackupSearchSnapshotConnections();
  const targets = searchSnapshotReadyConnections(point);
  els.backupSearchSnapshotVerificationSummary.textContent = `${point.searchSnapshot?.snapshotName || point.jobName} - choose the evidence level`;
  els.backupSearchSnapshotVerificationTarget.innerHTML = targets.map((connection) => `<option value="${escapeHtml(connection.id)}">${escapeHtml(connection.name)} - ${escapeHtml(connection.lastTest?.endpointIdentity?.clusterName || 'verified cluster')}</option>`).join('');
  els.backupSearchSnapshotVerificationForm.querySelector('input[value="search-snapshot-metadata"]').checked = true;
  els.backupSearchSnapshotVerificationError.classList.add('hidden');
  els.backupSearchSnapshotVerificationStatus.classList.add('hidden');
  els.backupSearchSnapshotVerificationStatus.textContent = '';
  els.backupSearchSnapshotVerificationCancelButton.disabled = false;
  els.backupSearchSnapshotVerificationCancelButton.textContent = 'Cancel';
  state.backupRecovery.activeVerification = null;
  syncBackupSearchSnapshotVerificationMode();
  setModalVisible(true, els.backupSearchSnapshotVerificationModal);
}

async function startBackupSearchSnapshotVerification(event) {
  event.preventDefault();
  const point = selectedRecoveryPoint();
  const mode = backupSearchSnapshotVerificationMode();
  const drill = mode === 'search-snapshot-full-drill';
  if (!point) return;
  if (drill) {
    const confirmed = await confirmDangerousAction('Run a full alternate search recovery drill?', `${point.searchSnapshot?.snapshotName || point.jobName}\nDeployerX will restore a deterministic isolated namespace, validate it, and delete only resources whose UUID ownership is proven.`, 'Run recovery drill');
    if (!confirmed) return;
  }
  els.backupSearchSnapshotVerificationError.classList.add('hidden');
  els.backupSearchSnapshotVerificationStartButton.disabled = true;
  els.backupSearchSnapshotVerificationCancelButton.disabled = true;
  els.backupSearchSnapshotVerificationStatus.textContent = drill ? 'Starting isolated full restore drill...' : 'Inspecting exact native snapshot metadata and primary shards...';
  els.backupSearchSnapshotVerificationStatus.classList.remove('hidden');
  try {
    const started = await window.deployerx.startBackupSearchSnapshotVerification({ recoveryPointId: point.id, mode, targetConnectionId: drill ? els.backupSearchSnapshotVerificationTarget.value : null, confirmationText: drill ? 'RUN SEARCH RECOVERY DRILL' : '' });
    state.backupRecovery.activeVerification = started;
    els.backupSearchSnapshotVerificationCancelButton.disabled = false;
    const completed = await window.deployerx.waitBackupSearchSnapshotVerification(started.id);
    state.backupRecovery.activeVerification = completed;
    if (['failed', 'interrupted'].includes(completed.state)) throw new Error(completed.result?.error?.safeMessage || 'The search recovery test failed.');
    els.backupSearchSnapshotVerificationStatus.textContent = completed.state === 'canceled' ? 'Recovery test canceled. A full drill may require alternate namespace inspection.' : drill ? `${completed.evidence?.restoredResources?.length || 0} resources restored, validated, and removed.` : `${completed.evidence?.shards?.successful || 0} of ${completed.evidence?.shards?.total || 0} primary shards validated from native metadata.`;
    state.backupRecovery.verificationRuns = [completed, ...state.backupRecovery.verificationRuns.filter((run) => run.id !== completed.id)];
    renderBackupRecoveryPoints();
    els.backupSearchSnapshotVerificationCancelButton.textContent = 'Done';
    await loadBackupActivity();
  } catch (error) {
    els.backupSearchSnapshotVerificationError.textContent = error.message || 'Could not test search snapshot recovery.';
    els.backupSearchSnapshotVerificationError.classList.remove('hidden');
    els.backupSearchSnapshotVerificationStartButton.disabled = false;
  } finally {
    els.backupSearchSnapshotVerificationCancelButton.disabled = false;
  }
}

async function cancelOrCloseBackupSearchSnapshotVerification() {
  const active = state.backupRecovery.activeVerification;
  if (!active || ['succeeded', 'warning', 'failed', 'canceled', 'interrupted'].includes(active.state)) return closeBackupSearchSnapshotVerification();
  els.backupSearchSnapshotVerificationCancelButton.disabled = true;
  els.backupSearchSnapshotVerificationStatus.textContent = 'Canceling recovery test...';
  try {
    state.backupRecovery.activeVerification = await window.deployerx.cancelBackupSearchSnapshotVerification(active.id);
    els.backupSearchSnapshotVerificationStatus.textContent = active.mode === 'search-snapshot-full-drill' ? 'Drill canceled. Inspect the alternate namespace before cleanup.' : 'Metadata validation canceled.';
    els.backupSearchSnapshotVerificationCancelButton.textContent = 'Done';
    await loadBackupActivity();
  } catch (error) {
    els.backupSearchSnapshotVerificationError.textContent = error.message || 'Could not cancel the search recovery test.';
    els.backupSearchSnapshotVerificationError.classList.remove('hidden');
  } finally {
    els.backupSearchSnapshotVerificationCancelButton.disabled = false;
  }
}

function verificationMode() {
  return els.backupVerificationForm.querySelector('input[name="backupVerificationMode"]:checked')?.value || 'sample-restore';
}

function syncBackupVerificationMode() {
  els.backupVerificationSampleField.classList.toggle('hidden', verificationMode() === 'checksum');
}

function closeBackupVerification() {
  if (state.backupRecovery.activeVerification && !['succeeded', 'warning', 'failed', 'canceled'].includes(state.backupRecovery.activeVerification.state)) return;
  setModalVisible(false, els.backupVerificationModal);
}

function openBackupVerification() {
  const point = selectedRecoveryPoint();
  if (!point) return;
  const copies = (point.repositoryCopies || []).filter((copy) => copy.state === 'available');
  els.backupVerificationSummary.textContent = recoveryDatabaseEngine(point) === 'redis' ? `${point.jobName} - Redis authenticated artifact test` : point.jobName;
  els.backupVerificationRepository.innerHTML = copies.map((copy) => `<option value="${escapeHtml(copy.repositoryId)}">${escapeHtml(copy.repositoryName || 'Repository copy')}</option>`).join('');
  els.backupVerificationError.classList.add('hidden');
  els.backupVerificationStatus.classList.add('hidden');
  els.backupVerificationStatus.textContent = '';
  els.backupVerificationStartButton.disabled = copies.length === 0;
  els.backupVerificationCancelButton.disabled = false;
  els.backupVerificationCancelButton.textContent = 'Cancel';
  state.backupRecovery.activeVerification = null;
  syncBackupVerificationMode();
  setModalVisible(true, els.backupVerificationModal);
}

async function startBackupVerification(event) {
  event.preventDefault();
  const recovery = state.backupRecovery;
  const mode = verificationMode();
  els.backupVerificationError.classList.add('hidden');
  els.backupVerificationStartButton.disabled = true;
  els.backupVerificationCancelButton.disabled = true;
  els.backupVerificationStatus.textContent = mode === 'checksum' ? 'Verifying every recovery point in this repository...' : 'Restoring and validating the deterministic file sample...';
  els.backupVerificationStatus.classList.remove('hidden');
  try {
    const started = await window.deployerx.startBackupVerification({
      mode,
      repositoryId: els.backupVerificationRepository.value,
      recoveryPointId: mode === 'sample-restore' ? recovery.selectedPointId : null,
      samplePercent: mode === 'sample-restore' ? Number(els.backupVerificationSamplePercent.value) : null
    });
    recovery.activeVerification = started;
    const completed = await window.deployerx.waitBackupVerification(started.id);
    recovery.activeVerification = completed;
    if (completed.state === 'failed') throw new Error(completed.result?.error?.safeMessage || 'Backup verification failed.');
    els.backupVerificationStatus.textContent = `${completed.result?.filesVerified || 0} files and ${formatBytes(completed.result?.bytesVerified || 0)} verified`;
    recovery.verificationRuns = [completed, ...recovery.verificationRuns.filter((run) => run.id !== completed.id)];
    renderBackupRecoveryPoints();
    els.backupVerificationCancelButton.textContent = 'Done';
  } catch (error) {
    els.backupVerificationError.textContent = error.message || 'Could not verify backup data.';
    els.backupVerificationError.classList.remove('hidden');
    els.backupVerificationStartButton.disabled = false;
  } finally {
    els.backupVerificationCancelButton.disabled = false;
  }
}

async function loadBackupRecoveryPoints(options = {}) {
  if (!window.deployerx?.listBackupRecoveryPoints || pendingActions.has('backup:recovery-points:list')) return;
  const append = Boolean(options.append);
  if (append && !state.backupRecovery.pointsNextCursor) return;
  pendingActions.add('backup:recovery-points:list');
  try {
    const result = await window.deployerx.listBackupRecoveryPoints({
      pageSize: 100,
      cursor: append ? state.backupRecovery.pointsNextCursor : null
    });
    state.backupRecovery.points = append ? [...state.backupRecovery.points, ...result.items] : result.items;
    state.backupRecovery.pointsNextCursor = result.nextCursor;
    state.backupRecovery.totalPoints = result.total;
    if (!append) {
      const [verifications, neo4jVerifications, clickHouseVerifications, influxDbVerifications, influxDb3CoreVerifications, cockroachDbVerifications, searchVerifications, managerVerifications] = await Promise.all([
        window.deployerx?.listBackupVerificationRuns ? window.deployerx.listBackupVerificationRuns({ limit: 100 }) : Promise.resolve([]),
        window.deployerx?.listBackupNeo4jVerificationRuns ? window.deployerx.listBackupNeo4jVerificationRuns({ limit: 100 }) : Promise.resolve([]),
        window.deployerx?.listBackupClickHouseVerificationRuns ? window.deployerx.listBackupClickHouseVerificationRuns({ limit: 100 }) : Promise.resolve([]),
        window.deployerx?.listBackupInfluxDbVerificationRuns ? window.deployerx.listBackupInfluxDbVerificationRuns({ limit: 100 }) : Promise.resolve([]),
        window.deployerx?.listBackupInfluxDb3CoreVerificationRuns ? window.deployerx.listBackupInfluxDb3CoreVerificationRuns({ limit: 100 }) : Promise.resolve([]),
        window.deployerx?.listBackupCockroachDbVerificationRuns ? window.deployerx.listBackupCockroachDbVerificationRuns({ limit: 100 }) : Promise.resolve([]),
        window.deployerx?.listBackupSearchSnapshotVerificationRuns ? window.deployerx.listBackupSearchSnapshotVerificationRuns({ limit: 100 }) : Promise.resolve([]),
        window.deployerx?.listBackupScyllaManagerVerificationRuns ? window.deployerx.listBackupScyllaManagerVerificationRuns({ limit: 100 }) : Promise.resolve([])
      ]);
      state.backupRecovery.verificationRuns = [...new Map([...verifications, ...neo4jVerifications, ...clickHouseVerifications, ...influxDbVerifications, ...influxDb3CoreVerifications, ...cockroachDbVerifications, ...searchVerifications, ...managerVerifications].map((run) => [run.id, run])).values()];
    }
  if (!state.backupRecovery.points.some((point) => point.id === state.backupRecovery.selectedPointId)) {
      state.backupRecovery.selectedPointId = state.backupRecovery.points[0]?.id || '';
      state.backupRecovery.selectedPaths.clear();
    }
    renderBackupRecoveryPoints();
    if (!append && state.backupRecovery.selectedPointId) await loadBackupRecoveryDirectory('', { resetSearch: true });
    if (!state.backupRecovery.selectedPointId) {
      state.backupRecovery.entries = [];
      state.backupRecovery.totalEntries = 0;
      renderBackupRecoveryEntries();
    }
  } finally {
    pendingActions.delete('backup:recovery-points:list');
  }
}

async function loadBackupRecoveryDirectory(path, options = {}) {
  const recovery = state.backupRecovery;
  const pointId = recovery.selectedPointId;
  if (!pointId || !window.deployerx?.browseBackupSnapshot) return;
  if (isDatabaseRecoveryPoint()) {
    recovery.mode = 'database';
    recovery.path = '';
    recovery.entries = [];
    recovery.entriesNextCursor = null;
    recovery.totalEntries = 1;
    recovery.selectedPaths.clear();
    renderBackupRecoveryEntries();
    return;
  }
  const append = Boolean(options.append);
  const actionKey = `backup:snapshot:browse:${pointId}`;
  if (pendingActions.has(actionKey) || (append && !recovery.entriesNextCursor)) return;
  pendingActions.add(actionKey);
  try {
    const result = await window.deployerx.browseBackupSnapshot({
      recoveryPointId: pointId,
      path,
      pageSize: 100,
      cursor: append ? recovery.entriesNextCursor : null
    });
    if (state.backupRecovery.selectedPointId !== pointId) return;
    recovery.mode = 'browse';
    recovery.path = result.path;
    recovery.breadcrumbs = result.breadcrumbs;
    recovery.entries = append ? [...recovery.entries, ...result.items] : result.items;
    recovery.entriesNextCursor = result.nextCursor;
    recovery.totalEntries = result.total;
    if (options.resetSearch !== false) {
      recovery.searchQuery = '';
      els.backupRecoverySearchInput.value = '';
    }
    renderBackupRecoveryEntries();
  } finally {
    pendingActions.delete(actionKey);
  }
}

async function searchBackupRecovery(event) {
  event?.preventDefault();
  const recovery = state.backupRecovery;
  const pointId = recovery.selectedPointId;
  const query = els.backupRecoverySearchInput.value.trim();
  if (!query) return loadBackupRecoveryDirectory(recovery.path || '', { resetSearch: true });
  const actionKey = `backup:snapshot:search:${pointId}`;
  if (!pointId || !window.deployerx?.searchBackupSnapshot || pendingActions.has(actionKey)) return;
  pendingActions.add(actionKey);
  try {
    const result = await window.deployerx.searchBackupSnapshot({
      recoveryPointId: pointId,
      query,
      type: els.backupRecoverySearchType.value,
      pageSize: 100,
      cursor: null
    });
    if (state.backupRecovery.selectedPointId !== pointId) return;
    recovery.mode = 'search';
    recovery.searchQuery = result.query;
    recovery.searchType = result.type;
    recovery.entries = result.items;
    recovery.entriesNextCursor = result.nextCursor;
    recovery.totalEntries = result.total;
    renderBackupRecoveryEntries();
  } finally {
    pendingActions.delete(actionKey);
  }
}

async function loadMoreBackupRecoveryEntries() {
  const recovery = state.backupRecovery;
  if (recovery.mode === 'browse') return loadBackupRecoveryDirectory(recovery.path, { append: true, resetSearch: false });
  const pointId = recovery.selectedPointId;
  const actionKey = `backup:snapshot:search:${pointId}`;
  if (!pointId || !recovery.entriesNextCursor || pendingActions.has(actionKey)) return;
  pendingActions.add(actionKey);
  try {
    const result = await window.deployerx.searchBackupSnapshot({
      recoveryPointId: pointId,
      query: recovery.searchQuery,
      type: recovery.searchType,
      pageSize: 100,
      cursor: recovery.entriesNextCursor
    });
    if (state.backupRecovery.selectedPointId !== pointId) return;
    recovery.entries.push(...result.items);
    recovery.entriesNextCursor = result.nextCursor;
    recovery.totalEntries = result.total;
    renderBackupRecoveryEntries();
  } finally {
    pendingActions.delete(actionKey);
  }
}

function closeBackupFileVersions() {
  setModalVisible(false, els.backupFileVersionsModal);
}

function renderBackupFileVersions(path, result) {
  els.backupFileVersionsPath.textContent = path;
  els.backupFileVersionsPath.classList.add('backup-file-versions-path');
  els.backupFileVersionsEmpty.classList.toggle('hidden', result.versions.length > 0);
  els.backupFileVersionsList.innerHTML = result.versions.map((version) => {
    const detail = version.availability !== 'available'
      ? 'Repository copy unavailable'
      : version.exists ? `${version.entry.type}${version.entry.type === 'file' ? ` - ${formatBytes(version.entry.sizeBytes)}` : ''}` : 'Not present';
    return `
      <div class="backup-file-version-row">
        <strong>${escapeHtml(formatDateTime(version.capturedTo))}</strong>
        <small>${escapeHtml(detail)}</small>
        <span class="backup-file-version-change ${escapeHtml(version.change)}">${escapeHtml(version.change.replace('-', ' '))}</span>
      </div>`;
  }).join('');
}

async function openBackupFileVersions(path) {
  const pointId = state.backupRecovery.selectedPointId;
  if (!pointId || !window.deployerx?.listBackupFileVersions) return;
  els.backupFileVersionsPath.textContent = path;
  els.backupFileVersionsList.innerHTML = '<div class="settings-muted">Loading versions...</div>';
  els.backupFileVersionsEmpty.classList.add('hidden');
  setModalVisible(true, els.backupFileVersionsModal);
  const result = await window.deployerx.listBackupFileVersions({ recoveryPointId: pointId, path });
  state.backupRecovery.versions = result.versions;
  renderBackupFileVersions(path, result);
}

function backupJobMode() {
  return els.backupJobForm.querySelector('input[name="backupJobMode"]:checked')?.value || 'incremental';
}

function selectedBackupJobRepositoryIds() {
  return Array.from(els.backupJobRepositories.querySelectorAll('[data-backup-job-repository]:checked')).map((input) => input.value);
}

function backupJobSchedule() {
  const type = els.backupJobScheduleType.value;
  if (type === 'manual') return { type };
  const schedule = { type, timezone: els.backupJobTimezone.value };
  if (type === 'interval') schedule.intervalMinutes = Number(els.backupJobIntervalMinutes.value);
  if (type === 'cron') schedule.expression = els.backupJobCronExpression.value.trim();
  if (type === 'hourly') schedule.minute = Number(els.backupJobHourlyMinute.value);
  if (type === 'daily') schedule.time = els.backupJobDailyTime.value;
  if (type === 'weekly') {
    schedule.daysOfWeek = els.backupJobWeekdays.filter((input) => input.checked).map((input) => Number(input.value));
    schedule.time = els.backupJobWeeklyTime.value;
  }
  if (type === 'monthly') {
    schedule.dayOfMonth = Number(els.backupJobMonthlyDay.value);
    schedule.time = els.backupJobMonthlyTime.value;
  }
  if (schedule.timezone !== 'UTC' && type !== 'interval') {
    schedule.dstBehavior = { nonexistentTime: els.backupJobDstNonexistent.value, ambiguousTime: els.backupJobDstAmbiguous.value };
  }
  schedule.missedRun = { behavior: els.backupJobMissedRun.value, graceMinutes: Number(els.backupJobMissedGrace.value) };
  const maintenanceWindows = els.backupJobMaintenanceEnabled.checked ? [{
    daysOfWeek: els.backupJobMaintenanceDays.filter((input) => input.checked).map((input) => Number(input.value)),
    startTime: els.backupJobMaintenanceStart.value,
    endTime: els.backupJobMaintenanceEnd.value
  }] : [];
  const blackouts = els.backupJobBlackoutEnabled.checked ? [{
    startsAt: backupUtcDateTime(els.backupJobBlackoutStart.value),
    endsAt: backupUtcDateTime(els.backupJobBlackoutEnd.value)
  }] : [];
  schedule.executionCalendar = {
    maintenanceWindows,
    outsideMaintenanceBehavior: els.backupJobMaintenanceBehavior.value,
    blackouts,
    blackoutBehavior: els.backupJobBlackoutBehavior.value
  };
  return schedule;
}

function backupUtcDateTime(value) {
  if (!value) return '';
  const normalized = value.length === 16 ? `${value}:00Z` : `${value}Z`;
  const date = new Date(normalized);
  return Number.isFinite(date.getTime()) ? date.toISOString() : '';
}

function backupScheduleSummary(schedule = {}) {
  const type = schedule.type === 'on-demand' ? 'manual' : schedule.type || 'manual';
  if (type === 'manual') return 'Manual only';
  if (type === 'interval') return `Every ${schedule.intervalMinutes} ${Number(schedule.intervalMinutes) === 1 ? 'minute' : 'minutes'}`;
  const timezone = schedule.timezone || 'UTC';
  if (type === 'cron') return `Cron ${schedule.expression} ${timezone}`;
  if (type === 'hourly') return `Hourly at :${String(schedule.minute ?? 0).padStart(2, '0')} ${timezone}`;
  if (type === 'daily') return `Daily at ${schedule.time} ${timezone}`;
  if (type === 'weekly') {
    const names = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return `${(schedule.daysOfWeek || []).map((day) => names[day]).filter(Boolean).join(', ')} at ${schedule.time} ${timezone}`;
  }
  if (type === 'monthly') return `Monthly day ${schedule.dayOfMonth} at ${schedule.time} ${timezone}`;
  return 'Schedule unavailable';
}

function backupRetentionPolicy(schedule = backupJobSchedule()) {
  return {
    timezone: schedule.timezone || 'UTC',
    keepLast: Number(els.backupJobKeepLast.value),
    hourly: Number(els.backupJobKeepHourly.value),
    daily: Number(els.backupJobKeepDaily.value),
    weekly: Number(els.backupJobKeepWeekly.value),
    monthly: Number(els.backupJobKeepMonthly.value),
    yearly: Number(els.backupJobKeepYearly.value)
  };
}

function backupRetentionSummary(policy = {}) {
  const parts = [`last ${Number(policy.keepLast ?? 30)}`];
  for (const rule of ['hourly', 'daily', 'weekly', 'monthly', 'yearly']) {
    const value = Number(policy[rule] || 0);
    if (value > 0) parts.push(`${value} ${rule}`);
  }
  return `Retain ${parts.join(', ')}`;
}

function backupRetentionMatchesSummary(retention = {}) {
  const labels = { 'last-n': 'Last-N', hourly: 'Hourly', daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', 'legal-hold': 'Legal hold' };
  const matches = (retention?.ruleMatches || []).map((rule) => labels[rule] || rule);
  return matches.length ? `Retained by ${matches.join(', ')}` : retention?.deletionEligible ? 'Retention elapsed' : '';
}

function syncBackupJobScheduleFields() {
  const type = els.backupJobScheduleType.value;
  const recurring = type !== 'manual';
  els.backupJobScheduleFields.forEach((field) => field.classList.toggle('hidden', field.dataset.backupJobScheduleFields !== type));
  els.backupJobTimezoneField.classList.toggle('hidden', !recurring);
  els.backupJobSchedulePolicy.classList.toggle('hidden', !recurring);
  els.backupJobDstPolicy.classList.toggle('hidden', !recurring || type === 'interval' || els.backupJobTimezone.value === 'UTC');
  els.backupJobMaintenanceFields.classList.toggle('hidden', !els.backupJobMaintenanceEnabled.checked);
  els.backupJobBlackoutFields.classList.toggle('hidden', !els.backupJobBlackoutEnabled.checked);
  els.backupJobBandwidthWindowFields.classList.toggle('hidden', !els.backupJobBandwidthWindowEnabled.checked);
}

function populateBackupJobTimezones() {
  const zones = typeof Intl.supportedValuesOf === 'function' ? Intl.supportedValuesOf('timeZone') : [];
  const values = ['UTC', ...zones.filter((zone) => zone !== 'UTC')];
  els.backupJobTimezone.innerHTML = values.map((zone) => `<option value="${escapeHtml(zone)}">${escapeHtml(zone)}</option>`).join('');
}

function renderBackupJobs() {
  const hasJobs = state.backupJobs.length > 0;
  els.backupJobList.classList.toggle('hidden', !hasJobs);
  els.backupJobsEmpty.classList.toggle('hidden', hasJobs);
  els.backupJobList.innerHTML = state.backupJobs.map((job) => {
    const sourceName = job.source?.name || 'Unavailable source';
    const repositoryCount = job.repositories?.length || 0;
    const mode = job.policy?.backupMode === 'full' ? 'Full' : job.policy?.backupMode === 'differential' ? 'Differential' : job.policy?.backupMode === 'native' ? 'Manager native' : 'Incremental';
    const enabled = job.state === 'enabled';
    const paused = job.state === 'paused';
    const disabled = job.state === 'disabled';
    const status = paused ? 'Paused' : disabled ? 'Disabled' : job.ready ? 'Ready' : 'Needs attention';
    const run = latestBackupRun(job.id);
    const active = isActiveBackupRun(run);
    const progress = run?.progress || {};
    const knownBytes = Math.max(Number(progress.sourceBytes || 0), Number(progress.bytesRead || 0), 1);
    const processedBytes = Math.min(Number(progress.bytesRead || 0), knownBytes);
    const runDetail = backupRunDetail(run);
    const cadence = backupScheduleSummary(job.policy?.schedule);
    const retention = backupRetentionSummary(job.policy?.retention);
    const deferredUntil = job.scheduleState?.lastCalendarDecision?.action === 'defer' ? job.scheduleState?.nextDispatchAttemptAt : null;
    const schedule = deferredUntil
      ? `${cadence} - Deferred until ${formatDateTime(deferredUntil)}`
      : job.nextRunAt ? `${cadence} - Next ${formatDateTime(job.nextRunAt)}` : cadence;
    const primaryAction = active
      ? `<button class="button outline danger compact icon-only" type="button" data-backup-cancel-run="${escapeHtml(run.id)}" title="Cancel backup" aria-label="Cancel backup"><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-stop"></use></svg></button>`
      : run?.resumable
        ? `<button class="button outline compact icon-only" type="button" data-backup-resume-run="${escapeHtml(run.id)}" title="Resume interrupted backup" aria-label="Resume interrupted backup" ${enabled ? '' : 'disabled'}><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-refresh"></use></svg></button>`
        : ['failed', 'canceled'].includes(run?.state)
          ? `<button class="button outline compact icon-only" type="button" data-backup-retry-run="${escapeHtml(run.id)}" title="Retry backup" aria-label="Retry backup" ${enabled && job.ready ? '' : 'disabled'}><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-refresh"></use></svg></button>`
          : `<button class="button solid compact icon-only" type="button" data-backup-run-job="${escapeHtml(job.id)}" title="Run backup" aria-label="Run backup" ${enabled && job.ready ? '' : 'disabled'}><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-play"></use></svg></button>`;
    const stateAction = paused
      ? `<button class="button outline compact icon-only" type="button" data-backup-job-resume="${escapeHtml(job.id)}" title="Resume schedule" aria-label="Resume schedule"><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-play"></use></svg></button>`
      : `<button class="button outline compact icon-only" type="button" data-backup-job-pause="${escapeHtml(job.id)}" title="Pause schedule" aria-label="Pause schedule" ${enabled ? '' : 'disabled'}><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-pause"></use></svg></button>`;
    const nativeScheduleAction = job.source?.adapterId === 'deployerx.database.cockroachdb'
      ? `<button class="button outline compact icon-only" type="button" data-backup-cockroachdb-schedule="${escapeHtml(job.id)}" title="Configure native UTC schedule" aria-label="Configure native UTC schedule"><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-settings"></use></svg></button>`
      : '';
    const actions = `${primaryAction}${stateAction}${nativeScheduleAction}
      <button class="button outline compact icon-only" type="button" data-backup-job-clone="${escapeHtml(job.id)}" title="Clone job" aria-label="Clone job"><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-copy"></use></svg></button>
      <button class="button outline compact icon-only" type="button" data-backup-job-disable="${escapeHtml(job.id)}" title="Disable job" aria-label="Disable job" ${disabled || active ? 'disabled' : ''}><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-power"></use></svg></button>
      <button class="button outline danger compact icon-only" type="button" data-backup-job-delete="${escapeHtml(job.id)}" title="${disabled ? 'Delete job' : 'Disable job before deleting'}" aria-label="Delete job" ${disabled && !active ? '' : 'disabled'}><svg class="button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-trash"></use></svg></button>`;
    return `
      <div class="backup-source-row backup-job-row" data-backup-job-id="${escapeHtml(job.id)}">
        <span class="backup-source-icon" aria-hidden="true"><svg class="button-icon" viewBox="0 0 24 24" focusable="false"><use href="#icon-save"></use></svg></span>
        <span class="backup-source-copy"><strong>${escapeHtml(job.name)}</strong><small>${escapeHtml(sourceName)} - ${mode} - ${repositoryCount} ${repositoryCount === 1 ? 'destination' : 'destinations'}</small><small>${escapeHtml(retention)}</small>${runDetail ? `<small class="backup-job-run-detail">${escapeHtml(runDetail)}</small>` : ''}${active ? `<progress class="backup-job-progress" max="${knownBytes}" value="${processedBytes}" aria-label="Backup byte progress"></progress>` : ''}</span>
        <span class="backup-job-row-status ${paused || disabled ? 'inactive' : job.ready ? 'ready' : 'attention'}">${status}</span>
        <span class="backup-job-schedule">${escapeHtml(schedule)}</span>
        <span class="backup-job-actions">${actions}</span>
      </div>`;
  }).join('');
  renderBackupWorkerStatus();
  syncBackupRunPolling();
}

function renderBackupWorkerStatus() {
  if (!els.backupWorkerStatus) return;
  const worker = state.backupWorker;
  els.backupWorkerStatus.classList.toggle('online', Boolean(worker?.online));
  els.backupWorkerStatus.classList.toggle('offline', !worker?.online);
  els.backupWorkerStatus.textContent = worker?.online
    ? `Background worker online${worker.nextRunAt ? ` - Next ${formatDateTime(worker.nextRunAt)}` : ''}`
    : 'Background worker offline';
}

async function loadBackupJobs() {
  if (!window.deployerx?.listBackupJobs || pendingActions.has('backup:jobs:list')) return;
  pendingActions.add('backup:jobs:list');
  try {
    const [jobs, runs, worker] = await Promise.all([
      window.deployerx.listBackupJobs(),
      window.deployerx.listBackupRuns ? window.deployerx.listBackupRuns({ limit: 500 }) : Promise.resolve([]),
      window.deployerx.getBackupWorkerStatus ? window.deployerx.getBackupWorkerStatus() : Promise.resolve(null)
    ]);
    state.backupJobs = jobs;
    state.backupRuns = runs;
    state.backupWorker = worker;
    renderBackupJobs();
  } finally {
    pendingActions.delete('backup:jobs:list');
  }
}

function isActiveBackupRun(run) {
  return Boolean(run && ['queued', 'preparing', 'running', 'verifying'].includes(run.state));
}

function latestBackupRun(jobId) {
  return state.backupRuns
    .filter((run) => run.jobId === jobId)
    .sort((left, right) => String(right.createdAt || '').localeCompare(String(left.createdAt || '')))[0] || null;
}

function backupRunDetail(run) {
  if (!run) return '';
  const progress = run.progress || {};
  const labels = {
    queued: 'Queued', preparing: 'Preparing', running: 'Running', verifying: 'Verifying',
    succeeded: 'Succeeded', warning: 'Completed with warnings', failed: 'Failed', canceled: 'Canceled', interrupted: 'Interrupted'
  };
  const parts = [labels[run.state] || run.state];
  const priority = run.priority;
  if (run.state === 'queued' && priority) parts.push(`${priority[0].toUpperCase()}${priority.slice(1)} priority`);
  if (run.state === 'interrupted' && run.retryState?.notBefore) parts.push(`Retry ${formatDateTime(run.retryState.notBefore)}`);
  if (Number(progress.bytesRead || 0) > 0) parts.push(formatBytes(progress.bytesRead));
  if (isActiveBackupRun(run) && Number(progress.throughputBytesPerSecond || 0) > 0) parts.push(`${formatBytes(progress.throughputBytesPerSecond)}/s`);
  if (isActiveBackupRun(run) && Number(progress.bandwidthLimitBytesPerSecond || 0) > 0) parts.push(`Limited to ${formatBytes(progress.bandwidthLimitBytesPerSecond)}/s`);
  if (Number(progress.repositoryCount || 0) > 1) parts.push(`${Number(progress.committedRepositories || 0)} of ${progress.repositoryCount} destinations`);
  return parts.join(' - ');
}

function backupActivityStateLabel(value) {
  const labels = {
    queued: 'Queued', preparing: 'Preparing', running: 'Running', verifying: 'Verifying', validating: 'Validating',
    succeeded: 'Succeeded', warning: 'Completed with warnings', failed: 'Failed', canceled: 'Canceled', interrupted: 'Interrupted'
  };
  return labels[value] || String(value || 'Unknown');
}

function backupActivityStateClass(value) {
  if (value === 'succeeded') return 'success';
  if (value === 'warning') return 'warning';
  if (['failed', 'canceled', 'interrupted'].includes(value)) return 'danger';
  return ['queued', 'preparing', 'running', 'verifying', 'validating'].includes(value) ? 'active' : 'neutral';
}

function isActiveRestoreRun(run) {
  return Boolean(run && ['queued', 'preparing', 'running', 'validating'].includes(run.state));
}

function isActiveVerificationRun(run) {
  return Boolean(run && ['queued', 'running'].includes(run.state));
}

function backupVerificationModeLabel(run, compact = false) {
  if (run?.mode === 'mongodb-recovery-drill') return compact ? 'MongoDB drill' : 'MongoDB isolated recovery drill';
  if (run?.mode === 'neo4j-metadata') return compact ? 'Neo4j metadata' : 'Neo4j chain and source identity validation';
  if (run?.mode === 'neo4j-full-drill') return compact ? 'Neo4j drill' : 'Neo4j full alternate-target drill';
  if (run?.mode === 'clickhouse-metadata') return compact ? 'ClickHouse metadata' : 'ClickHouse chain, source, and disk identity validation';
  if (run?.mode === 'clickhouse-full-drill') return compact ? 'ClickHouse drill' : 'ClickHouse full alternate-database drill';
  if (run?.mode === 'influxdb-metadata') return compact ? 'InfluxDB metadata' : 'InfluxDB media, source, scope, and retention validation';
  if (run?.mode === 'influxdb-full-drill') return compact ? 'InfluxDB drill' : 'InfluxDB full alternate-instance drill';
  if (run?.mode === 'influxdb3-core-metadata') return compact ? 'Core metadata' : `InfluxDB 3 Core ${influxDb3CoreStoreUi(influxDb3CoreRunObjectStore(run)).label} media and source validation`;
  if (run?.mode === 'influxdb3-core-full-drill') return compact ? 'Core drill' : `InfluxDB 3 Core stopped-target ${influxDb3CoreStoreUi(influxDb3CoreRunObjectStore(run)).label} drill`;
  if (run?.mode === 'influxdb3-enterprise-metadata') return compact ? 'Enterprise metadata' : 'InfluxDB 3 Enterprise upgraded-native metadata recovery test';
  if (run?.mode === 'influxdb3-enterprise-legacy-metadata') return compact ? 'Enterprise legacy metadata' : 'InfluxDB 3 Enterprise legacy filesystem metadata validation';
  if (run?.mode === 'influxdb3-enterprise-legacy-full-drill') return compact ? 'Enterprise legacy drill' : 'Full stopped-cluster Enterprise legacy drill';
  if (run?.mode === 'cockroachdb-metadata') return compact ? 'CockroachDB metadata' : 'CockroachDB chain, cluster, topology, and destination validation';
  if (run?.mode === 'cockroachdb-full-drill') return compact ? 'CockroachDB drill' : 'CockroachDB full alternate-database recovery drill';
  if (run?.mode === 'search-snapshot-metadata') return compact ? 'Search metadata' : 'Search native metadata validation';
  if (run?.mode === 'search-snapshot-full-drill') return compact ? 'Search drill' : 'Search full restore drill';
  if (run?.mode === 'scylla-manager-metadata') return compact ? 'Manager metadata' : 'Manager task, run, snapshot, and catalog validation';
  if (run?.mode === 'scylla-manager-full-drill') return compact ? 'Manager drill' : 'Manager full alternate-cluster drill';
  if (run?.mode === 'sample-restore') return compact ? 'Sample' : 'Sample restore';
  return 'Checksum';
}

function backupActivityDuration(startedAt, finishedAt, updatedAt) {
  const start = Date.parse(startedAt || '');
  const finish = Date.parse(finishedAt || updatedAt || '');
  return Number.isFinite(start) && Number.isFinite(finish) ? Math.max(0, finish - start) : 0;
}

function formatBackupDuration(value) {
  const milliseconds = Math.max(0, Number(value || 0));
  if (!milliseconds) return '-';
  const seconds = Math.max(1, Math.round(milliseconds / 1000));
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  const remainingSeconds = seconds % 60;
  if (minutes < 60) return remainingSeconds ? `${minutes}m ${remainingSeconds}s` : `${minutes}m`;
  const hours = Math.floor(minutes / 60);
  const remainingMinutes = minutes % 60;
  return remainingMinutes ? `${hours}h ${remainingMinutes}m` : `${hours}h`;
}

function formatBackupMetricBytes(value) {
  return Number(value || 0) > 0 ? formatBytes(value) : '0 B';
}

function backupActivityEntries(filter = state.backupActivity.filter) {
  const jobs = new Map(state.backupJobs.map((job) => [job.id, job]));
  const backups = state.backupRuns.map((run) => {
    const progress = run.progress || {};
    const metrics = run.metrics || {};
    const scannedBytes = Number(metrics.scannedBytes ?? progress.sourceBytes ?? 0);
    const uploadedBytes = Number(metrics.uploadedBytes ?? progress.uploadedBytes ?? 0);
    const reusedBytes = Number(metrics.reusedBytes ?? progress.reusedBytes ?? 0);
    return {
      type: 'backup', id: run.id, title: jobs.get(run.jobId)?.name || 'Deleted backup job', state: run.state,
      createdAt: run.createdAt, startedAt: run.startedAt || progress.startedAt, finishedAt: run.finishedAt, updatedAt: run.updatedAt || progress.updatedAt,
      active: isActiveBackupRun(run), raw: run,
      metrics: {
        scannedItems: Number(metrics.scannedItems ?? progress.itemsScanned ?? 0), scannedBytes,
        uploadedBytes, reusedBytes,
        deduplicationSavingsPercent: Number(metrics.deduplicationSavingsPercent ?? (scannedBytes > 0 ? Math.min(100, reusedBytes / scannedBytes * 100) : 0)),
        throughputBytesPerSecond: Number(metrics.throughputBytesPerSecond ?? progress.throughputBytesPerSecond ?? 0),
        durationMs: Number(metrics.durationMs ?? backupActivityDuration(run.startedAt || progress.startedAt, run.finishedAt, run.updatedAt || progress.updatedAt)),
        committedRepositories: Number(progress.committedRepositories || 0), repositoryCount: Number(progress.repositoryCount || 0)
      }
    };
  });
  const restores = state.backupActivity.restores.map((run) => {
    const progress = run.progress || {};
    const engineLabel = run.target?.engine === 'cockroachdb' ? 'CockroachDB' : run.target?.engine === 'influxdb3-enterprise' ? 'InfluxDB 3 Enterprise' : run.target?.engine === 'influxdb3-core' ? 'InfluxDB 3 Core' : run.target?.engine === 'influxdb' ? 'InfluxDB' : run.target?.engine === 'clickhouse' ? 'ClickHouse' : run.target?.engine === 'neo4j' ? 'Neo4j' : run.target?.engine === 'scylla-manager' ? 'ScyllaDB Manager' : run.target?.engine === 'search-cluster' ? 'Search cluster' : run.target?.engine === 'sqlite' ? 'SQLite' : run.target?.engine === 'redis' ? 'Redis' : run.target?.engine === 'mongodb' ? 'MongoDB' : run.target?.engine === 'oracle' ? 'Oracle' : run.target?.engine === 'mysql' ? 'MySQL' : run.target?.engine === 'mariadb' ? 'MariaDB' : run.target?.engine === 'postgresql' ? 'PostgreSQL' : run.target?.engine === 'sqlserver' ? 'SQL Server' : null;
    const pointInTime = ['point-in-time', 'postgresql-pitr', 'sqlserver-native', 'oracle-rman'].includes(run.target?.operation);
    const physical = ['physical', 'postgresql-pitr', 'sqlserver-native', 'oracle-rman'].includes(run.target?.operation);
    const operationLabel = run.target?.operation === 'oracle-rman' ? 'RMAN recovery' : run.target?.operation === 'sqlserver-native' ? 'native recovery' : run.target?.operation === 'postgresql-pitr' ? 'physical recovery' : physical ? 'physical restore' : pointInTime ? 'point-in-time recovery' : 'restore';
    const targetDatabase = run.target?.targetDatabase || run.target?.database;
    const targetLabel = targetDatabase
      ? `${engineLabel} ${pointInTime ? 'point-in-time recovery' : 'restore'} to ${targetDatabase}`
      : run.target?.engine === 'search-cluster' ? 'Search native alternate restore'
      : run.target?.engine === 'scylla-manager' ? 'ScyllaDB Manager alternate restore'
      : run.target?.engine === 'influxdb3-enterprise' && run.target?.tier === 'legacy-filesystem' ? 'InfluxDB 3 Enterprise legacy stopped-cluster restore'
      : run.target?.engine === 'influxdb3-enterprise' ? 'InfluxDB 3 Enterprise destructive live-cluster restore'
      : run.target?.engine === 'influxdb3-core' ? `InfluxDB 3 Core ${influxDb3CoreStoreUi(influxDb3CoreRunObjectStore(run)).label} restore`
      : run.target?.engine === 'redis' ? run.result?.recoveryTarget?.type === 'isolated-cluster-directory' ? 'Redis offline cluster recovery' : 'Redis alternate recovery'
      : run.target?.engine === 'sqlite' && run.target?.operation === 'alternate-file' ? 'SQLite alternate file recovery'
      : run.target?.mode === 'alternate' ? `${engineLabel} alternate ${operationLabel}` : engineLabel ? `${engineLabel} ${operationLabel}` : 'File restore';
    return {
      type: 'restore', id: run.id, title: targetLabel, state: run.state,
      createdAt: run.createdAt, startedAt: run.startedAt || progress.startedAt, finishedAt: run.result?.completedAt, updatedAt: run.updatedAt || progress.updatedAt,
      active: isActiveRestoreRun(run), raw: run,
      metrics: {
        itemsCompleted: Number(progress.itemsCompleted || 0), itemsTotal: Number(progress.itemsTotal || 0), itemsSkipped: Number(progress.itemsSkipped || 0),
        bytesWritten: Number(progress.bytesWritten || run.result?.bytesRestored || 0), throughputBytesPerSecond: Number(progress.throughputBytesPerSecond || 0),
        durationMs: backupActivityDuration(run.startedAt || progress.startedAt, run.result?.completedAt, run.updatedAt || progress.updatedAt)
      }
    };
  });
  const verifications = state.backupActivity.verifications.map((run) => {
    const progress = run.progress || {};
    const recoveryDrill = run.mode === 'mongodb-recovery-drill';
    const searchMetadata = run.mode === 'search-snapshot-metadata';
    const searchDrill = run.mode === 'search-snapshot-full-drill';
    const managerMetadata = run.mode === 'scylla-manager-metadata';
    const managerDrill = run.mode === 'scylla-manager-full-drill';
    const neo4jMetadata = run.mode === 'neo4j-metadata';
    const neo4jDrill = run.mode === 'neo4j-full-drill';
    const clickHouseMetadata = run.mode === 'clickhouse-metadata';
    const clickHouseDrill = run.mode === 'clickhouse-full-drill';
    const influxDbMetadata = run.mode === 'influxdb-metadata';
    const influxDbDrill = run.mode === 'influxdb-full-drill';
    const influxDb3CoreMetadata = run.mode === 'influxdb3-core-metadata';
    const influxDb3CoreDrill = run.mode === 'influxdb3-core-full-drill';
    const influxDb3EnterpriseMetadata = run.mode === 'influxdb3-enterprise-metadata';
    const influxDb3EnterpriseLegacyMetadata = run.mode === 'influxdb3-enterprise-legacy-metadata';
    const influxDb3EnterpriseLegacyDrill = run.mode === 'influxdb3-enterprise-legacy-full-drill';
    const cockroachDbMetadata = run.mode === 'cockroachdb-metadata';
    const cockroachDbDrill = run.mode === 'cockroachdb-full-drill';
    const influxDb3CoreStore = influxDb3CoreStoreUi(influxDb3CoreRunObjectStore(run));
    return {
      type: 'verification', id: run.id, title: cockroachDbDrill ? 'CockroachDB full alternate-database recovery drill' : cockroachDbMetadata ? 'CockroachDB native metadata recovery test' : influxDb3EnterpriseLegacyDrill ? 'Full stopped-cluster Enterprise legacy drill' : influxDb3EnterpriseLegacyMetadata ? 'Enterprise legacy filesystem metadata validation' : influxDb3EnterpriseMetadata ? 'InfluxDB 3 Enterprise upgraded-native metadata recovery test' : influxDb3CoreDrill ? `InfluxDB 3 Core stopped-target ${influxDb3CoreStore.label} drill` : influxDb3CoreMetadata ? `InfluxDB 3 Core ${influxDb3CoreStore.label} media and source validation` : influxDbDrill ? 'InfluxDB full alternate-instance drill' : influxDbMetadata ? 'InfluxDB media, source, scope, and retention validation' : clickHouseDrill ? 'ClickHouse full alternate-database drill' : clickHouseMetadata ? 'ClickHouse chain, source, and disk validation' : neo4jDrill ? 'Neo4j full alternate-target drill' : neo4jMetadata ? 'Neo4j chain and source validation' : managerDrill ? 'Manager full alternate-cluster drill' : managerMetadata ? 'Manager native metadata validation' : searchDrill ? 'Search full restore drill' : searchMetadata ? 'Search native metadata validation' : recoveryDrill ? 'MongoDB isolated recovery drill' : run.mode === 'sample-restore' ? 'Sample restore verification' : 'Repository verification', state: run.state,
      createdAt: run.createdAt, startedAt: run.startedAt || progress.startedAt, finishedAt: run.completedAt || run.result?.completedAt, updatedAt: run.updatedAt || progress.updatedAt,
      active: isActiveVerificationRun(run), raw: run,
      metrics: {
        recoveryPointsVerified: Number(progress.recoveryPointsVerified || 0), recoveryPointsTotal: Number(progress.recoveryPointsTotal || 0),
        filesVerified: Number(progress.filesVerified || 0), filesTotal: Number(progress.filesTotal || 0), bytesVerified: Number(progress.bytesVerified || 0),
        measuredRtoSeconds: Number(run.measuredRtoSeconds || run.result?.measuredRtoSeconds || 0),
        durationMs: backupActivityDuration(run.startedAt || progress.startedAt, run.completedAt || run.result?.completedAt, run.updatedAt || progress.updatedAt)
      }
    };
  });
  return [...backups, ...restores, ...verifications]
    .filter((entry) => filter === 'all' || entry.type === filter)
    .sort((left, right) => String(right.startedAt || right.createdAt || right.updatedAt || '').localeCompare(String(left.startedAt || left.createdAt || left.updatedAt || '')));
}

function backupActivityRowMetrics(entry) {
  const influxDb3CoreStore = influxDb3CoreStoreUi(influxDb3CoreRunObjectStore(entry.raw));
  if (entry.type === 'backup') return [
    ['Scanned', formatBackupMetricBytes(entry.metrics.scannedBytes)], ['Uploaded', formatBackupMetricBytes(entry.metrics.uploadedBytes)],
    ['Live rate', entry.metrics.throughputBytesPerSecond > 0 ? `${formatBytes(entry.metrics.throughputBytesPerSecond)}/s` : '-'],
    ['Saved', `${entry.metrics.deduplicationSavingsPercent.toFixed(1)}%`], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore' && entry.raw.target?.engine === 'cockroachdb') return [
    ['Database', entry.raw.result?.targetDatabase || entry.raw.target?.targetDatabase || '-'],
    ['Chain', `${entry.raw.result?.chainRecoveryPointIds?.length || entry.raw.recoveryPointIds?.length || 0} point(s)`],
    ['Validation', entry.raw.validation?.nativeIntegrityValidation ? 'Passed' : 'Not proven'],
    ['Target', entry.raw.result?.targetPreserved ? 'Preserved' : 'Inspect'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore' && entry.raw.target?.engine === 'search-cluster') return [
    ['Resources', `${entry.metrics.itemsCompleted} / ${entry.metrics.itemsTotal}`], ['Validation', entry.raw.validation?.nativeIntegrityValidation ? 'Passed' : '-'],
    ['Namespace', entry.raw.result?.renamePrefix || entry.raw.target?.renamePrefix || '-'], ['Rollback', 'Not supported'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore' && entry.raw.target?.engine === 'scylla-manager') return [
    ['Phases', `${entry.raw.progress?.phasesCompleted || 0} / ${entry.raw.progress?.phasesTotal || 2}`], ['Validation', entry.raw.validation?.nativeIntegrityValidation ? 'Passed' : '-'],
    ['Snapshot', entry.raw.result?.snapshotTag || entry.raw.target?.snapshotTag || '-'], ['Rollback', 'Not supported'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore' && entry.raw.target?.engine === 'neo4j') return [
    ['Artifacts', `${entry.metrics.itemsCompleted} / ${entry.metrics.itemsTotal}`], ['Validation', entry.raw.validation?.nativeIntegrityValidation ? 'Passed' : '-'],
    ['Database', entry.raw.result?.targetDatabase || entry.raw.target?.targetDatabase || '-'], ['Service', entry.raw.result?.serviceStarted === false ? 'Stopped' : '-'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore' && entry.raw.target?.engine === 'clickhouse') return [
    ['Tables', `${entry.metrics.itemsCompleted} / ${entry.metrics.itemsTotal}`], ['Validation', entry.raw.validation?.nativeIntegrityValidation ? 'Passed' : '-'],
    ['Database', entry.raw.result?.targetDatabase || entry.raw.target?.targetDatabase || '-'], ['Rollback', 'Not claimed'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore' && entry.raw.target?.engine === 'influxdb') return [
    ['Members', `${entry.metrics.itemsCompleted} / ${entry.metrics.itemsTotal}`], ['Validation', entry.raw.validation?.nativeIntegrityValidation ? 'Passed' : '-'],
    ['Buckets', String(entry.raw.result?.buckets?.length || 0)], ['Target', entry.raw.result?.targetPreserved ? 'Preserved' : '-'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore' && entry.raw.target?.engine === 'influxdb3-enterprise' && entry.raw.target?.tier === 'legacy-filesystem') return [
    ['Files', `${entry.metrics.itemsCompleted} / ${entry.metrics.itemsTotal}`], ['Target', entry.raw.result?.targetPreserved ? 'Preserved' : 'Inspect'],
    ['Service', 'Stopped'], ['Rollback', 'Not claimed'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore' && entry.raw.target?.engine === 'influxdb3-enterprise') return [
    ['Scope', 'Original live cluster'], ['Native result', entry.raw.validation?.nativeRestoreStatus === 'completed' ? 'Completed' : 'Inspect'],
    ['Row deletes', entry.raw.result?.evidence?.rowDeletesMayPersist === false ? 'No persistence reported' : 'May persist'], ['Rollback', 'Unavailable'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore' && entry.raw.target?.engine === 'influxdb3-core') return [
    [influxDb3CoreStore.itemTitle, `${entry.metrics.itemsCompleted} / ${entry.metrics.itemsTotal}`], ['Written', formatBackupMetricBytes(entry.metrics.bytesWritten)],
    ['Validation', entry.raw.validation?.nativeIntegrityValidation ? 'Passed' : '-'], ['Target', entry.raw.result?.targetStopped ? 'Stopped' : 'Inspect'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.type === 'restore') return [
    ['Items', `${entry.metrics.itemsCompleted} / ${entry.metrics.itemsTotal}`], ['Written', formatBackupMetricBytes(entry.metrics.bytesWritten)],
    ['Live rate', entry.metrics.throughputBytesPerSecond > 0 ? `${formatBytes(entry.metrics.throughputBytesPerSecond)}/s` : '-'],
    ['Skipped', String(entry.metrics.itemsSkipped)], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'search-snapshot-metadata') return [
    ['Snapshot', entry.raw.evidence?.snapshotState || '-'], ['Shards', `${entry.raw.evidence?.shards?.successful || 0} / ${entry.raw.evidence?.shards?.total || 0}`],
    ['Membership', entry.raw.evidence?.exactMembership ? 'Exact' : '-'], ['Class', 'Metadata only'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'search-snapshot-full-drill') return [
    ['Restore', entry.raw.evidence?.nativeIntegrityValidation ? 'Validated' : '-'], ['Objects', entry.raw.evidence?.expectedObjects || '-'],
    ['Target', entry.raw.evidence?.targetDestroyed ? 'Destroyed' : entry.state === 'interrupted' ? 'Inspect' : '-'], ['Class', 'Full drill'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'scylla-manager-metadata') return [
    ['Task', entry.raw.evidence?.taskId || '-'], ['Run', entry.raw.evidence?.runId || '-'], ['Snapshot', entry.raw.evidence?.snapshotTag || '-'], ['Catalog', entry.raw.evidence?.exactCatalog ? 'Exact' : '-'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'scylla-manager-full-drill') return [
    ['Restore', entry.raw.evidence?.nativeIntegrityValidation ? 'Validated' : '-'], ['Phases', entry.raw.evidence?.schemaPhase === 'pass' && entry.raw.evidence?.tablePhase === 'pass' ? 'Passed' : '-'], ['Target', entry.raw.evidence?.targetPreserved ? 'Preserved' : '-'], ['Cleanup', 'Not claimed'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'neo4j-metadata') return [
    ['Artifacts', String(entry.raw.evidence?.artifactCount || 0)], ['Chain', String(entry.raw.evidence?.chainRecoveryPointIds?.length || 0)], ['Source', entry.raw.evidence?.sourceIdentityVerified ? 'Matched' : '-'], ['Class', 'Metadata only'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'neo4j-full-drill') return [
    ['Restore', entry.raw.evidence?.nativeIntegrityValidation ? 'Validated' : '-'], ['Target', entry.raw.evidence?.targetPreserved ? 'Preserved' : '-'], ['Service', entry.raw.evidence?.serviceStarted === false ? 'Stopped' : '-'], ['Cleanup', 'Not claimed'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'clickhouse-metadata') return [
    ['Artifacts', String(entry.raw.evidence?.artifactCount || 0)], ['Chain', String(entry.raw.evidence?.chainRecoveryPointIds?.length || 0)], ['Objects', entry.raw.evidence?.selectionIdentityVerified ? 'Matched' : '-'], ['Disk', entry.raw.evidence?.destinationIdentityVerified ? 'Matched' : '-'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'clickhouse-full-drill') return [
    ['Restore', entry.raw.evidence?.nativeIntegrityValidation ? 'Validated' : '-'], ['Tables', String(entry.raw.evidence?.tableCount || 0)], ['Target', entry.raw.evidence?.targetPreserved ? 'Preserved' : '-'], ['Cleanup', 'Not claimed'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'influxdb-metadata') return [
    ['Members', String(entry.raw.evidence?.nativeFileCount || 0)], ['Media', entry.raw.evidence?.completeMediaAuthenticated ? 'Authenticated' : '-'], ['Source', entry.raw.evidence?.sourceIdentityVerified ? 'Matched' : '-'], ['Retention', entry.raw.evidence?.retentionRulesVerified ? 'Matched' : '-'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'influxdb-full-drill') return [
    ['Restore', entry.raw.evidence?.nativeIntegrityValidation ? 'Validated' : '-'], ['Buckets', String(entry.raw.evidence?.bucketCount || 0)], ['Target', entry.raw.evidence?.targetPreserved ? 'Preserved' : '-'], ['Cleanup', 'Not claimed'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'influxdb3-core-metadata') return [
    [influxDb3CoreStore.itemTitle, String(entry.raw.evidence?.nativeFileCount || 0)], ['Media', entry.raw.evidence?.completeMediaAuthenticated ? 'Authenticated' : '-'], ['Storage', entry.raw.evidence?.storageIdentityVerified ? 'Matched' : '-'], ['Proof', entry.raw.evidence?.consistencyProofVerified ? 'Matched' : '-'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'influxdb3-core-full-drill') return [
    ['Restore', entry.raw.evidence?.nativeIntegrityValidation ? 'Validated' : '-'], [influxDb3CoreStore.itemTitle, String(entry.raw.evidence?.nativeFileCount || 0)], ['Target', entry.raw.evidence?.targetStopped ? 'Stopped' : 'Inspect'], ['Startup', 'Manual'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'influxdb3-enterprise-metadata') return [
    ['Chain', `${Number(entry.raw.evidence?.nativeChainLength || 0)} member(s)`],
    ['Native media', entry.raw.evidence?.retainedNativeChainAuthenticated ? 'Authenticated' : 'Not proven'],
    ['Row deletes', entry.raw.evidence?.rowDeletesMayPersist === false ? 'No persistence reported' : 'May persist'],
    ['Restore', 'Not performed'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'influxdb3-enterprise-legacy-metadata') return [
    ['Files', String(entry.raw.evidence?.nativeFileCount || 0)], ['Directories', String(entry.raw.evidence?.nativeDirectoryCount || 0)],
    ['Media', entry.raw.evidence?.completeMediaAuthenticated ? 'Authenticated' : '-'], ['Class', 'Metadata only'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'influxdb3-enterprise-legacy-full-drill') return [
    ['Restore', entry.raw.evidence?.nativeIntegrityValidation ? 'Validated' : '-'], ['Target', entry.raw.evidence?.targetPreserved ? 'Preserved' : 'Inspect'],
    ['Service', entry.raw.evidence?.targetStopped ? 'Stopped' : 'Inspect'], ['Cleanup', 'Not claimed'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'cockroachdb-metadata') return [
    ['Artifacts', String(entry.raw.evidence?.artifactCount || 0)], ['Chain', `${entry.raw.evidence?.chainRecoveryPointIds?.length || 0} point(s)`],
    ['Source', entry.raw.evidence?.sourceIdentityVerified ? 'Matched' : 'Not proven'], ['Destination', entry.raw.evidence?.destinationIdentityVerified ? 'Matched' : 'Not proven'],
    ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'cockroachdb-full-drill') return [
    ['Restore', entry.raw.evidence?.nativeIntegrityValidation ? 'Validated' : 'Not proven'], ['Database', entry.raw.evidence?.targetDatabase || '-'],
    ['Target', entry.raw.evidence?.targetPreserved ? 'Preserved' : 'Inspect'], ['Cleanup', 'Not claimed'], ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  if (entry.raw.mode === 'mongodb-recovery-drill') return [
    ['Recovery', entry.raw.evidence?.expectedObjects === 'pass' && entry.raw.evidence?.nativeIntegrityValidation ? 'Validated' : '-'],
    ['Isolation', entry.raw.evidence?.isolated && entry.raw.evidence?.serviceExposed === false ? 'Passed' : '-'],
    ['Target', entry.raw.evidence?.targetDestroyed ? 'Destroyed' : '-'],
    ['RTO', entry.metrics.measuredRtoSeconds > 0 ? `${entry.metrics.measuredRtoSeconds}s` : '-'],
    ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
  return [
    ['Points', `${entry.metrics.recoveryPointsVerified} / ${entry.metrics.recoveryPointsTotal}`], ['Files', `${entry.metrics.filesVerified} / ${entry.metrics.filesTotal}`],
    ['Verified', formatBackupMetricBytes(entry.metrics.bytesVerified)], ['Mode', backupVerificationModeLabel(entry.raw, true)],
    ['Duration', formatBackupDuration(entry.metrics.durationMs)]
  ];
}

function renderBackupActivity() {
  if (!els.backupActivityList) return;
  const allEntries = backupActivityEntries('all');
  const entries = backupActivityEntries();
  const active = allEntries.filter((entry) => entry.active).length;
  const completed = allEntries.filter((entry) => ['succeeded', 'warning'].includes(entry.state)).length;
  const transferredBytes = allEntries.reduce((total, entry) => total + (entry.type === 'backup' ? entry.metrics.uploadedBytes : entry.type === 'restore' ? entry.metrics.bytesWritten : 0), 0);
  const reusedBytes = allEntries.reduce((total, entry) => total + (entry.type === 'backup' ? entry.metrics.reusedBytes : 0), 0);
  els.backupActivitySummary.classList.toggle('hidden', allEntries.length === 0);
  els.backupActivitySummary.innerHTML = [
    ['Runs', String(allEntries.length), `${active} active`], ['Completed', String(completed), 'Successful or warning'],
    ['Transferred', formatBackupMetricBytes(transferredBytes), 'Backup uploads and restores'], ['Deduplicated', formatBackupMetricBytes(reusedBytes), 'Repository bytes reused']
  ].map(([label, value, detail]) => `<div class="backup-summary-item"><span>${label}</span><strong>${escapeHtml(value)}</strong><small>${detail}</small></div>`).join('');
  els.backupActivityList.classList.toggle('hidden', entries.length === 0);
  els.backupActivityEmpty.classList.toggle('hidden', entries.length > 0);
  els.backupActivityEmpty.querySelector('strong').textContent = allEntries.length ? 'No matching activity' : 'No activity';
  els.backupActivityList.innerHTML = entries.map((entry) => `
    <button class="backup-activity-row" type="button" data-backup-activity-type="${entry.type}" data-backup-activity-id="${escapeHtml(entry.id)}" aria-label="View ${escapeHtml(entry.title)} run details">
      <span class="backup-activity-kind ${entry.type}" aria-hidden="true"><svg class="button-icon" viewBox="0 0 24 24" focusable="false"><use href="#icon-${entry.type === 'backup' ? 'save' : entry.type === 'restore' ? 'refresh' : 'check'}"></use></svg></span>
      <span class="backup-activity-copy"><strong>${escapeHtml(entry.title)}</strong><small>${escapeHtml(entry.type[0].toUpperCase() + entry.type.slice(1))} - ${escapeHtml(formatDateTime(entry.startedAt || entry.createdAt || entry.updatedAt))}</small></span>
      <span class="backup-activity-state ${backupActivityStateClass(entry.state)}">${escapeHtml(backupActivityStateLabel(entry.state))}</span>
      <span class="backup-activity-metrics">${backupActivityRowMetrics(entry).map(([label, value]) => `<span><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>`).join('')}</span>
      <svg class="button-icon backup-activity-chevron" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-chevron-right"></use></svg>
    </button>`).join('');
  syncBackupRunPolling();
}

function renderBackupTests() {
  if (!els.backupTestList) return;
  const entries = backupActivityEntries('verification');
  els.backupTestList.classList.toggle('hidden', entries.length === 0);
  els.backupTestsEmpty.classList.toggle('hidden', entries.length > 0);
  els.backupTestList.innerHTML = entries.map((entry) => {
    const influxDb3CoreStore = influxDb3CoreStoreUi(influxDb3CoreRunObjectStore(entry.raw));
    const evidence = entry.raw.mode === 'neo4j-metadata'
      ? `${entry.raw.evidence?.artifactCount || 0} artifacts / ${entry.raw.evidence?.chainRecoveryPointIds?.length || 0} points - source identity ${entry.raw.evidence?.sourceIdentityVerified ? 'matched' : 'not verified'}`
      : entry.raw.mode === 'neo4j-full-drill'
      ? `${entry.raw.evidence?.targetDatabase || 'Alternate database pending'} - native consistency ${entry.raw.evidence?.nativeIntegrityValidation ? 'passed' : 'not verified'} - target preserved`
      : entry.raw.mode === 'clickhouse-metadata'
      ? `${entry.raw.evidence?.artifactCount || 0} artifacts / ${entry.raw.evidence?.chainRecoveryPointIds?.length || 0} points - source and disk identity ${entry.raw.evidence?.sourceIdentityVerified && entry.raw.evidence?.destinationIdentityVerified ? 'matched' : 'not verified'}`
      : entry.raw.mode === 'clickhouse-full-drill'
      ? `${entry.raw.evidence?.targetDatabase || 'Alternate database pending'} - native integrity ${entry.raw.evidence?.nativeIntegrityValidation ? 'passed' : 'not verified'} - target preserved`
      : entry.raw.mode === 'influxdb-metadata'
      ? `${entry.raw.evidence?.nativeFileCount || 0} native members - source, scope, inventory, and retention ${entry.raw.evidence?.sourceIdentityVerified && entry.raw.evidence?.retentionRulesVerified ? 'matched' : 'not verified'}`
      : entry.raw.mode === 'influxdb-full-drill'
      ? `${entry.raw.evidence?.bucketCount || 0} bucket identities - native integrity ${entry.raw.evidence?.nativeIntegrityValidation ? 'passed' : 'not verified'} - target preserved`
      : entry.raw.mode === 'influxdb3-core-metadata'
      ? `${entry.raw.evidence?.nativeFileCount || 0} ${influxDb3CoreStore.itemPlural} / ${entry.raw.evidence?.nativeDirectoryCount || 0} directories - source, storage, and consistency proof ${entry.raw.evidence?.sourceIdentityVerified && entry.raw.evidence?.storageIdentityVerified && entry.raw.evidence?.consistencyProofVerified ? 'matched' : 'not verified'}`
      : entry.raw.mode === 'influxdb3-core-full-drill'
      ? `Node ${entry.raw.evidence?.nodeId || 'pending'} - native integrity ${entry.raw.evidence?.nativeIntegrityValidation ? 'passed' : 'not verified'} - stopped target ${entry.raw.evidence?.targetPreserved ? 'preserved' : 'not proven'}`
      : entry.raw.mode === 'influxdb3-enterprise-metadata'
      ? `${entry.raw.evidence?.nativeChainLength || 0} native chain member(s) authenticated - row-delete state not captured; row deletes may persist - destructive live drill unavailable - full restore not performed`
      : entry.raw.mode === 'scylla-manager-metadata'
      ? `${entry.raw.evidence?.snapshotTag || 'Snapshot pending'} - task/run/catalog ${entry.raw.evidence?.exactCatalog ? 'verified' : 'not verified'}`
      : entry.raw.mode === 'scylla-manager-full-drill'
      ? `${entry.raw.evidence?.targetManagedClusterId || 'Alternate cluster pending'} - restored data ${entry.raw.evidence?.targetPreserved ? 'preserved' : 'not proven'}`
      : entry.raw.mode === 'cockroachdb-metadata'
      ? `${entry.raw.evidence?.artifactCount || 0} authenticated metadata artifacts / ${entry.raw.evidence?.chainRecoveryPointIds?.length || 0} points - cluster, topology, inventory, and destination ${entry.raw.evidence?.sourceIdentityVerified && entry.raw.evidence?.destinationIdentityVerified ? 'matched' : 'not verified'}`
      : entry.raw.mode === 'cockroachdb-full-drill'
      ? `${entry.raw.evidence?.targetDatabase || 'Alternate database pending'} - native integrity ${entry.raw.evidence?.nativeIntegrityValidation ? 'passed' : 'not verified'} - target preserved`
      : backupVerificationModeLabel(entry.raw);
    return `<button class="backup-activity-row" type="button" data-backup-test-run="${escapeHtml(entry.id)}"><span class="backup-activity-kind verification" aria-hidden="true"><svg class="button-icon" viewBox="0 0 24 24" focusable="false"><use href="#icon-check"></use></svg></span><span class="backup-activity-copy"><strong>${escapeHtml(entry.title)}</strong><small>${escapeHtml(evidence)} - ${escapeHtml(formatDateTime(entry.startedAt || entry.createdAt || entry.updatedAt))}</small></span><span class="backup-activity-state ${backupActivityStateClass(entry.state)}">${escapeHtml(backupActivityStateLabel(entry.state))}</span><span class="backup-activity-metrics">${backupActivityRowMetrics(entry).slice(0, 3).map(([label, value]) => `<span><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>`).join('')}</span><svg class="button-icon backup-activity-chevron" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#icon-chevron-right"></use></svg></button>`;
  }).join('');
}

async function loadBackupTests() {
  await loadBackupActivity();
  renderBackupTests();
}

