async function discoverBackupNeo4j() {
  const action = 'backup:connections:neo4j:discover';
  if (pendingActions.has(action)) return;
  pendingActions.add(action);
  setButtonLoading(els.backupNeo4jDiscoverButton, true);
  els.backupNeo4jError.classList.add('hidden');
  try {
    if (!state.backupNeo4jConnectionId) {
      const connection = await window.deployerx.createBackupNeo4jConnection({
        name: els.backupNeo4jName.value.trim(), expectedEdition: els.backupNeo4jEdition.value, executionMode: els.backupNeo4jExecution.value,
        sshConnectionId: els.backupNeo4jExecution.value === 'ssh' ? els.backupNeo4jSshConnection.value : null,
        address: els.backupNeo4jAddress.value.trim(), username: els.backupNeo4jUsername.value.trim() || null, password: els.backupNeo4jPassword.value || null,
        neo4jPath: els.backupNeo4jExecutable.value.trim(), neo4jAdminPath: els.backupNeo4jAdminExecutable.value.trim(), cypherShellPath: els.backupNeo4jCypherShell.value.trim(), timeoutMs: Number(els.backupNeo4jTimeout.value)
      });
      state.backupNeo4jConnectionId = connection.id;
      state.backupNeo4jConnections.push(connection);
      setBackupNeo4jExistingConnection(true);
      if (!els.backupNeo4jSourceName.value.trim()) els.backupNeo4jSourceName.value = `${connection.name} database`;
    }
    const tested = await window.deployerx.testBackupNeo4jConnection(state.backupNeo4jConnectionId);
    if (tested.result.status !== 'success') throw new Error(tested.result.error?.safeMessage || 'The Neo4j connection test failed.');
    state.backupNeo4jConnections = state.backupNeo4jConnections.map((item) => item.id === tested.connection.id ? tested.connection : item);
    const discovered = await window.deployerx.discoverBackupNeo4jResources(state.backupNeo4jConnectionId, 'all');
    const databases = (discovered.databases || []).filter((item) => item.selectable && !item.system);
    if (!databases.length) throw new Error('No selectable Neo4j user database was discovered.');
    state.backupNeo4jDiscovery = discovered;
    els.backupNeo4jDatabase.innerHTML = databases.map((item) => `<option value="${escapeHtml(item.name)}">${escapeHtml(item.name)} - ${escapeHtml(item.currentStatus)} - ${escapeHtml(item.databaseId)}</option>`).join('');
    const enterprise = discovered.edition === 'enterprise';
    els.backupNeo4jMethod.querySelector('option[value="neo4j-native-backup"]').disabled = !enterprise;
    els.backupNeo4jMethod.value = enterprise ? 'neo4j-native-backup' : 'offline';
    els.backupNeo4jEvidence.textContent = `Neo4j ${discovered.version?.text || tested.result.remotePlatform?.version || ''} ${discovered.edition || ''} - ${databases.length} user database${databases.length === 1 ? '' : 's'} - ${discovered.servers?.length || 0} server${discovered.servers?.length === 1 ? '' : 's'} - deployment and topology authenticated`;
    els.backupNeo4jSelection.classList.remove('hidden');
    els.backupNeo4jSaveSourceButton.classList.remove('hidden');
    syncBackupNeo4jMethod();
    renderBackupConnections();
  } catch (error) {
    state.backupNeo4jDiscovery = null;
    els.backupNeo4jSelection.classList.add('hidden');
    els.backupNeo4jSaveSourceButton.classList.add('hidden');
    els.backupNeo4jError.textContent = error.message || 'Could not validate the Neo4j deployment.';
    els.backupNeo4jError.classList.remove('hidden');
  } finally {
    pendingActions.delete(action);
    setButtonLoading(els.backupNeo4jDiscoverButton, false);
  }
}

async function saveBackupNeo4jSource(event) {
  event.preventDefault();
  if (!state.backupNeo4jDiscovery || !state.backupNeo4jConnectionId) return;
  syncBackupNeo4jMethod();
  if (els.backupNeo4jSaveSourceButton.disabled) return;
  const online = els.backupNeo4jMethod.value === 'neo4j-native-backup';
  await withButtonLoading('backup:database-sources:neo4j:save', els.backupNeo4jSaveSourceButton, async () => {
    els.backupNeo4jError.classList.add('hidden');
    try {
      await window.deployerx.saveBackupDatabaseSource({
        name: els.backupNeo4jSourceName.value.trim(), connectionId: state.backupNeo4jConnectionId,
        selector: { allDatabases: false, databases: { include: [{ name: els.backupNeo4jDatabase.value }], exclude: [] }, schemas: { include: [], exclude: [] }, tables: { include: [], exclude: [] }, includeGlobalObjects: online && els.backupNeo4jIncludeRbac.checked },
        consistency: { requestedLevel: 'application', method: online ? 'neo4j-native-backup' : 'offline', backupMethod: 'physical', backupMode: online ? els.backupNeo4jMode.value : 'full', captureCoordinates: online },
        ...(online ? { physicalExecution: { backupAddresses: els.backupNeo4jAddresses.value.split(',').map((value) => value.trim()).filter(Boolean) } } : {})
      });
      closeBackupNeo4jModal();
      await Promise.all([loadBackupSources(), loadBackupConnections()]);
      showToast('Neo4j Source saved');
    } catch (error) {
      els.backupNeo4jError.textContent = error.message || 'Could not save the Neo4j Source.';
      els.backupNeo4jError.classList.remove('hidden');
    }
  });
}

