      await window.deployerx.saveBackupDatabaseSource({
        name: els.backupClickHouseSourceName.value.trim(), connectionId: state.backupClickHouseConnectionId,
        selector: { allDatabases: false, databases: { include: [{ name: els.backupClickHouseDatabase.value }], exclude: [] }, schemas: { include: [], exclude: [] }, tables: { include: selectedClickHouseTables(), exclude: [] }, includeGlobalObjects: false },
        consistency: { requestedLevel: 'application', method: 'clickhouse-native-backup', backupMethod: 'physical', backupMode: 'full', captureCoordinates: true },
        physicalExecution: { executionMode: 'asynchronous' }
      });
      closeBackupClickHouseModal();
      await Promise.all([loadBackupSources(), loadBackupConnections()]);
      showToast('ClickHouse Source saved');
