async function discoverBackupInfluxDb() {
  const action = 'backup:connections:influxdb:discover';
  if (pendingActions.has(action)) return;
  if (!state.backupInfluxDbConnectionId && [...els.backupInfluxDbConnectionFields.querySelectorAll('input, select')].some((input) => !input.reportValidity())) return;
  pendingActions.add(action);
  setButtonLoading(els.backupInfluxDbDiscoverButton, true);
  els.backupInfluxDbError.classList.add('hidden');
  try {
    if (!state.backupInfluxDbConnectionId) {
      const connection = await window.deployerx.createBackupInfluxDbConnection({
        name: els.backupInfluxDbName.value.trim(), protocol: els.backupInfluxDbProtocol.value,
        allowInsecureHttp: els.backupInfluxDbProtocol.value === 'http' && els.backupInfluxDbAllowInsecure.checked,
        host: els.backupInfluxDbHost.value.trim(), port: Number(els.backupInfluxDbPort.value), basePath: els.backupInfluxDbBasePath.value.trim(),
        token: els.backupInfluxDbToken.value, caFile: els.backupInfluxDbProtocol.value === 'https' ? els.backupInfluxDbCaFile.value.trim() || null : null,
        cliPath: els.backupInfluxDbCliPath.value.trim(), timeoutMs: Number(els.backupInfluxDbTimeout.value)
      });
      state.backupInfluxDbConnectionId = connection.id;
      state.backupInfluxDbConnections.push(connection);
      setBackupInfluxDbExistingConnection(true);
      if (!els.backupInfluxDbSourceName.value.trim()) els.backupInfluxDbSourceName.value = `${connection.name} backup`;
      els.backupInfluxDbToken.value = '';
    }
    const tested = await window.deployerx.testBackupInfluxDbConnection(state.backupInfluxDbConnectionId);
    state.backupInfluxDbConnections = state.backupInfluxDbConnections.map((item) => item.id === tested.connection.id ? tested.connection : item);
    if (tested.result.status !== 'success') throw new Error(tested.result.error?.safeMessage || 'InfluxDB connection validation failed.');
    const discovered = await window.deployerx.discoverBackupInfluxDbResources(state.backupInfluxDbConnectionId, 'all');
    const organizations = (discovered.organizations || []).filter((organization) => organization.selectable === true && (discovered.buckets || []).some((bucket) => bucket.organizationId === organization.id && bucket.selectable === true));
    if (!organizations.length) throw new Error('No organization with a selectable user bucket was discovered.');
    state.backupInfluxDbDiscovery = discovered;
    els.backupInfluxDbOrganization.innerHTML = organizations.map((organization) => `<option value="${escapeHtml(organization.id)}">${escapeHtml(organization.name)} - ${escapeHtml(organization.id)}</option>`).join('');
    els.backupInfluxDbEvidence.textContent = `InfluxDB OSS ${discovered.version?.text || tested.result.endpointIdentity?.version || ''} / CLI ${discovered.cliVersion?.text || tested.result.endpointIdentity?.cliVersion || ''} - ${organizations.length} organization${organizations.length === 1 ? '' : 's'} - ${(discovered.buckets || []).filter((bucket) => bucket.selectable).length} user buckets - deployment and inventory authenticated - plaintext token recovery unavailable`;
    els.backupInfluxDbSelection.classList.remove('hidden');
    els.backupInfluxDbSaveSourceButton.classList.remove('hidden');
    syncBackupInfluxDbSelection();
    renderBackupConnections();
  } catch (error) {
    state.backupInfluxDbDiscovery = null;
    els.backupInfluxDbSelection.classList.add('hidden');
    els.backupInfluxDbSaveSourceButton.classList.add('hidden');
    els.backupInfluxDbError.textContent = error.message || 'Could not validate the InfluxDB deployment.';
    els.backupInfluxDbError.classList.remove('hidden');
  } finally {
    pendingActions.delete(action);
    setButtonLoading(els.backupInfluxDbDiscoverButton, false);
  }
}

async function saveBackupInfluxDbSource(event) {
  event.preventDefault();
  if (!state.backupInfluxDbDiscovery || !state.backupInfluxDbConnectionId) return;
  syncBackupInfluxDbSelection();
  if (els.backupInfluxDbSaveSourceButton.disabled) return;
  const organization = state.backupInfluxDbDiscovery.organizations.find((item) => item.id === els.backupInfluxDbOrganization.value);
  const bucket = backupInfluxDbUserBuckets().find((item) => item.id === els.backupInfluxDbBucket.value);
  await withButtonLoading('backup:database-sources:influxdb:save', els.backupInfluxDbSaveSourceButton, async () => {
    try {
      await window.deployerx.saveBackupDatabaseSource({
        name: els.backupInfluxDbSourceName.value.trim(), connectionId: state.backupInfluxDbConnectionId,
        selector: { allDatabases: false, databases: { include: [{ name: organization.name }], exclude: [] }, schemas: { include: [], exclude: [] }, tables: { include: bucket ? [{ database: organization.name, schema: organization.name, name: bucket.name }] : [], exclude: [] }, includeGlobalObjects: false },
        consistency: { requestedLevel: 'application', method: 'influxdb-v2-native-backup', backupMethod: 'physical', backupMode: 'full', captureCoordinates: true }
      });
      closeBackupInfluxDbModal();
      await Promise.all([loadBackupSources(), loadBackupConnections()]);
      showToast('InfluxDB Source saved');
    } catch (error) {
      els.backupInfluxDbError.textContent = error.message || 'Could not save the InfluxDB Source.';
      els.backupInfluxDbError.classList.remove('hidden');
    }
  });
}

const BACKUP_INFLUXDB3_CORE_CONSISTENCY = Object.freeze({
  stopped: { requestedLevel: 'application', method: 'influxdb3-core-stopped', confirmationText: 'NODE IS STOPPED', evidence: 'The Core endpoint must remain stopped and unreachable for the complete capture.' },
  'atomic-snapshot': { requestedLevel: 'application', method: 'influxdb3-core-atomic-snapshot', confirmationText: 'USE ATOMIC SNAPSHOT', evidence: 'Application consistency depends on the operator-proven atomic filesystem snapshot supplied as the Source.' },
  'ordered-live-copy': { requestedLevel: 'crash', method: 'influxdb3-core-ordered-copy', confirmationText: 'ACCEPT CRASH CONSISTENCY', evidence: 'The ordered live copy is crash-consistent. Writes after the latest included snapshot may be absent.' }
});

function setBackupInfluxDb3CoreExistingConnection(existing) {
  els.backupInfluxDb3CoreConnectionFields.classList.toggle('hidden', existing);
  for (const input of els.backupInfluxDb3CoreConnectionFields.querySelectorAll('input, select')) input.disabled = existing;
}

function backupInfluxDb3CoreObjectStore() {
  const value = els.backupInfluxDb3CoreObjectStore.value;
  return ['s3', 'azure', 'google'].includes(value) ? value : 'file';
}

function clearBackupInfluxDb3CoreCredentials() {
  els.backupInfluxDb3CoreAccessKeyId.value = '';
  els.backupInfluxDb3CoreSecretAccessKey.value = '';
  els.backupInfluxDb3CoreSessionToken.value = '';
  els.backupInfluxDb3CoreAzureAccessKey.value = '';
  els.backupInfluxDb3CoreGcsServiceAccountJson.value = '';
}

function syncBackupInfluxDb3CoreObjectStore() {
  const objectStore = backupInfluxDb3CoreObjectStore();
  const file = objectStore === 'file';
  const s3 = objectStore === 's3';
  const azure = objectStore === 'azure';
  const google = objectStore === 'google';
  const existing = Boolean(state.backupInfluxDb3CoreConnectionId);
  const storeUi = influxDb3CoreStoreUi(objectStore);
  els.backupInfluxDb3CoreFilesystemFields.classList.toggle('hidden', !file);
  els.backupInfluxDb3CoreS3Fields.classList.toggle('hidden', !s3);
  els.backupInfluxDb3CoreAzureFields.classList.toggle('hidden', !azure);
  els.backupInfluxDb3CoreGcsFields.classList.toggle('hidden', !google);
  els.backupInfluxDb3CoreDataRoot.required = file;
  els.backupInfluxDb3CoreDataRoot.disabled = existing || !file;
  for (const input of els.backupInfluxDb3CoreS3Fields.querySelectorAll('input, select')) input.disabled = existing || !s3;
  for (const input of els.backupInfluxDb3CoreAzureFields.querySelectorAll('input, select')) input.disabled = existing || !azure;
  for (const input of els.backupInfluxDb3CoreGcsFields.querySelectorAll('input, textarea')) input.disabled = existing || !google;
  els.backupInfluxDb3CoreObjectStoreRegion.required = s3;
  els.backupInfluxDb3CoreObjectStoreBucket.required = s3;
  els.backupInfluxDb3CoreObjectStoreTimeout.required = s3;
  els.backupInfluxDb3CoreAccessKeyId.required = s3;
  els.backupInfluxDb3CoreSecretAccessKey.required = s3;
  els.backupInfluxDb3CoreAzureAccountName.required = azure;
  els.backupInfluxDb3CoreAzureContainer.required = azure;
  els.backupInfluxDb3CoreAzureTimeout.required = azure;
  els.backupInfluxDb3CoreAzureAccessKey.required = azure;
  els.backupInfluxDb3CoreGcsBucket.required = google;
  els.backupInfluxDb3CoreGcsTimeout.required = google;
  els.backupInfluxDb3CoreGcsServiceAccountJson.required = google;
  const insecureObjectStore = s3 && /^http:\/\//i.test(els.backupInfluxDb3CoreObjectStoreEndpoint.value.trim());
  const insecureAzure = azure && /^http:\/\//i.test(els.backupInfluxDb3CoreAzureEndpoint.value.trim());
  els.backupInfluxDb3CoreObjectStoreInsecureField.classList.toggle('hidden', !insecureObjectStore);
  if (!insecureObjectStore) els.backupInfluxDb3CoreAllowInsecureObjectStoreEndpoint.checked = false;
  els.backupInfluxDb3CoreAzureInsecureField.classList.toggle('hidden', !insecureAzure);
  if (!insecureAzure) els.backupInfluxDb3CoreAzureAllowInsecureEndpoint.checked = false;
  els.backupInfluxDb3CoreBindTitle.textContent = `Bind this exact ${storeUi.label} node`;
  els.backupInfluxDb3CoreBindEvidence.textContent = file
    ? 'The data root and node ID identify the complete protected Core node.'
    : azure
      ? 'The storage account, container, optional prefix, and node ID identify the complete protected Core node.'
      : 'The bucket, optional prefix, and node ID identify the complete protected Core node.';
  els.backupInfluxDb3CoreStorageBoundaryTitle.textContent = storeUi.cloud ? 'Object-store boundary' : 'Filesystem boundary';
  syncBackupInfluxDb3CoreConsistency();
}

function syncBackupInfluxDb3CoreProtocol() {
  const insecure = els.backupInfluxDb3CoreProtocol.value === 'http';
  els.backupInfluxDb3CoreInsecureField.classList.toggle('hidden', !insecure);
  els.backupInfluxDb3CoreCaFileField.classList.toggle('hidden', insecure);
  if (!insecure) els.backupInfluxDb3CoreAllowInsecure.checked = false;
}

function syncBackupInfluxDb3CoreConsistency() {
  const proof = BACKUP_INFLUXDB3_CORE_CONSISTENCY[els.backupInfluxDb3CoreConsistency.value] || BACKUP_INFLUXDB3_CORE_CONSISTENCY.stopped;
  els.backupInfluxDb3CoreConsistencyEvidence.textContent = els.backupInfluxDb3CoreConsistency.value === 'atomic-snapshot'
    ? `Application consistency depends on the operator-proven atomic ${influxDb3CoreStoreUi(backupInfluxDb3CoreObjectStore()).cloud ? 'object-store' : 'filesystem'} snapshot supplied as the Source.`
    : proof.evidence;
  els.backupInfluxDb3CoreSaveSourceButton.disabled = !state.backupInfluxDb3CoreDiscovery || !els.backupInfluxDb3CoreSourceName.value.trim();
}

