async function discoverBackupSearchSnapshot() {
  const action = 'backup:connections:search-snapshot:discover';
  if (pendingActions.has(action)) return;
  if (!state.backupSearchSnapshotConnectionId && (!els.backupSearchSnapshotName.value.trim() || !els.backupSearchSnapshotHost.value.trim() || !els.backupSearchSnapshotCredential.value)) {
    els.backupSearchSnapshotError.textContent = 'Enter the HTTPS endpoint and authentication credential.';
    els.backupSearchSnapshotError.classList.remove('hidden');
    return;
  }
  pendingActions.add(action);
  setButtonLoading(els.backupSearchSnapshotDiscoverButton, true);
  els.backupSearchSnapshotError.classList.add('hidden');
  try {
    if (!state.backupSearchSnapshotConnectionId) {
      const connection = await window.deployerx.createBackupSearchSnapshotConnection({
        name: els.backupSearchSnapshotName.value.trim(), host: els.backupSearchSnapshotHost.value.trim(), port: Number(els.backupSearchSnapshotPort.value), basePath: els.backupSearchSnapshotBasePath.value.trim() || null,
        authMode: els.backupSearchSnapshotAuth.value, username: els.backupSearchSnapshotAuth.value === 'basic' ? els.backupSearchSnapshotUsername.value.trim() : null, credential: els.backupSearchSnapshotCredential.value,
        expectedProduct: els.backupSearchSnapshotProduct.value, tlsMode: 'verify-identity', caFile: els.backupSearchSnapshotCaFile.value.trim() || null,
        clientCertificateFile: els.backupSearchSnapshotClientCertificate.value.trim() || null, clientKeyFile: els.backupSearchSnapshotClientKey.value.trim() || null, timeoutMs: Number(els.backupSearchSnapshotTimeout.value)
      });
      state.backupSearchSnapshotConnectionId = connection.id;
      state.backupSearchSnapshotConnections.push(connection);
      setBackupSearchSnapshotExistingConnection(true);
      if (!els.backupSearchSnapshotSourceName.value.trim()) els.backupSearchSnapshotSourceName.value = `${connection.name} snapshots`;
    }
    const tested = await window.deployerx.testBackupSearchSnapshotConnection(state.backupSearchSnapshotConnectionId);
    if (tested.result.status !== 'success') throw new Error(tested.result.error?.safeMessage || 'The search cluster connection test failed.');
    state.backupSearchSnapshotConnections = state.backupSearchSnapshotConnections.map((connection) => connection.id === tested.connection.id ? tested.connection : connection);
    const [repositories, resources, features] = await Promise.all([
      window.deployerx.discoverBackupSearchSnapshotResources(state.backupSearchSnapshotConnectionId, 'repositories'),
      window.deployerx.discoverBackupSearchSnapshotResources(state.backupSearchSnapshotConnectionId, 'resources'),
      tested.result.endpointIdentity?.featureStatesSupported ? window.deployerx.discoverBackupSearchSnapshotResources(state.backupSearchSnapshotConnectionId, 'features') : Promise.resolve({ items: [] })
    ]);
    const writable = (repositories.items || []).filter((item) => !item.readOnly && item.selectable !== false);
    const selectable = (resources.items || []).filter((item) => item.selectable);
    if (!writable.length) throw new Error('No writable native snapshot repository is available on this cluster.');
    if (!selectable.length) throw new Error('No regular open indices or data streams are available for snapshot protection.');
    state.backupSearchSnapshotDiscovery = { identity: tested.result.endpointIdentity || {}, platform: tested.result.remotePlatform || {}, repositories: writable, resources: selectable, features: features.items || [] };
    els.backupSearchSnapshotRepository.innerHTML = writable.map((item) => `<option value="${escapeHtml(item.name)}">${escapeHtml(item.name)} - ${escapeHtml(item.type)} - writer</option>`).join('');
    els.backupSearchSnapshotResources.innerHTML = selectable.map((item) => `<label class="backup-mysql-database-option"><input type="checkbox" data-backup-search-resource="${escapeHtml(item.name)}" checked /><span><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.kind === 'search-data-stream' ? `Data stream - ${item.primaryShards} primary shards` : `Index - ${item.primaryShards} primary shards`)}</small></span></label>`).join('');
    els.backupSearchSnapshotFeatures.innerHTML = (features.items || []).length ? `<strong>Elasticsearch feature states</strong>${features.items.map((item) => `<label class="backup-mysql-database-option"><input type="checkbox" data-backup-search-feature="${escapeHtml(item.name)}" /><span><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.description || 'System feature state')}</small></span></label>`).join('')}` : '';
    const product = tested.result.endpointIdentity.product;
    els.backupSearchSnapshotGlobalState.disabled = product === 'opensearch';
    els.backupSearchSnapshotEvidence.textContent = `${product === 'opensearch' ? 'OpenSearch' : 'Elasticsearch'} ${state.backupSearchSnapshotDiscovery.platform.version || ''} - ${tested.result.endpointIdentity.clusterName || 'cluster'} - ${selectable.length} resources - verified TLS`;
    els.backupSearchSnapshotSelection.classList.remove('hidden');
    els.backupSearchSnapshotSaveSourceButton.classList.remove('hidden');
    els.backupSearchSnapshotCleanupButton.classList.remove('hidden');
    syncBackupSearchSnapshotSelection();
    renderBackupConnections();
  } catch (error) {
    state.backupSearchSnapshotDiscovery = null;
    els.backupSearchSnapshotSelection.classList.add('hidden');
    els.backupSearchSnapshotSaveSourceButton.classList.add('hidden');
    els.backupSearchSnapshotCleanupButton.classList.add('hidden');
    els.backupSearchSnapshotError.textContent = error.message || 'Could not discover the search snapshot scope.';
    els.backupSearchSnapshotError.classList.remove('hidden');
  } finally {
    pendingActions.delete(action);
    setButtonLoading(els.backupSearchSnapshotDiscoverButton, false);
  }
}

async function saveBackupSearchSnapshotSource(event) {
  event?.preventDefault();
  const discovery = state.backupSearchSnapshotDiscovery;
  if (!discovery || !state.backupSearchSnapshotConnectionId) return;
  syncBackupSearchSnapshotSelection();
  if (els.backupSearchSnapshotSaveSourceButton.disabled) return;
  const repositoryName = els.backupSearchSnapshotRepository.value;
  const action = 'backup:database-sources:search-snapshot:save';
  if (pendingActions.has(action)) return;
  pendingActions.add(action);
  setButtonLoading(els.backupSearchSnapshotSaveSourceButton, true);
  els.backupSearchSnapshotError.classList.add('hidden');
  try {
    const verified = await window.deployerx.verifyBackupSearchSnapshotRepository(state.backupSearchSnapshotConnectionId, repositoryName);
    const selectedResources = [...els.backupSearchSnapshotResources.querySelectorAll('[data-backup-search-resource]:checked')].map((input) => ({ name: input.dataset.backupSearchResource }));
    const featureStates = [...els.backupSearchSnapshotFeatures.querySelectorAll('[data-backup-search-feature]:checked')].map((input) => input.dataset.backupSearchFeature);
    await window.deployerx.saveBackupDatabaseSource({
      name: els.backupSearchSnapshotSourceName.value.trim(), connectionId: state.backupSearchSnapshotConnectionId,
      selector: { allDatabases: els.backupSearchSnapshotAllResources.checked, databases: { include: els.backupSearchSnapshotAllResources.checked ? [] : selectedResources, exclude: [] }, schemas: { include: [], exclude: [] }, tables: { include: [], exclude: [] }, includeGlobalObjects: els.backupSearchSnapshotGlobalState.checked || featureStates.length > 0 },
      consistency: { requestedLevel: 'crash', method: 'search-native-snapshot', backupMethod: 'physical', backupMode: 'native', captureCoordinates: true },
      physicalExecution: { repositoryName, repositoryFingerprint: verified.verification.repositoryFingerprint, clusterUuid: verified.verification.clusterUuid, writerClusterUuid: verified.verification.writerClusterUuid, product: verified.verification.product, includeGlobalState: els.backupSearchSnapshotGlobalState.checked, featureStates }
    });
    closeBackupSearchSnapshotModal();
    await loadBackupSources();
    showToast('Search snapshot Source saved');
  } catch (error) {
    els.backupSearchSnapshotError.textContent = error.message || 'Could not save the search snapshot Source.';
    els.backupSearchSnapshotError.classList.remove('hidden');
  } finally {
    pendingActions.delete(action);
    setButtonLoading(els.backupSearchSnapshotSaveSourceButton, false);
  }
}

async function cleanupBackupSearchSnapshotRepository() {
  const discovery = state.backupSearchSnapshotDiscovery;
  const repository = discovery?.repositories?.find((item) => item.name === els.backupSearchSnapshotRepository.value);
  if (!repository) return;
  const confirmed = await confirmDangerousAction('Clean unused native repository blobs?', `${repository.name}\nThe cluster native cleanup API will remove only unreferenced blobs.`, 'Clean repository');
  if (!confirmed) return;
  const result = await window.deployerx.cleanupBackupSearchSnapshotRepository({ connectionId: state.backupSearchSnapshotConnectionId, repositoryName: repository.name, repositoryFingerprint: repository.repositoryFingerprint, confirmationText: 'CLEANUP SEARCH REPOSITORY' });
  showToast(`Native cleanup removed ${result.deletedBlobs || 0} blobs (${formatBytes(result.deletedBytes || 0)}).`);
}

function backupScyllaManagerList(value) {
  return [...new Set(String(value || '').split(/[\n,]+/).map((item) => item.trim()).filter(Boolean))];
}

function backupScyllaManagerScope() {
  const patterns = backupScyllaManagerList(els.backupScyllaManagerUnits.value);
  const allDatabases = patterns.includes('*.*');
  const databases = [];
  const tables = [];
  for (const pattern of patterns) {
    if (pattern === '*.*') continue;
    const match = /^([A-Za-z0-9_]+)\.([A-Za-z0-9_*]+)$/.exec(pattern);
    if (!match) throw new Error(`Invalid Manager scope: ${pattern}. Use keyspace.table or keyspace.*.`);
    if (match[2] === '*') databases.push({ name: match[1] });
    else tables.push({ database: match[1], schema: match[1], name: match[2] });
  }
  if (!allDatabases && !databases.length && !tables.length) throw new Error('Enter at least one keyspace.table or keyspace.* scope.');
  return { patterns, selector: { allDatabases, databases: { include: databases, exclude: [] }, schemas: { include: [], exclude: [] }, tables: { include: tables, exclude: [] }, includeGlobalObjects: false } };
}

function backupScyllaManagerExecution() {
  return {
    managedClusterId: state.backupScyllaManagerDiscovery?.managedClusterId || els.backupScyllaManagerClusterId.value.trim(),
    locations: backupScyllaManagerList(els.backupScyllaManagerLocations.value), dataCenters: backupScyllaManagerList(els.backupScyllaManagerDataCenters.value),
    method: els.backupScyllaManagerMethod.value, retention: Number(els.backupScyllaManagerRetention.value), retentionDays: Number(els.backupScyllaManagerRetentionDays.value),
    retentionLockMode: els.backupScyllaManagerRetentionLock.value, rateLimit: backupScyllaManagerList(els.backupScyllaManagerRateLimit.value),
    snapshotParallel: backupScyllaManagerList(els.backupScyllaManagerSnapshotParallel.value), uploadParallel: backupScyllaManagerList(els.backupScyllaManagerUploadParallel.value),
    transfers: Number(els.backupScyllaManagerTransfers.value), schedule: { cron: els.backupScyllaManagerCron.value.trim() || null, timezone: els.backupScyllaManagerTimezone.value.trim() || null }
  };
}

function backupScyllaManagerTaskUpdate() {
  const scope = backupScyllaManagerScope();
  const execution = backupScyllaManagerExecution();
  return {
    scope, execution,
    taskUpdate: { name: 'deployerx-target-validation', type: 'backup', labels: { 'deployerx.owner': 'deployerx', 'deployerx.purpose': 'target-validation' }, enabled: false, schedule: execution.schedule, properties: { location: execution.locations, keyspace: scope.patterns, dc: execution.dataCenters, method: execution.method, retention: execution.retention, retention_days: execution.retentionDays, retention_lock_mode: execution.retentionLockMode, rate_limit: execution.rateLimit, snapshot_parallel: execution.snapshotParallel, upload_parallel: execution.uploadParallel, transfers: execution.transfers, skip_schema: false, purge_only: false } }
  };
}

