async function discoverBackupSqlite() {
  const action = 'backup:connections:sqlite:discover';
  if (pendingActions.has(action)) return;
  if (!state.backupSqliteConnectionId && (!els.backupSqliteName.value.trim() || !els.backupSqliteDatabasePath.value.trim() || !els.backupSqliteExecutable.value.trim())) {
    els.backupSqliteError.textContent = 'Enter a connection name, canonical database path, and sqlite3 executable.';
    els.backupSqliteError.classList.remove('hidden');
    return;
  }
  pendingActions.add(action);
  setButtonLoading(els.backupSqliteDiscoverButton, true);
  els.backupSqliteError.classList.add('hidden');
  try {
    if (!state.backupSqliteConnectionId) {
      const connection = await window.deployerx.createBackupSqliteConnection({
        name: els.backupSqliteName.value.trim(),
        databasePath: els.backupSqliteDatabasePath.value.trim(),
        sqliteExecutable: els.backupSqliteExecutable.value.trim(),
        timeoutMs: Number(els.backupSqliteTimeout.value)
      });
      state.backupSqliteConnectionId = connection.id;
      setBackupSqliteExistingConnection(true);
      if (!els.backupSqliteSourceName.value.trim()) els.backupSqliteSourceName.value = `${connection.name} database`;
    }
    const tested = await window.deployerx.testBackupSqliteConnection(state.backupSqliteConnectionId);
    await loadBackupConnections();
    if (tested.result.status !== 'success') throw new Error(tested.result.error?.safeMessage || 'The SQLite connection test failed.');
    const discovered = await window.deployerx.discoverBackupSqliteDatabases(state.backupSqliteConnectionId, { kind: 'database' });
    const main = (discovered.items || []).find((item) => item.name === 'main' && item.selectable !== false);
    if (!main) throw new Error('The complete SQLite main database was not discovered.');
    state.backupSqliteDiscovery = { main, identity: tested.result.endpointIdentity || {}, platform: tested.result.remotePlatform || {} };
    const identity = state.backupSqliteDiscovery.identity;
    els.backupSqliteDatabaseEvidence.textContent = `${Number(main.objectCount ?? identity.objectCount ?? 0)} schema objects - ${identity.journalMode || 'journal mode unknown'}`;
    els.backupSqliteEvidence.innerHTML = `<strong>Online backup ready</strong><span>SQLite ${escapeHtml(state.backupSqliteDiscovery.platform.version || '3.38+')} - page size ${escapeHtml(String(identity.pageSize || 'unknown'))} - quick_check passed - complete main database</span>`;
    els.backupSqliteSelection.classList.remove('hidden');
    els.backupSqliteSaveSourceButton.classList.remove('hidden');
    els.backupSqliteSaveSourceButton.disabled = !els.backupSqliteSourceName.value.trim();
    showToast('SQLite main database is ready for online backup.');
  } catch (error) {
    state.backupSqliteDiscovery = null;
    els.backupSqliteSelection.classList.add('hidden');
    els.backupSqliteSaveSourceButton.classList.add('hidden');
    els.backupSqliteError.textContent = error.message || 'Could not validate the SQLite database.';
    els.backupSqliteError.classList.remove('hidden');
  } finally {
    pendingActions.delete(action);
    setButtonLoading(els.backupSqliteDiscoverButton, false);
  }
}

