    optionButton.setAttribute('aria-selected', 'false');
    optionButton.tabIndex = -1;
    optionLabel.textContent = option.textContent;
    optionButton.appendChild(optionLabel);
    els.workspaceSetupMenu.appendChild(optionButton);
