async function importLocalToCloud() {
  if (!state.teams.activeTeamId) return;
  const ok = await confirmDangerousAction(
    'Import local servers and templates to this cloud team?',
    'Items with the same id will be overwritten in the active cloud team.',
    'Import'
  );
  if (!ok) return;
  try {
    const result = await window.deployerx.importLocalToCloud();
    await refreshProjectsAndTemplates();
    showToast(`Imported ${result.projectCount} project${result.projectCount === 1 ? '' : 's'} and ${result.templateCount} template${result.templateCount === 1 ? '' : 's'}`);
  } catch (error) {
    showAlert(error.message || 'Could not import local data.');
  }
}

async function initializeApp() {
  try {
    hydrateStartupMetadata();
    refreshAppUpdateState().catch(() => {});
    const setup = await withTimeout(
      window.deployerx.getSetup(),
      STARTUP_IPC_TIMEOUT_MS,
      'Startup took too long. Please try again.'
    );
    applySetupState(setup);
    updateAuthMode('login');
    renderTeamView();

    if (!state.setup.complete || !state.setup.mode) {
      setSetupVisibility(true);
      showAuthPanel();
      return;
    }

    if (state.setup.mode === 'offline') {
      setSetupVisibility(false);
      showView('dashboard');
      await loadProjects();
      return;
    }

    const sessionRefreshPromise = refreshCloudSession();
    let sessionResult;
    try {
      sessionResult = await withTimeout(
        sessionRefreshPromise,
        CLOUD_SESSION_TIMEOUT_MS,
        'Cloud session took too long to refresh.'
      );
    } catch (error) {
      if (!state.auth.session) {
        const latestSetup = await window.deployerx.getSetup().catch(() => null);
        if (latestSetup) applySetupState(latestSetup);
      }

      sessionRefreshPromise
        .then(async (lateResult) => {
          if (!lateResult.session) {
            setSetupVisibility(true);
            showAuthPanel();
            return;
          }
          if (sessionRequiresVerification(lateResult)) {
            showEmailVerificationNotice(lateResult.session.email || '');
            return;
          }
          if (state.setup.mode === 'cloud') await continueCloudStartup();
        })
        .catch(() => {});

      if (state.auth.session) {
        showToast('Restored your saved session while cloud sync reconnects.');
        await continueCloudStartup();
      } else {
        setSetupVisibility(true);
        showAuthPanel();
        showToast('Cloud connection is taking longer than usual.');
      }
      return;
    }

    if (!sessionResult.session) {
      setSetupVisibility(true);
      showAuthPanel();
      return;
    }
    if (sessionRequiresVerification(sessionResult)) {
      showEmailVerificationNotice(sessionResult.session.email || '');
      return;
    }

    await continueCloudStartup();
  } catch (error) {
    showAlert(error.message || 'Could not initialize DeployerX.');
    setSetupVisibility(true);
    showAuthPanel();
  }
}

function createModalSshUser() {
  return {
    id: `ssh-user-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    username: '',
    authType: 'password',
    password: '',
    privateKey: '',
    passphrase: ''
  };
}

function activeModalSshUser() {
  return state.modalSshUsers.find((user) => user.id === state.modalSelectedSshUserId) || null;
}

function clearModalSshUserValidity() {
  [els.modalSshUsername, els.modalSshPassword, els.modalPrivateKey].forEach((field) => field?.setCustomValidity(''));
}

function saveActiveModalSshUser() {
  const user = activeModalSshUser();
  if (!user) return;
  user.username = els.modalSshUsername.value.trim();
  user.authType = els.modalAuthType.value === 'key' ? 'key' : 'password';
  user.password = els.modalSshPassword.value;
  user.privateKey = els.modalPrivateKey.value;
  user.passphrase = els.modalKeyPassphrase.value;
}

function renderModalSshUsers() {
  if (!els.modalSshUserTabs) return;
  els.modalSshUserTabs.replaceChildren(...state.modalSshUsers.map((user, index) => {
    const button = document.createElement('button');
    const selected = user.id === state.modalSelectedSshUserId;
    button.type = 'button';
    button.className = `ssh-user-tab${selected ? ' active' : ''}`;
    button.dataset.sshUserId = user.id;
    button.setAttribute('role', 'tab');
    button.setAttribute('aria-selected', String(selected));
    button.tabIndex = selected ? 0 : -1;

    const label = document.createElement('span');
    label.textContent = user.username || `User ${index + 1}`;
    button.appendChild(label);
    if (user.id === state.modalDraft.ssh.defaultUserId) {
      const badge = document.createElement('small');
      badge.textContent = 'Default';
      button.appendChild(badge);
    }
    return button;
  }));

  const selectedUser = activeModalSshUser();
  const isDefault = selectedUser?.id === state.modalDraft.ssh.defaultUserId;
  els.modalSshUserEditorTitle.textContent = selectedUser?.username || 'New SSH user';
  els.modalSshUserEditorStatus.textContent = isDefault ? 'Default connection user' : 'Additional connection user';
  els.modalDefaultSshUserButton.disabled = Boolean(isDefault);
  els.modalDefaultSshUserButton.textContent = isDefault ? 'Default user' : 'Use as default';
  els.modalRemoveSshUserButton.disabled = state.modalSshUsers.length <= 1;
}

function loadActiveModalSshUser() {
  let user = activeModalSshUser();
  if (!user) {
    user = state.modalSshUsers[0] || createModalSshUser();
    if (!state.modalSshUsers.length) state.modalSshUsers.push(user);
    state.modalSelectedSshUserId = user.id;
  }
  clearModalSshUserValidity();
  els.modalSshUsername.value = user.username;
  els.modalAuthType.value = user.authType;
  els.modalSshPassword.value = user.password;
  els.modalPrivateKey.value = user.privateKey;
  els.modalKeyPassphrase.value = user.passphrase;
  resetSecretVisibility(els.modalSshFields);
  updateAuthFields();
  renderModalSshUsers();
}

function selectModalSshUser(userId) {
  if (!state.modalSshUsers.some((user) => user.id === userId)) return;
  saveActiveModalSshUser();
  state.modalSelectedSshUserId = userId;
  loadActiveModalSshUser();
}

function addModalSshUser() {
  saveActiveModalSshUser();
  const user = createModalSshUser();
  state.modalSshUsers.push(user);
  state.modalSelectedSshUserId = user.id;
  loadActiveModalSshUser();
  requestAnimationFrame(() => els.modalSshUsername.focus());
}

function removeActiveModalSshUser() {
  if (state.modalSshUsers.length <= 1) return;
  const removedIndex = state.modalSshUsers.findIndex((user) => user.id === state.modalSelectedSshUserId);
  if (removedIndex < 0) return;
  const [removedUser] = state.modalSshUsers.splice(removedIndex, 1);
  if (state.modalDraft.ssh.defaultUserId === removedUser.id) {
    state.modalDraft.ssh.defaultUserId = state.modalSshUsers[0].id;
  }
  state.modalSelectedSshUserId = state.modalSshUsers[Math.min(removedIndex, state.modalSshUsers.length - 1)].id;
  loadActiveModalSshUser();
}

function makeActiveModalSshUserDefault() {
  saveActiveModalSshUser();
  const user = activeModalSshUser();
  if (!user) return;
  state.modalDraft.ssh.defaultUserId = user.id;
  renderModalSshUsers();
}

function validateModalSshUsers() {
  saveActiveModalSshUser();
  clearModalSshUserValidity();
  const usernames = new Set();
  for (const user of state.modalSshUsers) {
    let field = null;
    let message = '';
    const normalizedUsername = user.username.toLowerCase();
    if (!user.username) {
      field = els.modalSshUsername;
      message = 'Enter a username for this SSH user.';
    } else if (usernames.has(normalizedUsername)) {
      field = els.modalSshUsername;
      message = 'Each SSH user must have a unique username.';
    } else if (user.authType === 'key' && !user.privateKey.trim()) {
      field = els.modalPrivateKey;
      message = `Enter a private key for ${user.username}.`;
    } else if (user.authType !== 'key' && !user.password) {
      field = els.modalSshPassword;
      message = `Enter a password for ${user.username}.`;
    }
    usernames.add(normalizedUsername);
    if (!field) continue;
    selectModalSshUser(user.id);
    field.setCustomValidity(message);
    requestAnimationFrame(() => {
      field.focus();
      field.reportValidity();
    });
    return false;
  }
  return true;
}

const projectModalStepDescriptions = [
  'Start with the server name, group, and command template.',
  'Add one or more SSH users and choose the default connection.',
  'Optionally configure FTP or reuse the SSH connection.'
];

function isRdpModal() {
  return els.modalServerType?.value === 'rdp';
}

function getProjectModalSteps() {
  const panels = isRdpModal()
    ? els.projectModalStepPanels.filter((panel) => panel.id !== 'projectStepPanelFtp')
    : els.projectModalStepPanels;
  const buttons = isRdpModal()
    ? els.projectModalStepButtons.filter((button) => button.id !== 'projectStepButtonFtp')
    : els.projectModalStepButtons;
  return { panels, buttons };
}

function updateModalConnectionMode() {
  const rdp = isRdpModal();
  els.modalTemplateField?.classList.toggle('hidden', rdp);
  els.modalTemplateSelect.disabled = rdp;
  els.modalTemplateButton.disabled = rdp;
  els.modalSshFields?.classList.toggle('hidden', rdp);
  els.modalRdpFields?.classList.toggle('hidden', !rdp);
  [els.modalSshHost, els.modalSshPort, els.modalSshUsername, els.modalAuthType, els.modalSshPassword, els.modalPrivateKey, els.modalKeyPassphrase]
    .filter(Boolean)
    .forEach((field) => { field.disabled = rdp; });
  [els.modalRdpHost, els.modalRdpPort, els.modalRdpUsername, els.modalRdpDomain, els.modalRdpPassword]
    .filter(Boolean)
    .forEach((field) => { field.disabled = !rdp; });
  els.modalRdpHost.required = rdp;
  els.modalRdpUsername.required = rdp;
  els.modalRdpPassword.required = rdp;
  els.modalSshHost.required = !rdp;
  els.modalSshUsername.required = !rdp;
  els.projectConnectionStepLabel.textContent = rdp ? 'Windows' : 'SSH';
  const ftpStepButton = els.projectModalStepButtons.find((button) => button.id === 'projectStepButtonFtp');
  ftpStepButton?.closest('.server-wizard-progress')?.classList.toggle('windows-flow', rdp);
  ftpStepButton?.closest('.server-wizard-step-item')?.classList.toggle('hidden', rdp);
  els.projectModalStepPanels.find((panel) => panel.id === 'projectStepPanelFtp')?.classList.toggle('hidden', rdp || state.modalStep !== 2);
  if (rdp && state.modalStep > 1) setProjectModalStep(1, { focus: false });
}

function setProjectModalStep(step, { focus = true } = {}) {
  const { panels, buttons } = getProjectModalSteps();
  const nextStep = Math.max(0, Math.min(step, panels.length - 1));
  state.modalStep = nextStep;

  els.projectModalStepPanels.forEach((panel) => {
    const index = panels.indexOf(panel);
    const active = index === nextStep;
    panel.classList.toggle('hidden', !active);
    panel.setAttribute('aria-hidden', active ? 'false' : 'true');
  });

  els.projectModalStepButtons.forEach((button) => {
    const index = buttons.indexOf(button);
    const active = index === nextStep;
    button.classList.toggle('active', active);
    button.classList.toggle('completed', index >= 0 && index < nextStep);
    if (active) button.setAttribute('aria-current', 'step');
    else button.removeAttribute('aria-current');
  });

  els.projectModalSubtitle.textContent = rdpStepDescription(nextStep);
  els.projectModalBackButton.classList.toggle('hidden', nextStep === 0);
  els.projectModalNextButton.classList.toggle('hidden', nextStep === panels.length - 1);
  els.projectModalSaveButton.classList.toggle('hidden', nextStep !== panels.length - 1);

  if (!focus) return;
  const firstField = panels[nextStep]?.querySelector('input:not([disabled]), select:not([disabled]), textarea:not([disabled])');
  requestAnimationFrame(() => firstField?.focus());
}

function rdpStepDescription(step) {
  if (isRdpModal() && step === 0) return 'Name the Windows server and choose where it belongs.';
  if (isRdpModal() && step === 1) return 'Add the Windows Remote Desktop credentials used to connect to this server.';
  return projectModalStepDescriptions[step];
}

function validateProjectModalStep(step) {
  const panel = getProjectModalSteps().panels[step];
  if (!panel) return true;
  if (panel.id === 'projectStepPanelSsh' && !isRdpModal() && !validateModalSshUsers()) return false;

  const invalidField = Array.from(panel.querySelectorAll('input, select, textarea')).find(
    (field) => !field.checkValidity()
  );
  if (!invalidField) return true;

  setProjectModalStep(step, { focus: false });
  requestAnimationFrame(() => {
    invalidField.focus();
    invalidField.reportValidity();
  });
  return false;
}

function navigateProjectModalStep(step) {
  const { panels } = getProjectModalSteps();
  const targetStep = Math.max(0, Math.min(step, panels.length - 1));

  if (targetStep > state.modalStep) {
    while (state.modalStep < targetStep) {
      if (!validateProjectModalStep(state.modalStep)) return;
      setProjectModalStep(state.modalStep + 1, { focus: false });
    }
  } else {
    setProjectModalStep(targetStep, { focus: false });
  }

  const firstField = panels[targetStep]?.querySelector('input:not([disabled]), select:not([disabled]), textarea:not([disabled])');
  requestAnimationFrame(() => firstField?.focus());
}

function fillModal(project) {
  const normalizedProject = normalizeProject(project);
  state.modalDraft = structuredClone(normalizedProject);
  resetSecretVisibility(els.projectModal);
  els.modalProjectName.value = normalizedProject.name || '';
  renderProjectGroupOptions(normalizedProject.group || '');
  els.modalServerType.value = normalizedProject.serverType || 'ubuntu';
  renderModalServerTypeSelect();
  renderTemplateSelect();
  els.modalTemplateSelect.value = '';
  renderModalTemplateDropdown();
  els.modalSshHost.value = normalizedProject.ssh?.host || '';
  els.modalSshPort.value = normalizedProject.ssh?.port || 22;
  state.modalSshUsers = structuredClone(normalizedProject.ssh.users);
  state.modalSelectedSshUserId = normalizedProject.ssh.defaultUserId;
  loadActiveModalSshUser();
  els.modalRdpHost.value = normalizedProject.rdp?.host || '';
  els.modalRdpPort.value = normalizedProject.rdp?.port || 3389;
  els.modalRdpUsername.value = normalizedProject.rdp?.username || '';
  els.modalRdpDomain.value = normalizedProject.rdp?.domain || '';
  els.modalRdpPassword.value = normalizedProject.rdp?.password || '';
  els.modalFtpHost.value = normalizedProject.ftp?.host || '';
  els.modalFtpPort.value = normalizedProject.ftp?.port || '';
  els.modalFtpUsername.value = normalizedProject.ftp?.username || '';
  els.modalFtpAuthType.value = normalizedProject.ftp?.authType || (normalizedProject.ftp?.privateKey ? 'key' : normalizedProject.ftp?.password ? 'password' : '');
  els.modalFtpPassword.value = normalizedProject.ftp?.password || '';
  els.modalFtpPrivateKey.value = normalizedProject.ftp?.privateKey || '';
  els.modalFtpKeyPassphrase.value = normalizedProject.ftp?.passphrase || '';
  updateAuthFields();
  updateFtpAuthFields();
  updateModalConnectionMode();
}

function readModalProject() {
  saveActiveModalSshUser();
  const selectedTemplate = state.templates.find((template) => template.id === els.modalTemplateSelect.value);
  const ftpAuthType = els.modalFtpAuthType.value;
  const rdp = isRdpModal();
  const emptyProject = blankProject();

  const project = {
    ...state.modalDraft,
    name: els.modalProjectName.value.trim(),
    group: els.modalProjectGroup.value.trim(),
    serverType: els.modalServerType.value,
    variables: normalizeVariables(state.modalDraft.variables),
    ssh: rdp ? emptyProject.ssh : normalizeSshConnection({
      host: els.modalSshHost.value.trim(),
      port: Number(els.modalSshPort.value || 22),
      timeout: 20000,
      users: structuredClone(state.modalSshUsers),
      defaultUserId: state.modalDraft.ssh.defaultUserId
    }, emptyProject.ssh),
    rdp: {
      host: els.modalRdpHost.value.trim(),
      port: Number(els.modalRdpPort.value || 3389),
      username: els.modalRdpUsername.value.trim(),
      domain: els.modalRdpDomain.value.trim(),
      password: els.modalRdpPassword.value
    },
    ftp: rdp ? emptyProject.ftp : {
      host: els.modalFtpHost.value.trim(),
      port: els.modalFtpPort.value ? Number(els.modalFtpPort.value) : '',
      username: els.modalFtpUsername.value.trim(),
      authType: ftpAuthType,
      password: ftpAuthType === 'password' ? els.modalFtpPassword.value : '',
      privateKey: ftpAuthType === 'key' ? els.modalFtpPrivateKey.value : '',
      passphrase: ftpAuthType === 'key' ? els.modalFtpKeyPassphrase.value : ''
    }
  };

  project.commands = rdp ? [] : selectedTemplate ? selectedTemplate.commands || [] : state.modalDraft.commands || [];

  return project;
}

function syncServerFilterSelect(select, options) {
  if (!select) return;
  const selectedValue = select.value;
  const currentSignature = Array.from(select.options).map((option) => `${option.value}:${option.textContent}`).join('|');
  const nextSignature = options.map((option) => `${option.value}:${option.label}`).join('|');
  if (currentSignature === nextSignature) return;
  select.replaceChildren(...options.map(({ value, label }) => {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = label;
    return option;
  }));
  select.value = options.some((option) => option.value === selectedValue) ? selectedValue : '';
}

function serverFilterDropdowns() {
  return [
    { name: 'Group', dropdown: els.serversFilterGroupDropdown, select: els.serversFilterGroup, button: els.serversFilterGroupButton, label: els.serversFilterGroupLabel, menu: els.serversFilterGroupMenu },
    { name: 'System', dropdown: els.serversFilterSystemDropdown, select: els.serversFilterSystem, button: els.serversFilterSystemButton, label: els.serversFilterSystemLabel, menu: els.serversFilterSystemMenu },
    { name: 'Connection', dropdown: els.serversFilterConnectionDropdown, select: els.serversFilterConnection, button: els.serversFilterConnectionButton, label: els.serversFilterConnectionLabel, menu: els.serversFilterConnectionMenu },
    { name: 'Commands', dropdown: els.serversFilterCommandsDropdown, select: els.serversFilterCommands, button: els.serversFilterCommandsButton, label: els.serversFilterCommandsLabel, menu: els.serversFilterCommandsMenu },
    { name: 'Sort by', dropdown: els.serversFilterSortDropdown, select: els.serversFilterSort, button: els.serversFilterSortButton, label: els.serversFilterSortLabel, menu: els.serversFilterSortMenu }
  ];
}

function closeServerFilterDropdown(config, { focusTrigger = false } = {}) {
  config.dropdown.classList.remove('is-open');
  config.menu.classList.add('hidden');
  config.button.setAttribute('aria-expanded', 'false');
  if (focusTrigger) config.button.focus();
}

function closeServerFilterDropdowns({ except = null } = {}) {
  for (const config of serverFilterDropdowns()) {
    if (config.dropdown !== except?.dropdown) closeServerFilterDropdown(config);
  }
}

function renderServerFilterDropdown(config) {
  const options = Array.from(config.select.options);
  const selected = options.find((option) => option.value === config.select.value) || options[0];
  if (!selected) return;
  config.select.value = selected.value;
  config.label.textContent = selected.textContent;
  config.button.setAttribute('aria-label', `${config.name}: ${selected.textContent}`);
  config.menu.replaceChildren();
  for (const option of options) {
    const optionButton = document.createElement('button');
    const isSelected = option.value === selected.value;
    optionButton.type = 'button';
    optionButton.className = 'workspace-switcher-option';
    optionButton.dataset.serverFilterValue = option.value;
    optionButton.setAttribute('role', 'option');
    optionButton.setAttribute('aria-selected', String(isSelected));
    optionButton.tabIndex = -1;
    optionButton.innerHTML = `<span>${escapeHtml(option.textContent)}</span>${isSelected ? icon('check') : ''}`;
    config.menu.appendChild(optionButton);
  }
  closeServerFilterDropdown(config);
}

function renderServerFilterDropdowns() {
  for (const config of serverFilterDropdowns()) renderServerFilterDropdown(config);
}

function openServerFilterDropdown(config) {
  closeServerFilterDropdowns({ except: config });
  config.dropdown.classList.add('is-open');
  config.menu.classList.remove('hidden');
  config.button.setAttribute('aria-expanded', 'true');
  requestAnimationFrame(() => {
    const selected = config.menu.querySelector('[aria-selected="true"]');
    (selected || config.menu.querySelector('.workspace-switcher-option'))?.focus();
  });
}

function positionServerFilterPanel() {
  const trigger = els.serversFilterButton.getBoundingClientRect();
  const header = els.serversFilterButton.closest('.servers-view-header')?.getBoundingClientRect();
  const viewportPadding = window.innerWidth <= 520 ? 18 : 24;
  const width = Math.min(360, window.innerWidth - (viewportPadding * 2));
  const left = Math.min(
    Math.max(viewportPadding, trigger.right - width),
    window.innerWidth - width - viewportPadding
  );
  els.serverFilterPanel.style.width = `${width}px`;
  els.serverFilterPanel.style.left = `${left}px`;
  els.serverFilterPanel.style.top = `${(header?.bottom || trigger.bottom) + 8}px`;
}

function setServerFilterPanel(open) {
  const visible = Boolean(open);
  els.serverFilterPanel.classList.toggle('hidden', !visible);
  els.serversFilterButton.setAttribute('aria-expanded', String(visible));
  if (visible) positionServerFilterPanel();
  if (!visible) closeServerFilterDropdowns();
}

function syncServerFilterOptions() {
  const groups = [...new Set(state.projects.map((project) => serverGroupName(project)))]
    .sort((first, second) => first.localeCompare(second));
  syncServerFilterSelect(els.serversFilterGroup, [
    { value: '', label: 'All groups' },
    ...groups.map((group) => ({ value: group === 'Ungrouped' ? '__ungrouped__' : group, label: group }))
  ]);

  const systems = [...new Set(state.projects.map((project) => String(project.serverType || 'custom').toLowerCase()))]
    .sort((first, second) => serverTypeLabel(first).localeCompare(serverTypeLabel(second)));
  syncServerFilterSelect(els.serversFilterSystem, [
    { value: '', label: 'All systems' },
    ...systems.map((system) => ({ value: system, label: serverTypeLabel(system) }))
  ]);
  renderServerFilterDropdowns();
}

function serverFilterCriteria() {
  return {
    query: els.serversFilterSearch?.value.trim().toLowerCase() || '',
    group: els.serversFilterGroup?.value || '',
    system: els.serversFilterSystem?.value || '',
    connection: els.serversFilterConnection?.value || '',
    commands: els.serversFilterCommands?.value || '',
    sort: els.serversFilterSort?.value || 'name',
    favorites: Boolean(els.serversFilterFavorites?.checked)
  };
}

function serverPrimaryConnectionActive(project) {
  const connection = projectConnectionState(project.id);
  return project.serverType === 'rdp' ? connection.rdp : connection.ssh || connection.ftp;
}

function filteredServerProjects(projects = state.projects) {
  const filters = serverFilterCriteria();
  return projects.filter((project) => {
    const connection = projectConnectionState(project.id);
    const isConnected = project.serverType === 'rdp' ? connection.rdp : connection.ssh || connection.ftp;
    const searchText = [
      project.name,
      serverGroupName(project),
      serverTypeLabel(project.serverType),
      serverHost(project),
      project.ssh?.username,
      project.rdp?.username,
      ...(Array.isArray(project.commands) ? project.commands : [])
    ].filter(Boolean).join(' ').toLowerCase();
    if (filters.query && !searchText.includes(filters.query)) return false;
    if (filters.group === '__ungrouped__' && serverGroupName(project) !== 'Ungrouped') return false;
    if (filters.group && filters.group !== '__ungrouped__' && serverGroupName(project) !== filters.group) return false;
    if (filters.system && String(project.serverType || 'custom').toLowerCase() !== filters.system) return false;
    if (filters.connection === 'connected' && !isConnected) return false;
    if (filters.connection === 'disconnected' && isConnected) return false;
    if (filters.connection === 'ssh' && !connection.ssh) return false;
    if (filters.connection === 'ftp' && !connection.ftp) return false;
    if (filters.connection === 'rdp' && !connection.rdp) return false;
    if (filters.commands === 'with' && !project.commands?.length) return false;
    if (filters.commands === 'without' && project.commands?.length) return false;
    if (filters.favorites && !project.pinned) return false;
    return true;
  });
}

function sortServerProjects(projects, sort = serverFilterCriteria().sort) {
  const nameCompare = (first, second) => (first.name || '').localeCompare(second.name || '');
  return [...projects].sort((first, second) => {
    if (sort === 'name-desc') return -nameCompare(first, second);
    if (sort === 'recent') return String(second.updatedAt || '').localeCompare(String(first.updatedAt || '')) || nameCompare(first, second);
    if (sort === 'commands') return (second.commands?.length || 0) - (first.commands?.length || 0) || nameCompare(first, second);
    if (sort === 'connection') return Number(serverPrimaryConnectionActive(second)) - Number(serverPrimaryConnectionActive(first)) || nameCompare(first, second);
    return nameCompare(first, second);
  });
}

function activeServerFilterCount(filters = serverFilterCriteria()) {
  return Number(Boolean(filters.query))
    + Number(Boolean(filters.group))
    + Number(Boolean(filters.system))
    + Number(Boolean(filters.connection))
    + Number(Boolean(filters.commands))
    + Number(filters.favorites)
    + Number(filters.sort !== 'name');
}

function dashboardBackupRunStateLabel(stateValue) {
  return ({ queued: 'Queued', preparing: 'Preparing', running: 'Running', verifying: 'Verifying', succeeded: 'Succeeded', failed: 'Failed', canceled: 'Canceled', canceled_by_user: 'Canceled' })[stateValue] || stateValue || 'Unknown';
}

function dashboardOperationEmpty(target, message, tone = 'neutral') {
  if (!target) return;
  target.innerHTML = `<div class="dashboard-operation-empty ${tone}"><span class="operation-status-dot"></span><span>${escapeHtml(message)}</span></div>`;
}

function renderDashboardOperations() {
  const uptimeTarget = els.dashboardUptimeAlerts;
  const backupTarget = els.dashboardBackupStatus;
  const databaseTarget = els.dashboardDatabaseStatus;
  if (!dashboardOperationsLoaded) {
    dashboardOperationEmpty(uptimeTarget, 'Loading uptime telemetry...');
    dashboardOperationEmpty(backupTarget, 'Loading backup protection...');
    dashboardOperationEmpty(databaseTarget, 'Loading database estate...');
    return;
  }

  const activeIncidents = (state.uptime.incidents || [])
    .filter((incident) => incident.state !== 'resolved')
    .sort((left, right) => String(right.openedAt || '').localeCompare(String(left.openedAt || '')));
  const uptimeMonitors = state.uptime.monitors || [];
  if (activeIncidents.length) {
    uptimeTarget.innerHTML = activeIncidents.slice(0, 4).map((incident) => {
      const monitor = uptimeMonitors.find((item) => item.id === incident.monitorId);
      const severity = String(incident.severity || 'warning').toLowerCase();
      return `<button class="dashboard-operation-row" type="button" data-dashboard-uptime-incident="${escapeHtml(incident.id)}">
        <span class="operation-status-dot ${severity === 'critical' ? 'is-danger' : 'is-warning'}"></span>
        <span class="dashboard-operation-copy"><strong>${escapeHtml(monitor?.name || incident.monitorId || 'Uptime monitor')}</strong><small>${escapeHtml(incident.summary || `${severity} alert`)} - ${escapeHtml(formatDateTime(incident.openedAt))}</small></span>
        <span class="operation-status is-warning">${escapeHtml(severity)}</span>
      </button>`;
    }).join('');
  } else if (!uptimeMonitors.length) {
    dashboardOperationEmpty(uptimeTarget, 'No uptime monitors configured.');
  } else {
    dashboardOperationEmpty(uptimeTarget, `${uptimeMonitors.length} monitor${uptimeMonitors.length === 1 ? '' : 's'} healthy.`, 'is-good');
  }

  const activeRuns = (state.backupRuns || []).filter(isActiveBackupRun);
  const latestRun = [...(state.backupRuns || [])].sort((left, right) => String(right.createdAt || right.startedAt || '').localeCompare(String(left.createdAt || left.startedAt || '')))[0];
  const completedRuns = (state.backupRuns || []).filter((run) => ['succeeded', 'failed', 'canceled'].includes(run.state));
  const successfulRuns = completedRuns.filter((run) => run.state === 'succeeded').length;
  if (!state.backupJobs.length && !state.backupRuns.length) {
    dashboardOperationEmpty(backupTarget, 'No backup jobs configured.');
  } else {
    backupTarget.innerHTML = `
      <div class="dashboard-operation-summary"><strong>${activeRuns.length ? `${activeRuns.length} backup${activeRuns.length === 1 ? '' : 's'} in progress` : 'No backup currently running'}</strong><span class="operation-status ${activeRuns.length ? 'is-warning' : 'is-good'}">${state.backupWorker?.online ? 'Worker online' : 'Worker offline'}</span></div>
      <div class="dashboard-operation-metrics"><span><strong>${state.backupJobs.length}</strong><small>Configured jobs</small></span><span><strong>${successfulRuns}/${completedRuns.length || 0}</strong><small>Successful runs</small></span></div>
      ${latestRun ? `<button class="dashboard-operation-row" type="button" data-dashboard-backup-run="${escapeHtml(latestRun.id)}"><span class="operation-status-dot ${latestRun.state === 'succeeded' ? 'is-good' : isActiveBackupRun(latestRun) ? 'is-warning' : 'is-danger'}"></span><span class="dashboard-operation-copy"><strong>${escapeHtml(state.backupJobs.find((job) => job.id === latestRun.jobId)?.name || 'Backup run')}</strong><small>${escapeHtml(dashboardBackupRunStateLabel(latestRun.state))} - ${escapeHtml(formatDateTime(latestRun.completedAt || latestRun.startedAt || latestRun.createdAt))}</small></span><span class="operation-status ${latestRun.state === 'succeeded' ? 'is-good' : isActiveBackupRun(latestRun) ? 'is-warning' : 'is-danger'}">${escapeHtml(dashboardBackupRunStateLabel(latestRun.state))}</span></button>` : ''}
    `;
  }

  const profiles = state.databaseManager.profiles || [];
  const readyProfiles = profiles.filter((profile) => state.databaseManager.connectionStates.get(profile.id) === 'ready').length;
  const failedProfiles = profiles.filter((profile) => state.databaseManager.connectionStates.get(profile.id) === 'failed').length;
  if (!profiles.length) {
    dashboardOperationEmpty(databaseTarget, 'No database profiles configured.');
  } else {
    const attentionProfiles = profiles.filter((profile) => state.databaseManager.connectionStates.get(profile.id) === 'failed').slice(0, 3);
    databaseTarget.innerHTML = `
      <div class="dashboard-operation-summary"><strong>${readyProfiles} of ${profiles.length} profiles connected</strong><span class="operation-status ${failedProfiles ? 'is-danger' : 'is-good'}">${failedProfiles ? `${failedProfiles} failed` : 'No failures'}</span></div>
      <div class="dashboard-operation-metrics"><span><strong>${profiles.length}</strong><small>Saved profiles</small></span><span><strong>${readyProfiles}</strong><small>Live sessions</small></span></div>
      ${attentionProfiles.length ? attentionProfiles.map((profile) => `<button class="dashboard-operation-row" type="button" data-dashboard-database-profile="${escapeHtml(profile.id)}"><span class="operation-status-dot is-danger"></span><span class="dashboard-operation-copy"><strong>${escapeHtml(profile.name || 'Database profile')}</strong><small>Connection failed - review credentials or network access</small></span><span class="operation-status is-danger">Failed</span></button>`).join('') : `<div class="dashboard-operation-empty is-good"><span class="operation-status-dot is-good"></span><span>All saved database profiles are clear.</span></div>`}
    `;
  }

  uptimeTarget?.querySelectorAll('[data-dashboard-uptime-incident]').forEach((button) => button.addEventListener('click', () => {
    state.uptime.selectedIncidentId = button.dataset.dashboardUptimeIncident;
    showView('uptime');
    setUptimeTab('incidents');
  }));
  backupTarget?.querySelectorAll('[data-dashboard-backup-run]').forEach((button) => button.addEventListener('click', () => {
    showView('backup');
    setBackupManagerTab('jobs');
  }));
  databaseTarget?.querySelectorAll('[data-dashboard-database-profile]').forEach((button) => button.addEventListener('click', () => {
    showView('database');
    state.databaseManager.editingProfileId = button.dataset.dashboardDatabaseProfile;
  }));
}

async function refreshDashboardOperations() {
  if (dashboardRefreshInFlight || !window.deployerx) return;
  dashboardRefreshInFlight = true;
  try {
    const read = (method, fallback, ...args) => typeof window.deployerx[method] === 'function'
      ? window.deployerx[method](...args).catch(() => fallback)
      : Promise.resolve(fallback);
    const [monitors, incidents, worker, jobs, runs, backupWorker, profiles, statuses] = await Promise.all([
      read('listUptimeMonitors', []), read('listUptimeIncidents', [], { limit: 50 }), read('getUptimeWorkerStatus', { active: false }),
      read('listBackupJobs', []), read('listBackupRuns', [], { limit: 100 }), read('getBackupWorkerStatus', null),
      read('listDatabaseProfiles', [], { limit: 100 }), read('listDatabaseConnectionStatuses', [])
    ]);
    state.uptime.monitors = Array.isArray(monitors) ? monitors : [];
    state.uptime.incidents = Array.isArray(incidents) ? incidents : [];
    state.uptime.worker = worker || { active: false };
    state.backupJobs = Array.isArray(jobs) ? jobs : [];
    state.backupRuns = Array.isArray(runs) ? runs : [];
    state.backupWorker = backupWorker;
    state.databaseManager.profiles = Array.isArray(profiles) ? profiles : [];
    state.databaseManager.connectionStates = new Map((Array.isArray(statuses) ? statuses : []).map((status) => [status.profileId, status.state]));
    dashboardOperationsLoaded = true;
    renderDashboardStats();
    renderDashboardOperations();
  } finally {
    dashboardRefreshInFlight = false;
  }
}

function startDashboardAutoRefresh() {
  clearInterval(dashboardRefreshTimer);
  dashboardRefreshTimer = setInterval(() => {
    if (state.currentView === 'dashboard') refreshDashboardOperations().catch(() => {});
  }, 15000);
  refreshDashboardOperations().catch(() => {});
}

function stopDashboardAutoRefresh() {
  clearInterval(dashboardRefreshTimer);
  dashboardRefreshTimer = null;
}

function renderDashboardStats(stats = dashboardStats()) {
  if (!els.dashboardStatsGrid) return;
  els.dashboardStatsGrid.innerHTML = '';
  const offline = Math.max(0, stats.total - stats.sshConnected);
  const activeIncidents = (state.uptime.incidents || []).filter((incident) => incident.state !== 'resolved').length;
  const activeBackups = (state.backupRuns || []).filter(isActiveBackupRun).length;
  const databaseProfiles = state.databaseManager.profiles || [];
  const liveDatabases = databaseProfiles.filter((profile) => state.databaseManager.connectionStates.get(profile.id) === 'ready').length;
  const statCards = [
    ['Fleet nodes', stats.total, 'Registered infrastructure', 'server', 'cyan'],
    ['SSH live', stats.sshConnected, 'Encrypted sessions active', 'play', 'green'],
    ['Nodes offline', offline, 'Awaiting secure link', 'unplug', offline ? 'red' : 'green'],
    ['Uptime alerts', activeIncidents, `${state.uptime.monitors.length} monitors configured`, 'rocket', activeIncidents ? 'red' : 'green'],
    ['Active backups', activeBackups, `${state.backupJobs.length} protected jobs`, 'save', activeBackups ? 'amber' : 'violet'],
    ['Databases', databaseProfiles.length, `${liveDatabases} connected profiles`, 'database', 'blue']
  ];
  for (const [label, value, note, iconName, tone] of statCards) {
    const statCard = document.createElement('article');
    statCard.className = `dashboard-stat-card ${tone}`;
    statCard.innerHTML = `
      <div class="dashboard-stat-heading">
        <span class="dashboard-stat-icon ${tone}">${icon(iconName)}</span>
        <span class="dashboard-stat-label">${escapeHtml(label)}</span>
      </div>
      <strong class="dashboard-stat-value">${escapeHtml(value)}</strong>
      <span class="dashboard-stat-note">${escapeHtml(note)}</span>
    `;
    els.dashboardStatsGrid.appendChild(statCard);
  }
}

function renderProjects() {
  els.projectList.innerHTML = '';
  els.projectGrid.innerHTML = '';
  if (els.dashboardStatsGrid) els.dashboardStatsGrid.innerHTML = '';
  if (els.dashboardHealthSummary) els.dashboardHealthSummary.innerHTML = '';
  if (els.dashboardGroupSummary) els.dashboardGroupSummary.innerHTML = '';
  if (els.dashboardServerSections) els.dashboardServerSections.innerHTML = '';
  if (els.dashboardSystemOverview) els.dashboardSystemOverview.innerHTML = '';
  if (els.dashboardConnectionReadiness) els.dashboardConnectionReadiness.innerHTML = '';
  if (els.dashboardRecentActivity) els.dashboardRecentActivity.innerHTML = '';
  renderDashboardOperations();
  const sidebarQuery = els.serverSearch?.value.trim().toLowerCase() || '';
  const sidebarProjects = state.projects.filter((project) => {
    if (!sidebarQuery) return true;
    return [project.name, project.group, serverTypeLabel(project.serverType), serverHost(project), project.ssh?.username, project.rdp?.username]
      .filter(Boolean)
      .join(' ')
      .toLowerCase()
      .includes(sidebarQuery);
  });
  const sidebarProjectIds = new Set(sidebarProjects.map((project) => project.id));
  syncServerFilterOptions();
  const serverFilters = serverFilterCriteria();
  const visibleServerProjects = sortServerProjects(filteredServerProjects(), serverFilters.sort);
  const visibleServerIds = new Set(visibleServerProjects.map((project) => project.id));
  const visibleGroupCount = new Set(visibleServerProjects.map((project) => serverGroupName(project))).size;
  const totalConnectedCount = state.projects.filter(serverPrimaryConnectionActive).length;
  const totalFavoriteCount = state.projects.filter((project) => project.pinned).length;
  const totalCommandCount = state.projects.reduce((total, project) => total + (project.commands?.length || 0), 0);
  const filterCount = activeServerFilterCount(serverFilters);
  const hasFilterCriteria = filterCount > Number(serverFilters.sort !== 'name');
  if (els.serversOverviewTotal) els.serversOverviewTotal.textContent = String(state.projects.length);
  if (els.serversOverviewGroups) els.serversOverviewGroups.textContent = String(visibleGroupCount);
  if (els.serversOverviewConnected) els.serversOverviewConnected.textContent = String(totalConnectedCount);
  if (els.serversOverviewFavorites) els.serversOverviewFavorites.textContent = String(totalFavoriteCount);
  if (els.serversOverviewCommands) els.serversOverviewCommands.textContent = String(totalCommandCount);
  if (els.serversFilterResults) {
    els.serversFilterResults.textContent = hasFilterCriteria
      ? `Showing ${visibleServerProjects.length} of ${state.projects.length} servers`
      : `Showing all ${state.projects.length} servers`;
  }
  if (els.serversFilterBadge) {
    els.serversFilterBadge.textContent = String(filterCount);
    els.serversFilterBadge.classList.toggle('hidden', !filterCount);
  }
  els.serversFilterButton?.classList.toggle('active', Boolean(filterCount));
  renderProjectGroupOptions();

  const renderServerCard = (project) => {
    const connectionState = projectConnectionState(project.id);
    const windowsServer = project.serverType === 'rdp';
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'project-card';
    card.innerHTML = `
      <div class="project-card-top">
        <span class="project-card-icon" aria-hidden="true">${serverTypeIcon(project.serverType)}</span>
        <div class="project-card-meta">
          <strong>${escapeHtml(project.name || 'Untitled Server')}</strong>
          <span>${escapeHtml(serverTypeLabel(project.serverType))} · ${escapeHtml(serverHost(project) || 'no host')}</span>
        </div>
        <span class="project-card-action">${icon('chevron-right')}</span>
      </div>
      <div class="project-card-status-row">
        ${windowsServer
          ? `<span class="status-pill ${connectionState.rdp ? 'connected' : 'disconnected'}">RDP ${connectionState.rdp ? 'online' : 'offline'}</span>`
          : `<span class="status-pill ${connectionState.ssh ? 'connected' : 'disconnected'}">SSH ${connectionState.ssh ? 'online' : 'offline'}</span>
             <span class="status-pill ${connectionState.ftp ? 'connected' : 'disconnected'}">FTP ${connectionState.ftp ? 'online' : 'offline'}</span>`}
      </div>
      <div class="project-card-footer">
        <span class="project-card-note">${windowsServer ? 'Windows Remote Desktop' : `${project.commands?.length || 0} saved command${project.commands?.length === 1 ? '' : 's'}`}</span>
        ${project.pinned ? `<span class="project-card-favorite">${icon('heart')} Favorite</span>` : ''}
      </div>
    `;
    card.addEventListener('click', () => openProject(project.id));
    return card;
  };

  const renderServerInventoryRow = (project) => {
    const connection = projectConnectionState(project.id);
    const isRdp = project.serverType === 'rdp';
    const connected = isRdp ? connection.rdp : connection.ssh || connection.ftp;
    const projectName = project.name || 'Untitled Server';
    const endpointUser = isRdp ? project.rdp?.username : project.ssh?.username;
    const services = isRdp
      ? [{ label: 'RDP', port: project.rdp?.port || 3389, active: connection.rdp }]
      : [
          { label: 'SSH', port: project.ssh?.port || 22, active: connection.ssh },
          { label: 'FTP', port: project.ftp?.port || project.ssh?.port || 22, active: connection.ftp }
        ];
    const pinLabel = project.pinned ? `Remove ${projectName} from favorites` : `Add ${projectName} to favorites`;
    const row = document.createElement('div');
    row.className = `server-inventory-row ${connected ? 'is-connected' : 'is-disconnected'}`;
    row.innerHTML = `
      <button class="server-inventory-open" type="button" aria-label="Open ${escapeHtml(projectName)}"></button>
      <span class="server-inventory-identity">
        <span class="server-inventory-os" aria-hidden="true">${serverTypeIcon(project.serverType)}</span>
        <span>
          <strong>${escapeHtml(projectName)}</strong>
          <small>${escapeHtml(serverTypeLabel(project.serverType))}</small>
        </span>
      </span>
      <span class="server-inventory-group"><span>${escapeHtml(serverGroupName(project))}</span></span>
      <span class="server-inventory-endpoint">
        <strong>${escapeHtml(serverHost(project) || 'No host')}</strong>
        <small>${escapeHtml(endpointUser || 'No username')}</small>
      </span>
      <span class="server-service-list">
        ${services.map((service) => `
          <span class="server-service-capsule ${service.active ? 'is-active' : ''}">
            <i></i><strong>${service.label}</strong><small>:${escapeHtml(service.port)}</small>
          </span>
        `).join('')}
      </span>
      <span class="server-inventory-commands"><strong>${project.commands?.length || 0}</strong><small>saved</small></span>
      <span class="server-inventory-state ${connected ? 'is-live' : ''}"><i></i>${connected ? 'Connected' : 'Offline'}</span>
      <button class="server-inventory-favorite ${project.pinned ? 'active' : ''}" type="button" aria-label="${escapeHtml(pinLabel)}" aria-pressed="${project.pinned ? 'true' : 'false'}" title="${escapeHtml(pinLabel)}">${icon('heart')}</button>
      <span class="server-inventory-arrow" aria-hidden="true">${icon('chevron-right')}</span>
    `;
    row.querySelector('.server-inventory-open').addEventListener('click', () => openProject(project.id));
    const favoriteButton = row.querySelector('.server-inventory-favorite');
    favoriteButton.addEventListener('click', async () => {
      const nextPinned = !project.pinned;
      try {
        const saved = await withButtonLoading(`project:pin:${project.id}`, favoriteButton, () => saveProject({
          ...project,
          pinned: nextPinned
        }));
        if (!saved) return;
        renderProjects();
        showToast(nextPinned ? 'Server added to favorites' : 'Server removed from favorites');
      } catch (error) {
        showAlert(error.message || 'Could not update this favorite.');
      }
    });
    return row;
  };

  const renderSidebarProjectItem = (project, { reorderable = false } = {}) => {
    const connectionState = projectConnectionState(project.id);
    const isRdp = project.serverType === 'rdp';
    const connectionActive = isRdp ? connectionState.rdp : connectionState.ssh;
    const connectionLabel = `${isRdp ? 'RDP' : 'SSH'} ${connectionActive ? 'connected' : 'disconnected'}`;
    const isActiveProject = (state.currentView === 'project' && state.activeProject?.id === project.id)
      || (state.currentView === 'server-monitoring' && state.serverMonitoring.selectedProjectId === String(project.id));
    const projectName = project.name || 'Untitled Server';
    const pinLabel = project.pinned ? `Remove ${projectName} from favorites` : `Add ${projectName} to favorites`;
    const item = document.createElement('div');
    item.className = `project-item ${reorderable ? 'is-reorderable' : ''} ${isActiveProject ? 'active' : ''}`;
    if (reorderable) {
      item.draggable = true;
      item.dataset.sidebarProject = String(project.id);
      item.dataset.sidebarProjectDrag = String(project.id);
      item.dataset.sidebarGroup = serverGroupName(project);
      item.title = 'Drag to reorder server';
    }
    item.innerHTML = `
      <button class="project-item-open" type="button" aria-label="Open ${escapeHtml(projectName)}"${isActiveProject ? ' aria-current="page"' : ''}>
        <span class="project-server-icon">
          ${serverTypeIcon(project.serverType)}
          <span class="project-server-indicator ${connectionActive ? 'connected' : 'disconnected'}" title="${connectionLabel}" aria-label="${connectionLabel}"></span>
        </span>
        <span class="project-text">
          <strong>${escapeHtml(projectName)}</strong>
          <span class="project-host">${escapeHtml(serverHost(project) || 'no host')}</span>
        </span>
      </button>
      <button class="project-pin-button ${project.pinned ? 'active' : ''}" type="button" aria-label="${escapeHtml(pinLabel)}" aria-pressed="${project.pinned ? 'true' : 'false'}" title="${escapeHtml(pinLabel)}">
        ${icon('heart')}
      </button>
    `;
    item.querySelector('.project-item-open').addEventListener('click', () => openSidebarProject(project.id));
    const pinButton = item.querySelector('.project-pin-button');
    pinButton.addEventListener('click', async () => {
      const nextPinned = !project.pinned;
      try {
        const saved = await withButtonLoading(`project:pin:${project.id}`, pinButton, () => saveProject({
          ...project,
          pinned: nextPinned
        }));
        if (!saved) return;
        renderProjects();
        showToast(nextPinned ? 'Server added to favorites' : 'Server removed from favorites');
      } catch (error) {
        showAlert(error.message || 'Could not update this favorite.');
      }
    });
    return item;
  };

  if (!state.projects.length) {
    const sidebarEmpty = document.createElement('div');
    sidebarEmpty.className = 'empty-project';
    sidebarEmpty.textContent = 'No servers yet';
    els.projectList.appendChild(sidebarEmpty);

    const empty = document.createElement('div');
    empty.className = 'project-card';
    empty.innerHTML = `
      <div class="project-card-top">
        <span class="project-icon">DX</span>
        <div class="project-card-meta">
          <strong>No servers yet</strong>
          <span>Add one to start.</span>
        </div>
      </div>
      <div class="project-card-note">Use Add server to save SSH details, groups, and deployment commands.</div>
    `;
    els.projectGrid.appendChild(empty);
    renderDashboardStats({ total: 0, sshConnected: 0, ftpConnected: 0, groups: 0, commands: 0 });
    if (els.dashboardHealthSummary) els.dashboardHealthSummary.innerHTML = '<div class="dashboard-empty-inline">Save a server to see connection coverage.</div>';
    if (els.dashboardGroupSummary) els.dashboardGroupSummary.innerHTML = '<div class="dashboard-empty-inline">Groups appear here once servers are assigned.</div>';
    if (els.dashboardSystemOverview) els.dashboardSystemOverview.innerHTML = '<div class="dashboard-empty-inline">Add a server to start monitoring your workspace.</div>';
    if (els.dashboardConnectionReadiness) els.dashboardConnectionReadiness.innerHTML = '<div class="dashboard-empty-inline">No connection data yet.</div>';
    if (els.dashboardRecentActivity) els.dashboardRecentActivity.innerHTML = '<div class="dashboard-empty-inline">No recent workspace activity.</div>';
    return;
  }

  for (const project of state.projects) {
    const connectionState = projectConnectionState(project.id);
    const windowsServer = project.serverType === 'rdp';
    const sshStatus = connectionState.ssh ? 'SSH connected' : 'SSH disconnected';
    const ftpStatus = connectionState.ftp ? 'FTP connected' : 'FTP disconnected';
    const rdpStatus = connectionState.rdp ? 'RDP connected' : 'RDP disconnected';
    const connectionDots = windowsServer ? `
      <span class="project-connection-dots" aria-label="${rdpStatus}.">
        <span class="project-status-dot ${connectionState.rdp ? 'connected' : 'disconnected'}" title="${rdpStatus}"></span>
      </span>
    ` : `
      <span class="project-connection-dots" aria-label="${sshStatus}. ${ftpStatus}.">
        <span class="project-status-dot ${connectionState.ssh ? 'connected' : 'disconnected'}" title="${sshStatus}"></span>
        <span class="project-status-dot ${connectionState.ftp ? 'connected' : 'disconnected'}" title="${ftpStatus}"></span>
      </span>
    `;
    const listItem = document.createElement('button');
    listItem.type = 'button';
    const isActiveProject = state.currentView === 'project' && state.activeProject?.id === project.id;
    listItem.className = `project-item ${isActiveProject ? 'active' : ''}`;
    if (isActiveProject) listItem.setAttribute('aria-current', 'page');
    listItem.innerHTML = `
      <span class="project-text">
        <strong>${escapeHtml(project.name || 'Untitled Server')}</strong>
        <span>${escapeHtml(serverTypeLabel(project.serverType))} · ${escapeHtml(serverHost(project) || 'no host')}</span>
      </span>
      ${connectionDots}
    `;
    listItem.addEventListener('click', () => openProject(project.id));
    els.projectList.appendChild(listItem);

    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'project-card';
    card.innerHTML = `
      <div class="project-card-top">
        <span class="project-icon">${escapeHtml(projectBadge(project))}</span>
        <div class="project-card-meta">
          <strong>${escapeHtml(project.name || 'Untitled Server')}</strong>
          <span>${escapeHtml(serverTypeLabel(project.serverType))} · ${escapeHtml(serverHost(project) || 'no host')}</span>
        </div>
        <span class="project-card-action">${icon('chevron-right')}</span>
      </div>
      <div class="project-card-note">${project.commands?.length || 0} saved commands</div>
    `;
    card.addEventListener('click', () => openProject(project.id));
    els.projectGrid.appendChild(card);
  }

  const groups = groupProjects();
  const stats = dashboardStats();

  els.projectList.innerHTML = '';
  els.projectGrid.innerHTML = '';

  renderDashboardStats(stats);

  if (els.dashboardHealthSummary) {
    const online = stats.sshConnected;
    const offline = Math.max(0, stats.total - online);
    const onlinePercent = stats.total ? Math.round((online / stats.total) * 100) : 0;
    els.dashboardHealthSummary.innerHTML = `
      <div class="dashboard-status-primary">
        <span>Available now</span>
        <strong>${online}<small>of ${stats.total} servers</small></strong>
        <i><b style="width:${onlinePercent}%"></b></i>
      </div>
      <div class="dashboard-status-legend">
        <div><span><i class="status-key online"></i>Online</span><strong>${online} (${onlinePercent}%)</strong></div>
        <div><span><i class="status-key offline"></i>Offline</span><strong>${offline} (${100 - onlinePercent}%)</strong></div>
        <div><span><i class="status-key ftp"></i>FTP active</span><strong>${stats.ftpConnected}</strong></div>
      </div>
    `;
  }

  if (els.dashboardSystemOverview) {
    const sshPercent = stats.total ? Math.round((stats.sshConnected / stats.total) * 100) : 0;
    const ftpPercent = stats.total ? Math.round((stats.ftpConnected / stats.total) * 100) : 0;
    const commandCoverage = stats.total ? Math.min(100, Math.round((state.projects.filter((project) => project.commands?.length).length / stats.total) * 100)) : 0;
    els.dashboardSystemOverview.innerHTML = `
      <div class="system-overview-metric"><span>SSH sessions</span><strong>${sshPercent}%</strong><i><b style="width:${sshPercent}%"></b></i></div>
      <div class="system-overview-metric blue"><span>FTP sessions</span><strong>${ftpPercent}%</strong><i><b style="width:${ftpPercent}%"></b></i></div>
      <div class="system-overview-metric green"><span>Command coverage</span><strong>${commandCoverage}%</strong><i><b style="width:${commandCoverage}%"></b></i></div>
      <div class="system-overview-footer"><span>${stats.commands} saved deployment command${stats.commands === 1 ? '' : 's'}</span><span>${stats.groups} server group${stats.groups === 1 ? '' : 's'}</span></div>
    `;
  }

  if (els.dashboardConnectionReadiness) {
    const readinessProjects = [...state.projects]
      .sort((first, second) => {
        const firstState = projectConnectionState(first.id);
        const secondState = projectConnectionState(second.id);
        return Number(secondState.ssh) + Number(secondState.ftp) - Number(firstState.ssh) - Number(firstState.ftp);
      })
      .slice(0, 5);
    els.dashboardConnectionReadiness.innerHTML = readinessProjects.map((project) => {
      const connection = projectConnectionState(project.id);
      const score = Number(connection.ssh) * 60 + Number(connection.ftp) * 40;
      return `
        <button class="readiness-row" type="button" data-dashboard-project="${escapeHtml(project.id)}">
          <span><strong>${escapeHtml(project.name || 'Untitled Server')}</strong><small>${connection.ssh ? 'SSH active' : 'SSH idle'}${connection.ftp ? ' / FTP active' : ''}</small></span>
          <span class="readiness-meter"><i style="width:${score}%"></i></span>
          <b>${score}%</b>
        </button>
      `;
    }).join('');
    els.dashboardConnectionReadiness.querySelectorAll('[data-dashboard-project]').forEach((button) => {
      button.addEventListener('click', () => openProject(button.dataset.dashboardProject));
    });
  }

  if (els.dashboardRecentActivity) {
    const activity = [];
    for (const project of state.projects) {
      const connection = projectConnectionState(project.id);
      if (connection.ssh) activity.push({ icon: 'play', label: `SSH connected to ${project.name || 'server'}`, meta: project.ssh?.host || '', tone: 'success' });
      if (connection.ftp) activity.push({ icon: 'folder-open', label: `FTP connected to ${project.name || 'server'}`, meta: project.ssh?.host || '', tone: 'info' });
    }
    for (const item of state.backupHistory.slice(-4).reverse()) {
      activity.push({ icon: 'save', label: item.label, meta: item.time, tone: 'backup' });
    }
    if (!activity.length) activity.push({ icon: 'server', label: `${stats.total} servers loaded`, meta: 'Workspace ready', tone: 'neutral' });
    els.dashboardRecentActivity.innerHTML = activity.slice(0, 6).map((item) => `
      <div class="dashboard-activity-row">
        <span class="activity-icon ${item.tone}">${icon(item.icon)}</span>
        <strong>${escapeHtml(item.label)}</strong>
        <small>${escapeHtml(item.meta)}</small>
      </div>
    `).join('');
  }

  let serverInventoryBody = null;
  if (visibleServerProjects.length) {
    const serverInventory = document.createElement('section');
    serverInventory.className = 'server-inventory';
    serverInventory.innerHTML = `
      <div class="server-inventory-header" aria-hidden="true">
        <span>Server</span>
        <span>Group</span>
        <span>Endpoint</span>
        <span>Services and ports</span>
        <span>Commands</span>
        <span>State</span>
        <span></span>
        <span></span>
      </div>
      <div class="server-inventory-body"></div>
    `;
    serverInventoryBody = serverInventory.querySelector('.server-inventory-body');
    els.projectGrid.appendChild(serverInventory);
  }

  const pinnedSidebarProjects = sidebarProjects
    .filter((project) => project.pinned)
    .sort((first, second) => (first.name || '').localeCompare(second.name || ''));
  if (pinnedSidebarProjects.length) {
    const pinnedGroup = document.createElement('section');
    pinnedGroup.className = 'sidebar-server-group sidebar-pinned-group';
    pinnedGroup.innerHTML = `
      <div class="sidebar-server-group-header">
        <strong>Favorites</strong>
      </div>
    `;
    for (const project of pinnedSidebarProjects) pinnedGroup.appendChild(renderSidebarProjectItem(project));
    els.projectList.appendChild(pinnedGroup);
  }

  for (const group of groups) {
    const summary = document.createElement('div');
    summary.className = 'dashboard-group-chip';
    summary.innerHTML = `
      <strong>${escapeHtml(group.name)}</strong>
      <span>${group.items.length} server${group.items.length === 1 ? '' : 's'}</span>
    `;
    if (els.dashboardGroupSummary) els.dashboardGroupSummary.appendChild(summary);

    const sidebarItems = group.items.filter((project) => sidebarProjectIds.has(project.id));
    const serverItems = sortServerProjects(
      group.items.filter((project) => visibleServerIds.has(project.id)),
      serverFilters.sort
    );
    const sidebarGroup = document.createElement('section');
    sidebarGroup.className = 'sidebar-server-group';
    sidebarGroup.dataset.sidebarGroup = group.name;
    sidebarGroup.innerHTML = `
      <div class="sidebar-server-group-header${sidebarQuery ? '' : ' is-reorderable'}"${sidebarQuery ? '' : ` draggable="true" data-sidebar-group-drag="${escapeHtml(group.name)}" title="Drag to reorder group"`}>
        <div class="sidebar-server-group-title">
          <strong>${escapeHtml(group.name)}</strong>
        </div>
      </div>
    `;

    const dashboardSection = document.createElement('section');
    dashboardSection.className = 'server-group-section';
    dashboardSection.innerHTML = `
      <div class="server-group-header">
        <div>
          <h2>${escapeHtml(group.name)}</h2>
          <p>${group.items.length} server${group.items.length === 1 ? '' : 's'} in this group</p>
        </div>
      </div>
      <div class="server-group-grid"></div>
    `;
    const dashboardGrid = dashboardSection.querySelector('.server-group-grid');

    for (const project of group.items) {
      if (sidebarProjectIds.has(project.id)) sidebarGroup.appendChild(renderSidebarProjectItem(project, { reorderable: !sidebarQuery }));

      dashboardGrid.appendChild(renderServerCard(project));
    }
    if (serverItems.length && serverInventoryBody) {
      const groupHeading = document.createElement('div');
      groupHeading.className = 'server-inventory-group-row';
      groupHeading.innerHTML = `
        <strong>${escapeHtml(group.name)}</strong>
        <span>${serverItems.length}${hasFilterCriteria && serverItems.length !== group.items.length ? ` of ${group.items.length}` : ''} server${serverItems.length === 1 ? '' : 's'}</span>
      `;
      serverInventoryBody.appendChild(groupHeading);
      for (const project of serverItems) serverInventoryBody.appendChild(renderServerInventoryRow(project));
    }

    if (sidebarItems.length) els.projectList.appendChild(sidebarGroup);
    if (els.dashboardServerSections) els.dashboardServerSections.appendChild(dashboardSection);
  }

  if (!visibleServerProjects.length) {
    const emptyFilters = document.createElement('div');
    emptyFilters.className = 'server-filter-empty';
    emptyFilters.innerHTML = `
      <span aria-hidden="true">${icon('filter')}</span>
      <strong>No servers match these filters</strong>
      <small>Adjust or reset the active filters to restore the inventory.</small>
    `;
    els.projectGrid.appendChild(emptyFilters);
  }

  if (sidebarQuery && !sidebarProjects.length) {
    const emptySearch = document.createElement('div');
    emptySearch.className = 'empty-project';
    emptySearch.textContent = 'No matching servers';
    els.projectList.appendChild(emptySearch);
  }
}

let sidebarDragState = null;

function clearSidebarDropIndicators() {
  els.projectList.querySelectorAll('.drop-before, .drop-after').forEach((item) => {
    item.classList.remove('drop-before', 'drop-after');
  });
}

function sidebarDropAfter(event, element) {
  const bounds = element.getBoundingClientRect();
  return event.clientY > bounds.top + bounds.height / 2;
}

function reorderSidebarGroup(sourceName, targetName, placeAfter) {
  const groups = groupProjects().map((group) => group.name);
  const sourceIndex = groups.findIndex((name) => name.toLocaleLowerCase() === sourceName.toLocaleLowerCase());
  if (sourceIndex < 0) return;
  const [source] = groups.splice(sourceIndex, 1);
  const targetIndex = groups.findIndex((name) => name.toLocaleLowerCase() === targetName.toLocaleLowerCase());
  if (targetIndex < 0) return;
  groups.splice(targetIndex + (placeAfter ? 1 : 0), 0, source);
  state.sidebarOrder.groups = groups;
  persistSidebarOrder();
}

function reorderSidebarProject(sourceId, targetId, groupName, placeAfter) {
  const group = groupProjects().find((item) => item.name.toLocaleLowerCase() === groupName.toLocaleLowerCase());
  if (!group) return;
  const projectIds = group.items.map((project) => String(project.id));
  const sourceIndex = projectIds.indexOf(String(sourceId));
  if (sourceIndex < 0) return;
  const [source] = projectIds.splice(sourceIndex, 1);
  const targetIndex = projectIds.indexOf(String(targetId));
  if (targetIndex < 0) return;
  projectIds.splice(targetIndex + (placeAfter ? 1 : 0), 0, source);

  reconcileSidebarOrder();
  const groupProjectIds = new Set(projectIds);
  let nextProjectIndex = 0;
  state.sidebarOrder.projects = state.sidebarOrder.projects.map((projectId) => (
    groupProjectIds.has(String(projectId)) ? projectIds[nextProjectIndex++] : projectId
  ));
  persistSidebarOrder();
}

function beginSidebarDrag(event) {
  if (!(event.target instanceof Element) || els.serverSearch.value.trim()) return;
  const groupHandle = event.target.closest('[data-sidebar-group-drag]');
  const projectHandle = event.target.closest('[data-sidebar-project-drag]');
  if (!groupHandle && !projectHandle) return;

  if (groupHandle) {
    sidebarDragState = { type: 'group', group: groupHandle.dataset.sidebarGroupDrag };
    groupHandle.closest('.sidebar-server-group')?.classList.add('is-dragging');
  } else {
    const projectItem = projectHandle.closest('.project-item');
    sidebarDragState = {
      type: 'project',
      projectId: projectHandle.dataset.sidebarProjectDrag,
      group: projectItem?.dataset.sidebarGroup || ''
    };
    projectItem?.classList.add('is-dragging');
  }

  event.dataTransfer.effectAllowed = 'move';
  event.dataTransfer.setData('text/plain', sidebarDragState.type);
}

function updateSidebarDragTarget(event) {
  if (!sidebarDragState || !(event.target instanceof Element)) return;
  const target = sidebarDragState.type === 'group'
    ? event.target.closest('.sidebar-server-group[data-sidebar-group]:not(.sidebar-pinned-group)')
    : event.target.closest('.project-item[data-sidebar-project]');
  if (!target) return;
  if (sidebarDragState.type === 'project' && target.dataset.sidebarGroup.toLocaleLowerCase() !== sidebarDragState.group.toLocaleLowerCase()) return;

  event.preventDefault();
  event.dataTransfer.dropEffect = 'move';
  clearSidebarDropIndicators();
  target.classList.add(sidebarDropAfter(event, target) ? 'drop-after' : 'drop-before');
}

function finishSidebarDrop(event) {
  if (!sidebarDragState || !(event.target instanceof Element)) return;
  const target = sidebarDragState.type === 'group'
    ? event.target.closest('.sidebar-server-group[data-sidebar-group]:not(.sidebar-pinned-group)')
    : event.target.closest('.project-item[data-sidebar-project]');
  if (!target) return;
  if (sidebarDragState.type === 'project' && target.dataset.sidebarGroup.toLocaleLowerCase() !== sidebarDragState.group.toLocaleLowerCase()) return;

  event.preventDefault();
  const placeAfter = sidebarDropAfter(event, target);
  if (sidebarDragState.type === 'group') {
    reorderSidebarGroup(sidebarDragState.group, target.dataset.sidebarGroup, placeAfter);
  } else {
    reorderSidebarProject(sidebarDragState.projectId, target.dataset.sidebarProject, sidebarDragState.group, placeAfter);
  }
  sidebarDragState = null;
  renderProjects();
}

function endSidebarDrag() {
  sidebarDragState = null;
  clearSidebarDropIndicators();
  els.projectList.querySelectorAll('.is-dragging').forEach((item) => item.classList.remove('is-dragging'));
}

function renderTemplatesLegacy() {
  els.templateList.innerHTML = '';
  const query = els.templateSearch.value.trim().toLowerCase();
  const visibleTemplates = state.templates.filter((template) => {
    const category = normalizeTemplateCategory(template.category);
    const categoryMatches = state.activeTemplateCategory === 'All' || category === state.activeTemplateCategory;
    const commands = Array.isArray(template.commands) ? template.commands.join('\n') : '';
    const variables = extractTemplateVariables(template.commands || []).join('\n');
    const searchMatches = !query || `${template.name || ''}\n${category}\n${commands}\n${variables}`.toLowerCase().includes(query);
    return categoryMatches && searchMatches;
  });

  if (!state.templates.length) {
    const empty = document.createElement('div');
    empty.className = 'template-empty';
    empty.innerHTML = '<strong>No templates</strong><span>Create reusable command lists.</span>';
    els.templateList.appendChild(empty);
    return;
  }

  if (!visibleTemplates.length) {
    const empty = document.createElement('div');
    empty.className = 'template-empty';
    empty.innerHTML = '<strong>No matching templates</strong><span>Try another category or search.</span>';
    els.templateList.appendChild(empty);
    return;
  }

  for (const template of visibleTemplates) {
    const variableCount = extractTemplateVariables(template.commands || []).length;
    const item = document.createElement('button');
    item.type = 'button';
    item.className = `template-item ${state.activeTemplateId === template.id ? 'active' : ''}`;
    item.innerHTML = `
      <span class="template-item-icon">${icon('templates')}</span>
      <strong>${escapeHtml(template.name || 'Untitled template')}</strong>
      <span>${template.commands?.length || 0} commands${variableCount ? ` · ${variableCount} variables` : ''}</span>
      <span class="template-item-action">${icon('chevron-right')}</span>
    `;
    setTemplateMetaLine(item, template, variableCount);
    item.addEventListener('click', () => selectTemplate(template.id));
    els.templateList.appendChild(item);
  }
}

function setTemplateMetaLineLegacy(item, template, variableCount) {
  const meta = item.querySelector('span:not(.template-item-icon):not(.template-item-action)');
  if (!meta) return;
  const category = normalizeTemplateCategory(template.category);
  const variableText = variableCount ? ` - ${variableCount} variables` : '';
  const scopeText = isBuiltInTemplate(template) ? 'Library - ' : '';
  meta.textContent = `${scopeText}${category} - ${template.commands?.length || 0} commands${variableText}`;
}

function renderTemplates() {
  els.templateList.innerHTML = '';
  const query = els.templateSearch.value.trim().toLowerCase();
  const visibleTemplates = state.templates.filter((template) => {
    const category = normalizeTemplateCategory(template.category);
    const categoryMatches = state.activeTemplateCategory === 'All' || category === state.activeTemplateCategory;
    const commands = Array.isArray(template.commands) ? template.commands.join('\n') : '';
    const variables = extractTemplateVariables(template.commands || []).join('\n');
    const searchMatches = !query || `${template.name || ''}\n${category}\n${commands}\n${variables}`.toLowerCase().includes(query);
    return categoryMatches && searchMatches;
  });

  if (!state.templates.length) {
    const empty = document.createElement('div');
    empty.className = 'template-empty';
    empty.innerHTML = '<strong>No templates</strong><span>Create reusable command lists.</span>';
    els.templateList.appendChild(empty);
    return;
  }

  if (!visibleTemplates.length) {
    const empty = document.createElement('div');
    empty.className = 'template-empty';
    empty.innerHTML = '<strong>No matching templates</strong><span>Try another category or search.</span>';
    els.templateList.appendChild(empty);
    return;
  }

  for (const template of visibleTemplates) {
    const variableCount = extractTemplateVariables(template.commands || []).length;
    const sourceLabel = isBuiltInTemplate(template) ? 'Default' : 'Own';
    const badgeClass = isBuiltInTemplate(template) ? 'template-badge' : 'template-badge own';
    const item = document.createElement('button');
    item.type = 'button';
    item.className = `template-item ${state.activeTemplateId === template.id ? 'active' : ''}`;
    item.innerHTML = `
      <span class="template-item-icon">${icon('templates')}</span>
      <strong>${escapeHtml(template.name || 'Untitled template')}</strong>
      <span class="template-item-meta">
        <span class="template-item-meta-text"></span>
        <span class="${badgeClass}">${sourceLabel}</span>
      </span>
      <span class="template-item-action">${icon('chevron-right')}</span>
    `;
    setTemplateMetaLine(item, template, variableCount);
    item.addEventListener('click', () => selectTemplate(template.id));
    els.templateList.appendChild(item);
  }
}

function setTemplateMetaLine(item, template, variableCount) {
  const meta = item.querySelector('.template-item-meta-text');
  if (!meta) return;
  const category = normalizeTemplateCategory(template.category);
  const variableText = variableCount ? ` - ${variableCount} variables` : '';
  meta.textContent = `${category} - ${template.commands?.length || 0} commands${variableText}`;
}

function selectTemplate(templateId) {
  const template = getTemplateById(templateId);
  if (!template) return;
  state.activeTemplateId = template.id;
  els.templateName.value = template.name || '';
  els.templateCategory.value = normalizeTemplateCategory(template.category);
  els.templateCommands.value = Array.isArray(template.commands) ? template.commands.join('\n') : '';
  renderTemplateVariableSummary(template.commands || []);
  renderTemplateEditorState(template);
  els.templateEditorEmptyState.classList.add('hidden');
  els.templatePageForm.classList.remove('hidden');
  renderTemplates();
}

function newTemplate() {
  state.activeTemplateId = '';
  els.templateName.value = '';
  els.templateCategory.value = '';
  els.templateCommands.value = '';
  renderTemplateVariableSummary([]);
  renderTemplateEditorState(null);
  els.templateEditorEmptyState.classList.add('hidden');
  els.templatePageForm.classList.remove('hidden');
  renderTemplates();
}

function closeTemplateEditor() {
  state.activeTemplateId = '';
  els.templateName.value = '';
  els.templateCategory.value = '';
  els.templateCommands.value = '';
  renderTemplateVariableSummary([]);
  renderTemplateEditorState(null);
  els.templatePageForm.classList.add('hidden');
  els.templateEditorEmptyState.classList.remove('hidden');
  renderTemplates();
}

function renderDetailsSummary(project) {
  if (project.serverType === 'rdp') {
    const windowsUser = project.rdp?.domain
      ? `${project.rdp.domain}\\${project.rdp?.username || '-'}`
      : project.rdp?.username || '-';
    const rows = [
      ['Server', `${serverGroupName(project)} - Windows`],
      ['Host', `${windowsUser}@${project.rdp?.host || '-'}:${project.rdp?.port || '3389'}`]
    ];
    els.detailsSummary.innerHTML = rows
      .map(
        ([label, value]) =>
          `<div><dt>${escapeHtml(label)}</dt><dd title="${escapeHtml(value)}">${escapeHtml(value)}</dd></div>`
      )
      .join('');
    return;
  }
  const rows = [
    ['Server', `${serverGroupName(project)} - ${project.serverType || '-'}`],
    ['Host', `${project.ssh?.username || '-'}@${project.ssh?.host || '-'}:${project.ssh?.port || '22'}`]
  ];

  els.detailsSummary.innerHTML = rows
    .map(
      ([label, value]) =>
        `<div><dt>${escapeHtml(label)}</dt><dd title="${escapeHtml(value)}">${escapeHtml(value)}</dd></div>`
    )
    .join('');
}

function syncActiveFtpSession() {
  const ftpSession = getFtpSession(state.activeProject?.id, Boolean(state.activeProject));
  if (!ftpSession) return;
  ftpSession.sessionId = state.ftpSessionId;
  ftpSession.connected = Boolean(state.ftpConnected);
  ftpSession.localCurrentPath = state.ftpLocalCurrentPath || '';
  ftpSession.localParentPath = state.ftpLocalParentPath || '';
  ftpSession.localLoaded = Boolean(state.ftpLocalLoaded);
  ftpSession.localEntries = Array.isArray(state.ftpLocalEntries) ? [...state.ftpLocalEntries] : [];
  ftpSession.localSelectedPath = state.ftpLocalSelectedPath || '';
  ftpSession.localBackStack = [...state.ftpLocalBackStack];
  ftpSession.localForwardStack = [...state.ftpLocalForwardStack];
  ftpSession.localFilter = state.ftpLocalFilter || '';
  ftpSession.currentPath = state.ftpCurrentPath || '.';
  ftpSession.parentPath = state.ftpParentPath || '.';
  ftpSession.entries = Array.isArray(state.ftpEntries) ? [...state.ftpEntries] : [];
  ftpSession.selectedPath = state.ftpSelectedPath || '';
  ftpSession.backStack = [...state.ftpBackStack];
  ftpSession.forwardStack = [...state.ftpForwardStack];
  ftpSession.remoteFilter = state.ftpRemoteFilter || '';
}

function applyFtpSessionToState(projectId) {
  const ftpSession = getFtpSession(projectId);
  state.ftpSessionId = ftpSession?.sessionId || null;
  state.ftpConnected = Boolean(ftpSession?.connected);
  state.ftpLocalCurrentPath = ftpSession?.localCurrentPath || '';
  state.ftpLocalParentPath = ftpSession?.localParentPath || '';
  state.ftpLocalLoaded = Boolean(ftpSession?.localLoaded);
  state.ftpLocalEntries = Array.isArray(ftpSession?.localEntries) ? [...ftpSession.localEntries] : [];
  state.ftpLocalSelectedPath = ftpSession?.localSelectedPath || '';
  state.ftpLocalBackStack = Array.isArray(ftpSession?.localBackStack) ? [...ftpSession.localBackStack] : [];
  state.ftpLocalForwardStack = Array.isArray(ftpSession?.localForwardStack) ? [...ftpSession.localForwardStack] : [];
  state.ftpLocalFilter = ftpSession?.localFilter || '';
  state.ftpCurrentPath = ftpSession?.currentPath || '.';
  state.ftpParentPath = ftpSession?.parentPath || '.';
  state.ftpEntries = Array.isArray(ftpSession?.entries) ? [...ftpSession.entries] : [];
  state.ftpSelectedPath = ftpSession?.selectedPath || '';
  state.ftpBackStack = Array.isArray(ftpSession?.backStack) ? [...ftpSession.backStack] : [];
  state.ftpForwardStack = Array.isArray(ftpSession?.forwardStack) ? [...ftpSession.forwardStack] : [];
  state.ftpRemoteFilter = ftpSession?.remoteFilter || '';
}

function updateFtpStatus(message, connected = state.ftpConnected) {
  state.ftpConnected = Boolean(connected);
  syncActiveFtpSession();
  els.ftpStatus.textContent = message;
  els.ftpWorkspace.classList.toggle('terminal-connected', state.ftpConnected);
  els.connectFtpButton.disabled = state.ftpConnected;
  els.disconnectFtpButton.disabled = !state.ftpSessionId;
  els.ftpPathInput.disabled = !state.ftpConnected;
  els.ftpBackButton.disabled = !state.ftpConnected || !state.ftpBackStack.length;
  els.ftpForwardButton.disabled = !state.ftpConnected || !state.ftpForwardStack.length;
  els.ftpRemoteFilter.disabled = !state.ftpConnected;
  if (!state.ftpConnected) resetFtpDropState();
  renderFtpActionState();
  renderProjects();
}

function updateLocalFtpStatus(message = 'Local files') {
  els.ftpLocalStatus.textContent = message;
  els.ftpLocalPathInput.disabled = !state.activeProject;
  els.ftpLocalPathPickerButton.disabled = !state.activeProject;
  els.ftpLocalBackButton.disabled = !state.ftpLocalBackStack.length;
  els.ftpLocalForwardButton.disabled = !state.ftpLocalForwardStack.length;
  renderFtpActionState();
}

function selectedFtpLocalEntry() {
  return state.ftpLocalEntries.find((entry) => entry.path === state.ftpLocalSelectedPath) || null;
}

function selectedFtpEntry() {
  return state.ftpEntries.find((entry) => entry.path === state.ftpSelectedPath) || null;
}

function renderFtpActionState() {
  hideFtpContextMenu();
}

function renderFtpRow(entry, pane, selected, onSelect, onOpen, onContextMenu) {
  const row = document.createElement('button');
  row.type = 'button';
  row.className = `ftp-row ${selected ? 'selected' : ''}`;
  row.draggable = true;
  row.dataset.entryPath = entry.path;
  row.dataset.entryType = entry.type;
  row.dataset.entryName = entry.name;
  row.innerHTML = `
    <span class="ftp-name">${icon(entry.type === 'directory' ? 'folder-open' : 'templates')}<strong>${escapeHtml(entry.name)}</strong></span>
    <span>${escapeHtml(formatFtpDate(entry.modifiedAt))}</span>
    <span>${entry.type === 'directory' ? '-' : escapeHtml(formatBytes(entry.size))}</span>
    <span>${escapeHtml(entry.mode || (entry.type === 'directory' ? 'folder' : 'file'))}</span>
  `;
  row.addEventListener('click', onSelect);
  row.addEventListener('contextmenu', (event) => {
    event.preventDefault();
    onSelect();
    if (onContextMenu) onContextMenu(event);
  });
  row.addEventListener('dblclick', () => {
    if (entry.type === 'directory') onOpen();
  });
  row.addEventListener('dragstart', (event) => {
    if (!event.dataTransfer) return;
    event.dataTransfer.effectAllowed = 'copy';
    if (pane === 'local') {
      event.dataTransfer.setData(FTP_LOCAL_DRAG_TYPE, JSON.stringify({ paths: [entry.path] }));
    } else {
      event.dataTransfer.setData(FTP_REMOTE_DRAG_TYPE, JSON.stringify({ entry }));
    }
    event.dataTransfer.setData('text/plain', entry.name);
    requestAnimationFrame(() => row.classList.add('is-dragging'));
  });
  row.addEventListener('dragend', () => {
    row.classList.remove('is-dragging');
    resetFtpDropState();
  });
  return row;
}

function renderLocalFtpBrowser() {
  els.ftpLocalPathInput.value = state.ftpLocalCurrentPath || '';
  els.ftpLocalFilter.value = state.ftpLocalFilter;
  els.ftpLocalFileList.innerHTML = '';

  if (!state.ftpLocalLoaded) {
    const empty = document.createElement('div');
    empty.className = 'ftp-empty';
    empty.textContent = 'Loading local files...';
    empty.addEventListener('contextmenu', (event) => showFtpContextMenu(event, 'local'));
    els.ftpLocalFileList.appendChild(empty);
    return;
  }

  const entries = filteredEntries(state.ftpLocalEntries, state.ftpLocalFilter);
  if (!entries.length) {
    const empty = document.createElement('div');
    empty.className = 'ftp-empty';
    empty.textContent = state.ftpLocalFilter ? 'No local matches.' : 'This local folder is empty.';
    empty.addEventListener('contextmenu', (event) => showFtpContextMenu(event, 'local'));
    els.ftpLocalFileList.appendChild(empty);
    return;
  }

  for (const entry of entries) {
    els.ftpLocalFileList.appendChild(
      renderFtpRow(
        entry,
        'local',
        entry.path === state.ftpLocalSelectedPath,
        () => {
          state.ftpLocalSelectedPath = entry.path;
          renderFtpBrowser();
        },
        () => openLocalFtpPath(entry.path, { pushHistory: true }).catch((error) => showAlert(error.message || 'Could not open local folder.')),
        (event) => showFtpContextMenu(event, 'local', entry)
      )
    );
  }
}

function renderRemoteFtpBrowser() {
  els.ftpPathInput.value = state.ftpCurrentPath || '.';
  els.ftpRemoteFilter.value = state.ftpRemoteFilter;
  els.ftpFileList.innerHTML = '';

  if (!state.ftpConnected) {
    const empty = document.createElement('div');
    empty.className = 'ftp-empty';
    empty.textContent = 'Connect FTP to browse this server.';
    empty.addEventListener('contextmenu', (event) => showFtpContextMenu(event, 'remote'));
    els.ftpFileList.appendChild(empty);
    return;
  }

  const entries = filteredEntries(state.ftpEntries, state.ftpRemoteFilter);
  if (!entries.length) {
    const empty = document.createElement('div');
    empty.className = 'ftp-empty';
    empty.textContent = state.ftpRemoteFilter ? 'No server matches.' : 'This server folder is empty. Drop files or folders here to upload.';
    empty.addEventListener('contextmenu', (event) => showFtpContextMenu(event, 'remote'));
    els.ftpFileList.appendChild(empty);
    return;
  }

  for (const entry of entries) {
    els.ftpFileList.appendChild(
      renderFtpRow(
        entry,
        'remote',
        entry.path === state.ftpSelectedPath,
        () => {
          state.ftpSelectedPath = entry.path;
          renderFtpBrowser();
        },
        () => openFtpPath(entry.path, { pushHistory: true }).catch((error) => showAlert(error.message || 'Could not open server folder.')),
        (event) => showFtpContextMenu(event, 'remote', entry)
      )
    );
  }
}

function renderFtpBrowser() {
  renderLocalFtpBrowser();
  renderRemoteFtpBrowser();
  updateLocalFtpStatus(fileNameFromPath(state.ftpLocalCurrentPath) || 'Local files');
  updateFtpStatus(state.ftpConnected ? 'Connected' : 'Not connected', state.ftpConnected);
  syncActiveFtpSession();
}

async function persistActiveProjectLocalSettings(localPath = state.ftpLocalCurrentPath) {
  if (!state.activeProject?.id) return;
  await window.deployerx.setProjectLocalSettings(state.activeProject.id, {
    ftpLocalPath: localPath || ''
  });
}

async function ensureActiveProjectLocalFtpReady(projectId = state.activeProject?.id) {
  const activeProjectId = String(projectId || '').trim();
  if (!activeProjectId) return;

  const ftpSession = getFtpSession(activeProjectId, true);
  if (ftpSession?.localLoaded && ftpSession.localCurrentPath) return;

  let targetPath = ftpSession?.localCurrentPath || '';
  if (!targetPath) {
    const localSettings = await window.deployerx.getProjectLocalSettings(activeProjectId);
    targetPath = String(localSettings?.ftpLocalPath || '').trim();
    if (state.activeProject?.id === activeProjectId && targetPath) {
      state.ftpLocalCurrentPath = targetPath;
      state.ftpLocalLoaded = false;
      renderFtpBrowser();
    }
  }

  if (state.activeProject?.id !== activeProjectId) return;

  try {
    await refreshLocalFtpList(targetPath || undefined, { persist: false, projectId: activeProjectId });
  } catch (error) {
    if (!targetPath) throw error;
    await window.deployerx.setProjectLocalSettings(activeProjectId, { ftpLocalPath: '' });
    await refreshLocalFtpList(undefined, { persist: false, projectId: activeProjectId });
    showAlert('Your saved local folder was not found, so the FTP pane opened your home folder instead.');
  }
}

async function refreshLocalFtpList(pathOverride = state.ftpLocalCurrentPath, options = {}) {
  const targetProjectId = String(options.projectId || state.activeProject?.id || '').trim();
  const previousPath = state.ftpLocalCurrentPath;
  const result = await withFileActivity('Loading local files...', () => window.deployerx.localList({ path: pathOverride || undefined }));
  if (targetProjectId && state.activeProject?.id !== targetProjectId) return;
  state.ftpLocalCurrentPath = result.path || pathOverride || '';
  state.ftpLocalParentPath = result.parentPath || '';
  state.ftpLocalLoaded = true;
  state.ftpLocalEntries = Array.isArray(result.items) ? result.items : [];
  state.ftpLocalSelectedPath = '';
  if (options.pushHistory && previousPath && previousPath !== state.ftpLocalCurrentPath) {
    state.ftpLocalBackStack.push(previousPath);
    state.ftpLocalForwardStack = [];
  }
  updateLocalFtpStatus(fileNameFromPath(state.ftpLocalCurrentPath) || 'Local files');
  renderFtpBrowser();
  if (options.persist !== false && state.ftpLocalCurrentPath) {
    persistActiveProjectLocalSettings(state.ftpLocalCurrentPath).catch(() => {});
  }
}

async function refreshFtpList(pathOverride = state.ftpCurrentPath, options = {}) {
  if (!state.ftpSessionId) return;
  const previousPath = state.ftpCurrentPath;
  updateFtpStatus('Loading...', true);
  try {
    const result = await withFileActivity('Loading server files...', () =>
      window.deployerx.ftpList({
        sessionId: state.ftpSessionId,
        path: pathOverride || '.'
      })
    );
    state.ftpCurrentPath = result.path || pathOverride || '.';
    state.ftpParentPath = result.parentPath || parentFtpPath(state.ftpCurrentPath);
    state.ftpEntries = Array.isArray(result.items) ? result.items : [];
    state.ftpSelectedPath = '';
    if (options.pushHistory && previousPath && previousPath !== state.ftpCurrentPath) {
      state.ftpBackStack.push(previousPath);
      state.ftpForwardStack = [];
    }
    updateFtpStatus('Connected', true);
    renderFtpBrowser();
  } catch (error) {
    updateFtpStatus(state.ftpConnected ? 'Connected' : 'Not connected', state.ftpConnected);
    throw error;
  }
}

async function connectFtp() {
  if (!state.activeProject || state.ftpSessionId || pendingActions.has('ftp:connect')) return;
  try {
    updateFtpStatus('Connecting...', false);
    const sessionId = `${Date.now()}`;
    const response = await withButtonLoading('ftp:connect', els.connectFtpButton, () =>
      window.deployerx.ftpConnect({
        sessionId,
        project: state.activeProject
      })
    );
    if (!response) return;
    state.ftpSessionId = response.sessionId || sessionId;
    state.ftpCurrentPath = response.path || '.';
    state.ftpEntries = [];
    state.ftpBackStack = [];
    state.ftpForwardStack = [];
    updateFtpStatus('Connected', true);
    if (!state.ftpLocalLoaded) await ensureActiveProjectLocalFtpReady();
    await refreshFtpList(state.ftpCurrentPath);
  } catch (error) {
  state.ftpSessionId = null;
  state.ftpConnected = false;
  state.ftpCurrentPath = '.';
  state.ftpParentPath = '.';
  state.ftpEntries = [];
  state.ftpSelectedPath = '';
  state.ftpBackStack = [];
  state.ftpForwardStack = [];
    updateFtpStatus('Connection failed', false);
    renderFtpBrowser();
    showAlert(error.message || 'Could not connect FTP.');
  }
}

async function disconnectFtp() {
  if (!state.ftpSessionId || pendingActions.has('ftp:disconnect')) return;
  await withButtonLoading('ftp:disconnect', els.disconnectFtpButton, () => window.deployerx.ftpDisconnect(state.ftpSessionId));
  state.ftpSessionId = null;
  state.ftpConnected = false;
  state.ftpCurrentPath = '.';
  state.ftpParentPath = '.';
  state.ftpEntries = [];
  state.ftpSelectedPath = '';
  state.ftpBackStack = [];
  state.ftpForwardStack = [];
  renderFtpBrowser();
}

async function openLocalFtpPath(localPath, options = {}) {
  await refreshLocalFtpList(localPath || els.ftpLocalPathInput.value, options);
}

async function chooseLocalFtpPath() {
  if (!state.activeProject) return;
  const localPath = await window.deployerx.selectLocalFolder(state.ftpLocalCurrentPath || '');
  if (!localPath) return;
  await openLocalFtpPath(localPath, { pushHistory: true });
}

async function openFtpPath(remotePath, options = {}) {
  if (!state.ftpConnected) return;
  await refreshFtpList(remotePath || els.ftpPathInput.value || '.', options);
}

async function goLocalFtpHistory(direction) {
  const fromPath = state.ftpLocalCurrentPath;
  const stackFrom = direction < 0 ? state.ftpLocalBackStack : state.ftpLocalForwardStack;
  const stackTo = direction < 0 ? state.ftpLocalForwardStack : state.ftpLocalBackStack;
  const nextPath = stackFrom.pop();
  if (!nextPath) return;
  if (fromPath) stackTo.push(fromPath);
  try {
    await refreshLocalFtpList(nextPath);
  } catch (error) {
    stackFrom.push(nextPath);
    if (fromPath) stackTo.pop();
    throw error;
  }
}

async function goFtpHistory(direction) {
  if (!state.ftpConnected) return;
  const fromPath = state.ftpCurrentPath;
  const stackFrom = direction < 0 ? state.ftpBackStack : state.ftpForwardStack;
  const stackTo = direction < 0 ? state.ftpForwardStack : state.ftpBackStack;
  const nextPath = stackFrom.pop();
  if (!nextPath) return;
  if (fromPath) stackTo.push(fromPath);
  try {
    await refreshFtpList(nextPath);
  } catch (error) {
    stackFrom.push(nextPath);
    if (fromPath) stackTo.pop();
    throw error;
  }
}

function hideFtpContextMenu() {
  if (!els.ftpContextMenu) return;
  els.ftpContextMenu.classList.add('hidden');
  els.ftpContextMenu.setAttribute('aria-hidden', 'true');
}

function promptFileName(title, currentName = '') {
  const value = window.prompt(title, currentName);
  if (value === null) return '';
  return value.trim();
}

async function openLocalFtpEntry(entry) {
  if (!entry) return;
  if (entry.type === 'directory') {
    await openLocalFtpPath(entry.path, { pushHistory: true });
    return;
  }
  await window.deployerx.localOpen({ entry });
}

async function openLocalFtpEntryWith(entry) {
  if (!entry || entry.type === 'directory') return;
  await window.deployerx.localOpenWith({ entry });
}

async function renameLocalFtpEntry(entry) {
  if (!entry) return;
  const name = promptFileName('Rename local item', entry.name);
  if (!name || name === entry.name) return;
  await window.deployerx.localRename({ entry, name });
  await refreshLocalFtpList();
  showToast('Local item renamed');
}

async function openRemoteFtpEntry(entry) {
  if (!entry || !state.ftpSessionId) return;
  if (entry.type === 'directory') {
    await openFtpPath(entry.path, { pushHistory: true });
    return;
  }
  await window.deployerx.ftpOpen({ sessionId: state.ftpSessionId, entry });
}

async function openRemoteFtpEntryWith(entry) {
  if (!entry || entry.type === 'directory' || !state.ftpSessionId) return;
  await window.deployerx.ftpOpenWith({ sessionId: state.ftpSessionId, entry });
}

async function renameRemoteFtpEntry(entry) {
  if (!entry || !state.ftpSessionId) return;
  const name = promptFileName('Rename server item', entry.name);
  if (!name || name === entry.name) return;
  await window.deployerx.ftpRename({ sessionId: state.ftpSessionId, entry, name });
  await refreshFtpList();
  showToast('Server item renamed');
}

async function createFtpFolderFromMenu(pane) {
  const name = promptFileName('New folder name');
  if (!name) return;
  if (pane === 'local') await makeLocalFtpFolder(name);
  else await makeFtpFolder(name);
}

function getFtpContextItems(pane, entry) {
  const isLocal = pane === 'local';
  const hasEntry = Boolean(entry);
  const canUseLocalDirectory = Boolean(state.ftpLocalCurrentPath);
  const canUseRemoteDirectory = Boolean(state.ftpConnected && state.ftpSessionId);

  return [
    {
      label: 'Open',
      disabled: !hasEntry || (!isLocal && !canUseRemoteDirectory),
      action: () => (isLocal ? openLocalFtpEntry(entry) : openRemoteFtpEntry(entry))
    },
    {
      label: 'Open with...',
      disabled: !hasEntry || entry.type === 'directory' || (!isLocal && !canUseRemoteDirectory),
      action: () => (isLocal ? openLocalFtpEntryWith(entry) : openRemoteFtpEntryWith(entry))
    },
    {
      label: isLocal ? 'Upload' : 'Download',
      disabled: !hasEntry || (isLocal ? !canUseRemoteDirectory : !canUseLocalDirectory),
      action: () => (isLocal ? uploadFtpFile(entry) : downloadFtpFile(entry))
    },
    {
      label: 'Copy to target directory',
      disabled: !hasEntry || (isLocal ? !canUseRemoteDirectory : !canUseLocalDirectory),
      action: () => (isLocal ? uploadFtpFile(entry) : downloadFtpFile(entry))
    },
    {
      label: 'Rename',
      disabled: !hasEntry || (!isLocal && !canUseRemoteDirectory),
      action: () => (isLocal ? renameLocalFtpEntry(entry) : renameRemoteFtpEntry(entry))
    },
    {
      label: 'Delete',
      disabled: !hasEntry || (!isLocal && !canUseRemoteDirectory),
      action: () => (isLocal ? deleteLocalFtpEntry(entry) : deleteFtpEntry(entry))
    },
    {
      label: 'Refresh',
      disabled: isLocal ? !canUseLocalDirectory : !canUseRemoteDirectory,
      action: () => (isLocal ? refreshLocalFtpList() : refreshFtpList())
    },
    {
      label: 'New folder',
      disabled: isLocal ? !canUseLocalDirectory : !canUseRemoteDirectory,
      action: () => createFtpFolderFromMenu(pane)
    }
  ];
}

function showFtpContextMenu(event, pane, entry = null) {
  showContextMenuItems(event, getFtpContextItems(pane, entry));
}

function showContextMenuItems(event, items) {
  event.preventDefault();
  event.stopPropagation();
  const menu = els.ftpContextMenu;
  if (!menu) return;
  hideFtpContextMenu();
  menu.innerHTML = '';

  for (const item of items) {
    const button = document.createElement('button');
    button.type = 'button';
    button.role = 'menuitem';
    button.textContent = item.label;
    button.disabled = Boolean(item.disabled);
    button.addEventListener('click', () => {
      hideFtpContextMenu();
      Promise.resolve(item.action()).catch((error) => showAlert(error.message || 'Could not complete this action.'));
    });
    menu.appendChild(button);
  }

  menu.classList.remove('hidden');
  menu.setAttribute('aria-hidden', 'false');
  const rect = menu.getBoundingClientRect();
  const left = Math.max(8, Math.min(event.clientX, window.innerWidth - rect.width - 8));
  const top = Math.max(8, Math.min(event.clientY, window.innerHeight - rect.height - 8));
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function recordFtpTransferUndo(action) {
  const ftpSession = getFtpSession(state.activeProject?.id, true);
  if (!ftpSession) return;
  ftpSession.undoStack.push(action);
  if (ftpSession.undoStack.length > 20) ftpSession.undoStack.shift();
}

async function undoLastFtpTransfer() {
  const ftpSession = getFtpSession();
  const action = ftpSession?.undoStack?.pop();
  if (!action) {
    showToast('Nothing to undo');
    return;
  }

  try {
    if (action.kind === 'upload') {
      if (!state.ftpSessionId || state.ftpSessionId !== action.sessionId) {
        throw new Error('Reconnect to the same FTP session before undoing this upload.');
      }
      await withFileActivity('Undoing upload...', async () => {
        for (const entry of [...action.entries].reverse()) {
          await window.deployerx.ftpDelete({ sessionId: state.ftpSessionId, entry });
        }
      });
      await refreshFtpList();
      showToast(action.entries.length === 1 ? 'Upload undone' : `${action.entries.length} uploads undone`);
      return;
    }

    if (action.kind === 'download') {
      await withFileActivity('Undoing download...', async () => {
        for (const entry of [...action.entries].reverse()) {
          await window.deployerx.localDelete({ entry });
        }
      });
      await refreshLocalFtpList();
      showToast(action.entries.length === 1 ? 'Download undone' : `${action.entries.length} downloads undone`);
    }
  } catch (error) {
    ftpSession.undoStack.push(action);
    showAlert(error.message || 'Could not undo the file transfer.');
  }
}

async function uploadFtpFile(entryOverride = null) {
  const entry = entryOverride || selectedFtpLocalEntry();
  if (!entry) return;
  await uploadFtpPaths([entry.path]);
}

async function uploadFtpPaths(localPaths = [], remoteDirectoryOverride = '') {
  const paths = [...new Set(localPaths.map((localPath) => String(localPath || '').trim()).filter(Boolean))];
  if (!state.ftpSessionId || !paths.length || pendingActions.has('ftp:upload')) return;

  const label = paths.length === 1 ? fileNameFromPath(paths[0]) : `${paths.length} items`;
  const remoteDirectory = remoteDirectoryOverride || state.ftpCurrentPath;
  const canUndo = remoteDirectory === state.ftpCurrentPath;
  const existingRemoteNames = new Set(state.ftpEntries.map((entry) => entry.name));
  const localEntriesByPath = new Map(state.ftpLocalEntries.map((entry) => [entry.path, entry]));
  const uploadedEntries = [];
  try {
    await withFileActivity(`Uploading ${label}...`, () =>
      withButtonLoading('ftp:upload', null, async () => {
        for (const localPath of paths) {
          const result = await window.deployerx.ftpUpload({
            sessionId: state.ftpSessionId,
            localPath,
            remoteDirectory
          });
          const localEntry = localEntriesByPath.get(localPath);
          if (canUndo && localEntry && !existingRemoteNames.has(localEntry.name) && result?.remotePath) {
            uploadedEntries.push({ path: result.remotePath, type: localEntry.type });
          }
        }
      })
    );
    await refreshFtpList();
    if (uploadedEntries.length === paths.length) {
      recordFtpTransferUndo({ kind: 'upload', sessionId: state.ftpSessionId, entries: uploadedEntries });
    }
    showToast(paths.length === 1 ? `Uploaded ${label}` : `Uploaded ${paths.length} items`);
  } catch (error) {
    showAlert(error.message || 'Could not upload item.');
  }
}

function canDropOnFtpRemote(dataTransfer) {
  const hasLocalItems = hasFtpDragType(dataTransfer, FTP_LOCAL_DRAG_TYPE) || hasDraggedFiles(dataTransfer);
  return Boolean(hasLocalItems && state.ftpConnected && state.ftpSessionId && !pendingActions.has('ftp:upload'));
}

function canDropOnFtpLocal(dataTransfer) {
  return Boolean(
    hasFtpDragType(dataTransfer, FTP_REMOTE_DRAG_TYPE) &&
      state.ftpConnected &&
      state.ftpSessionId &&
      state.ftpLocalCurrentPath &&
      !pendingActions.has('ftp:download')
  );
}

function handleFtpRemoteDragEnter(event) {
  if (!hasFtpDragType(event.dataTransfer, FTP_LOCAL_DRAG_TYPE) && !hasDraggedFiles(event.dataTransfer)) return;
  event.preventDefault();
  event.stopPropagation();
  ftpRemoteDragDepth = 1;
  const droppable = canDropOnFtpRemote(event.dataTransfer);
  setFtpDropActive('remote', droppable, droppable ? ftpDropDirectoryFromEvent(event, 'remote') : null);
}

function handleFtpRemoteDragOver(event) {
  if (!hasFtpDragType(event.dataTransfer, FTP_LOCAL_DRAG_TYPE) && !hasDraggedFiles(event.dataTransfer)) return;
  event.preventDefault();
  event.stopPropagation();
  const droppable = canDropOnFtpRemote(event.dataTransfer);
  if (event.dataTransfer) event.dataTransfer.dropEffect = droppable ? 'copy' : 'none';
  setFtpDropActive('remote', droppable, droppable ? ftpDropDirectoryFromEvent(event, 'remote') : null);
}

function handleFtpRemoteDragLeave(event) {
  if (!hasFtpDragType(event.dataTransfer, FTP_LOCAL_DRAG_TYPE) && !hasDraggedFiles(event.dataTransfer)) return;
  event.preventDefault();
  event.stopPropagation();
  if (event.relatedTarget && els.ftpRemoteBrowser?.contains(event.relatedTarget)) return;
  ftpRemoteDragDepth = 0;
  setFtpDropActive('remote', false);
}

async function handleFtpRemoteDrop(event) {
  const hasLocalDrag = hasFtpDragType(event.dataTransfer, FTP_LOCAL_DRAG_TYPE);
  if (!hasLocalDrag && !hasDraggedFiles(event.dataTransfer)) return;
  event.preventDefault();
  event.stopPropagation();
  const destination = ftpDropDirectoryFromEvent(event, 'remote');
  resetFtpDropState();

  if (!state.ftpConnected || !state.ftpSessionId) {
    showAlert('Connect FTP before dropping files to upload.');
    return;
  }

  const dragData = hasLocalDrag ? readFtpDragData(event.dataTransfer, FTP_LOCAL_DRAG_TYPE) : null;
  const localPaths = Array.isArray(dragData?.paths) ? dragData.paths : await droppedFtpLocalPaths(event);
  if (!localPaths.length) {
    showAlert('Could not read the dropped files. Try dropping local files or folders directly from Explorer.');
    return;
  }

  await uploadFtpPaths(localPaths, destination?.path || state.ftpCurrentPath);
}

async function downloadFtpFile(entryOverride = null) {
  const entry = entryOverride || selectedFtpEntry();
  if (!entry) return;
  await downloadFtpEntries([entry]);
}

async function downloadFtpEntries(entries = [], localDirectoryOverride = '') {
  const remoteEntries = entries.filter((entry) => entry?.path && entry?.name);
  if (!state.ftpSessionId || !remoteEntries.length || pendingActions.has('ftp:download')) return;
  const localDirectory = localDirectoryOverride || state.ftpLocalCurrentPath;
  const label = remoteEntries.length === 1 ? remoteEntries[0].name : `${remoteEntries.length} items`;
  const canUndo = localDirectory === state.ftpLocalCurrentPath;
  const existingLocalNames = new Set(state.ftpLocalEntries.map((entry) => entry.name));
  const downloadedEntries = [];
  try {
    await withFileActivity(`Downloading ${label}...`, () =>
      withButtonLoading('ftp:download', null, async () => {
        for (const entry of remoteEntries) {
          const result = await window.deployerx.ftpDownloadToDirectory({
            sessionId: state.ftpSessionId,
            entry,
            localDirectory
          });
          if (canUndo && !existingLocalNames.has(entry.name) && result?.localPath) {
            downloadedEntries.push({ path: result.localPath, type: entry.type });
          }
        }
      })
    );
    await refreshLocalFtpList();
    if (downloadedEntries.length === remoteEntries.length) {
      recordFtpTransferUndo({ kind: 'download', entries: downloadedEntries });
    }
    showToast(remoteEntries.length === 1 ? `Downloaded ${label}` : `Downloaded ${remoteEntries.length} items`);
  } catch (error) {
    showAlert(error.message || 'Could not download item.');
  }
}

function handleFtpLocalDragEnter(event) {
  if (!hasFtpDragType(event.dataTransfer, FTP_REMOTE_DRAG_TYPE)) return;
  event.preventDefault();
  event.stopPropagation();
  ftpLocalDragDepth = 1;
  const droppable = canDropOnFtpLocal(event.dataTransfer);
  setFtpDropActive('local', droppable, droppable ? ftpDropDirectoryFromEvent(event, 'local') : null);
}

function handleFtpLocalDragOver(event) {
  if (!hasFtpDragType(event.dataTransfer, FTP_REMOTE_DRAG_TYPE)) return;
  event.preventDefault();
  event.stopPropagation();
  const droppable = canDropOnFtpLocal(event.dataTransfer);
  if (event.dataTransfer) event.dataTransfer.dropEffect = droppable ? 'copy' : 'none';
  setFtpDropActive('local', droppable, droppable ? ftpDropDirectoryFromEvent(event, 'local') : null);
}

function handleFtpLocalDragLeave(event) {
  if (!hasFtpDragType(event.dataTransfer, FTP_REMOTE_DRAG_TYPE)) return;
  event.preventDefault();
  event.stopPropagation();
  if (event.relatedTarget && els.ftpLocalBrowser?.contains(event.relatedTarget)) return;
  ftpLocalDragDepth = 0;
  setFtpDropActive('local', false);
}

async function handleFtpLocalDrop(event) {
  if (!hasFtpDragType(event.dataTransfer, FTP_REMOTE_DRAG_TYPE)) return;
  event.preventDefault();
  event.stopPropagation();
  const destination = ftpDropDirectoryFromEvent(event, 'local');
  const dragData = readFtpDragData(event.dataTransfer, FTP_REMOTE_DRAG_TYPE);
  resetFtpDropState();

  if (!state.ftpConnected || !state.ftpSessionId) {
    showAlert('Connect FTP before dropping server items to download.');
    return;
  }
  if (!state.ftpLocalCurrentPath) {
    showAlert('Choose a local folder before downloading server items.');
    return;
  }
  if (!dragData?.entry?.path) {
    showAlert('Could not read the dropped server item.');
    return;
  }

  await downloadFtpEntries([dragData.entry], destination?.path || state.ftpLocalCurrentPath);
}

async function makeLocalFtpFolder(nameOverride = '') {
  if (!state.ftpLocalCurrentPath || pendingActions.has('local:mkdir')) return;
  const name = String(nameOverride || '').trim();
  if (!name) return;
  try {
    await withButtonLoading('local:mkdir', null, () =>
      window.deployerx.localMkdir({
        directory: state.ftpLocalCurrentPath,
        name
      })
    );
    await refreshLocalFtpList();
    showToast('Local folder created');
  } catch (error) {
    showAlert(error.message || 'Could not create local folder.');
  }
}

async function makeFtpFolder(nameOverride = '') {
  if (!state.ftpSessionId || pendingActions.has('ftp:mkdir')) return;
  const name = String(nameOverride || '').trim();
  if (!name) return;
  try {
    await withButtonLoading('ftp:mkdir', null, () =>
      window.deployerx.ftpMkdir({
        sessionId: state.ftpSessionId,
        remoteDirectory: state.ftpCurrentPath,
        name
      })
    );
    await refreshFtpList();
    showToast('Server folder created');
  } catch (error) {
    showAlert(error.message || 'Could not create server folder.');
  }
}

async function deleteLocalFtpEntry(entryOverride = null) {
  const entry = entryOverride || selectedFtpLocalEntry();
  if (!entry || pendingActions.has('local:delete')) return;
  const ok = await confirmDangerousAction(
    `Delete local "${entry.name}"?`,
    entry.type === 'directory' ? 'This deletes the local folder and its contents.' : 'This deletes the local file.',
    'Delete'
  );
  if (!ok) return;
  try {
    await withButtonLoading('local:delete', null, () => window.deployerx.localDelete({ entry }));
    await refreshLocalFtpList();
    showToast('Local item deleted');
  } catch (error) {
    showAlert(error.message || 'Could not delete local item.');
  }
}

async function deleteFtpEntry(entryOverride = null) {
  const entry = entryOverride || selectedFtpEntry();
  if (!state.ftpSessionId || !entry || pendingActions.has('ftp:delete')) return;
  const ok = await confirmDangerousAction(
    `Delete server "${entry.name}"?`,
    entry.type === 'directory' ? 'This deletes the server folder and its contents.' : 'This action cannot be undone.',
    'Delete'
  );
  if (!ok) return;
  try {
    await withButtonLoading('ftp:delete', null, () =>
      window.deployerx.ftpDelete({
        sessionId: state.ftpSessionId,
        entry
      })
    );
    await refreshFtpList();
    showToast('Server item deleted');
  } catch (error) {
    showAlert(error.message || 'Could not delete server item.');
  }
}

function populateProjectView(project) {
  const normalizedProject = normalizeProject(project);
  const projectChanged = Boolean(state.activeProject?.id && state.activeProject.id !== normalizedProject.id);
  if (projectChanged && state.sshEditor.dirty) saveSshEditorFile().catch(() => {});
  if (projectChanged) {
    clearTimeout(sshEditorAutosaveTimer);
    state.sshEditor = { sessionId: '', path: '', dirty: false, saving: false };
    setSshEditorValue('');
    setSshRailView('directory');
  }
  state.activeProject = structuredClone(normalizedProject);
  const windowsServer = isRdpProject(normalizedProject);
  els.projectView.classList.toggle('windows-project', windowsServer);
  els.projectSshTab.parentElement.classList.toggle('hidden', windowsServer);
  els.rdpWorkspace.classList.toggle('hidden', !windowsServer);
  els.sshWorkspace.classList.toggle('hidden', windowsServer);
  els.ftpWorkspace.classList.add('hidden');
  els.terminalProjectLabel.textContent = windowsServer ? 'RDP' : 'SSH';
  const disconnectTitle = windowsServer ? 'Disconnect RDP' : 'Disconnect SSH';
  els.disconnectTerminalButton.setAttribute('aria-label', disconnectTitle);
  els.disconnectTerminalButton.dataset.tooltip = disconnectTitle;
  els.rdpToolbarLabel.textContent = windowsServer
    ? `${normalizedProject.rdp?.host || 'Windows'}:${normalizedProject.rdp?.port || 3389}`
    : 'Windows Remote Desktop';
  els.activeProjectName.textContent = normalizedProject.name || 'Untitled Server';
  renderDetailsSummary(normalizedProject);

  if (windowsServer) {
    prepareRdpClient().catch(() => {});
    const currentSession = state.rdpSessionId && state.rdpProjectId === normalizedProject.id;
    const message = currentSession
      ? (state.rdpStatus === 'connected' ? 'Connected' : 'Connecting...')
      : 'Not connected';
    setRdpStatus(currentSession ? state.rdpStatus : 'disconnected', message);
    if (!currentSession) els.disconnectTerminalButton.disabled = true;
    showView('project');
    renderProjects();
    setProjectTab('rdp');
    requestAnimationFrame(() => {
      syncRdpSize();
      if (currentSession && state.rdpStatus === 'connected') els.rdpCanvas.focus();
      else els.connectRdpButton.focus();
    });
    return;
  }

  const terminalSession = getTerminalSession(normalizedProject.id, true);
  getFtpSession(normalizedProject.id, true);
  applyTerminalSessionToState(normalizedProject.id);
  applyFtpSessionToState(normalizedProject.id);
  renderVisibleTerminalSession(terminalSession);
  updateTerminalStatus(terminalSession.status || (terminalSession.connected ? 'Connected' : 'Not connected'), terminalSession.connected);
  updateFtpStatus(state.ftpConnected ? 'Connected' : 'Not connected', state.ftpConnected);
  els.projectTemplateSelect.value = '';
  renderProjectTemplateDropdown();
  els.commands.value = Array.isArray(normalizedProject.commands) ? normalizedProject.commands.join('\n') : '';
  showView('project');
  renderProjects();
  setProjectTab(state.activeProjectTab);
  if (terminalSession.connected && terminalSession.sessionId) {
    if (!terminalSession.homeDirectory) ensureTerminalHomeDirectory(terminalSession.sessionId).catch(() => {});
    else refreshSshDirectory(terminalSession).catch(() => {});
  }
  if (state.activeProjectTab === 'ftp' && !state.ftpLocalLoaded) {
    ensureActiveProjectLocalFtpReady(normalizedProject.id).catch((error) => showAlert(error.message || 'Could not load local files.'));
  }
  requestAnimationFrame(() => {
    fitTerminal();
    if (!state.activeTerminalSessionId) els.connectTerminalButton.focus();
  });
}

async function refreshProjectsAndTemplates() {
  const data = await window.deployerx.listProjects();
  if (data.cloudError) {
    showToast('Cloud data is temporarily unavailable. Retrying shortly...');
    scheduleCloudProjectsRetry();
    return;
  }

  clearCloudProjectsRetry();
  const activeProjectId = state.activeProject?.id || '';
  state.projects = (data.projects || []).map(normalizeProject);
  state.serverGroups = readStoredServerGroups();
  rememberServerGroups(...state.projects.map((project) => project.group));
  state.sidebarOrder = readStoredSidebarOrder();
  reconcileSidebarOrder();
  state.templates = (data.templates || []).map(normalizeTemplate);
  if (activeProjectId) {
    state.activeProject = state.projects.find((project) => project.id === activeProjectId) || null;
  }
  syncSelectedUptimeProject(state.uptime.selectedProjectId || activeProjectId);
  renderTemplateCategories();
  renderTemplates();
  renderTemplateSelect();
  renderUptimeProjectSelect();
  renderProjects();
  renderServerGroupsSettings();
}

let projectLoadPromise = null;
let cloudProjectsRetryTimer = null;
let cloudProjectsRetryCount = 0;

function clearCloudProjectsRetry() {
  if (cloudProjectsRetryTimer) clearTimeout(cloudProjectsRetryTimer);
  cloudProjectsRetryTimer = null;
  cloudProjectsRetryCount = 0;
}

function scheduleCloudProjectsRetry() {
  if (cloudProjectsRetryTimer || cloudProjectsRetryCount >= 3) return;
  cloudProjectsRetryCount += 1;
  cloudProjectsRetryTimer = setTimeout(() => {
    cloudProjectsRetryTimer = null;
    refreshProjectsAndTemplates().catch(() => {});
  }, 2500);
}

async function loadProjects() {
  if (projectLoadPromise) return projectLoadPromise;
  projectLoadPromise = (async () => {
    try {
      await refreshProjectsAndTemplates();
      state.activeProject = null;
      renderProjects();
      showView('dashboard');
    } finally {
      projectLoadPromise = null;
    }
  })();
  return projectLoadPromise;
}

async function saveProject(project) {
  const saved = normalizeProject(await window.deployerx.saveProject(normalizeProject(project)));
  const index = state.projects.findIndex((item) => item.id === saved.id);
  if (index >= 0) state.projects[index] = saved;
  else state.projects.unshift(saved);
  if (state.activeProject?.id === saved.id) state.activeProject = structuredClone(saved);
  if (saved.group) rememberServerGroups(saved.group);
  return saved;
}

function exportPickerItems(type = state.exportPicker.type) {
  if (type === 'projects') {
    return state.projects.map((project) => ({
      id: String(project.id),
      title: project.name || 'Untitled Server',
      meta: `${serverGroupName(project)} - ${serverTypeLabel(project.serverType)} - ${serverHost(project) || 'no host'}`
    }));
  }

  return state.templates.filter((template) => !isBuiltInTemplate(template)).map((template) => {
    const variableCount = extractTemplateVariables(template.commands || []).length;
    return {
      id: String(template.id),
      title: template.name || 'Untitled template',
      meta: `${template.commands?.length || 0} commands${variableCount ? ` - ${variableCount} variables` : ''}`
    };
  });
}

function filteredExportPickerItems() {
  const query = els.exportPickerSearch.value.trim().toLowerCase();
  const items = exportPickerItems();
  if (!query) return items;
  return items.filter((item) => `${item.title} ${item.meta}`.toLowerCase().includes(query));
}

function updateExportPickerSelectionState(visibleItems = filteredExportPickerItems()) {
  const selectedCount = state.exportPicker.selectedIds.size;
  const visibleSelectedCount = visibleItems.filter((item) => state.exportPicker.selectedIds.has(item.id)).length;
  els.exportPickerCount.textContent = `${selectedCount} selected`;
  els.exportPickerSelectAll.checked = visibleItems.length > 0 && visibleSelectedCount === visibleItems.length;
  els.exportPickerSelectAll.indeterminate = visibleSelectedCount > 0 && visibleSelectedCount < visibleItems.length;
  els.exportPickerExportButton.disabled = selectedCount === 0;
}

function renderExportPicker() {
  const visibleItems = filteredExportPickerItems();
  els.exportPickerList.innerHTML = '';

  if (!visibleItems.length) {
    const empty = document.createElement('div');
    empty.className = 'export-picker-empty';
    empty.textContent = 'No matches found.';
    els.exportPickerList.appendChild(empty);
    updateExportPickerSelectionState(visibleItems);
    return;
  }

  for (const item of visibleItems) {
    const row = document.createElement('label');
    row.className = 'export-picker-row';
    row.innerHTML = `
      <input class="export-check" type="checkbox" data-export-id="${escapeHtml(item.id)}" ${state.exportPicker.selectedIds.has(item.id) ? 'checked' : ''} />
      <span class="export-picker-copy">
        <strong>${escapeHtml(item.title)}</strong>
        <span>${escapeHtml(item.meta)}</span>
      </span>
    `;

    row.querySelector('input').addEventListener('change', (event) => {
      if (event.target.checked) state.exportPicker.selectedIds.add(item.id);
      else state.exportPicker.selectedIds.delete(item.id);
      updateExportPickerSelectionState(visibleItems);
    });

    els.exportPickerList.appendChild(row);
  }

  updateExportPickerSelectionState(visibleItems);
}

function openExportPicker(type) {
  const items = exportPickerItems(type);
  if (!items.length) {
    showToast(type === 'projects' ? 'No servers to export' : 'No templates to export');
    return;
  }

  state.exportPicker = {
    type,
    selectedIds: new Set(items.map((item) => item.id))
  };
  els.exportPickerTitle.textContent = type === 'projects' ? 'Export servers' : 'Export templates';
  els.exportPickerSubtitle.textContent =
    type === 'projects' ? 'Choose the servers to include in this JSON export.' : 'Choose the templates to include in this JSON export.';
  els.exportPickerSearch.placeholder = type === 'projects' ? 'Search servers' : 'Search templates';
  els.exportPickerSearch.value = '';
  setModalVisible(true, els.exportPickerModal);
  renderExportPicker();
  els.exportPickerSearch.focus();
}

function closeExportPicker() {
  setModalVisible(false, els.exportPickerModal);
  state.exportPicker = {
    type: '',
    selectedIds: new Set()
  };
  els.exportPickerSearch.value = '';
  els.exportPickerList.innerHTML = '';
}

function toggleExportPickerSelectAll() {
  const visibleItems = filteredExportPickerItems();
  for (const item of visibleItems) {
    if (els.exportPickerSelectAll.checked) state.exportPicker.selectedIds.add(item.id);
    else state.exportPicker.selectedIds.delete(item.id);
  }
  renderExportPicker();
}

async function confirmExportPicker(event) {
  event.preventDefault();
  const selectedIds = [...state.exportPicker.selectedIds];
  if (!selectedIds.length) return;

  try {
    const result =
      state.exportPicker.type === 'projects'
        ? await window.deployerx.exportProjects(selectedIds)
        : await window.deployerx.exportTemplates(selectedIds);
    if (result?.canceled) return;
    const itemName = state.exportPicker.type === 'projects' ? 'server' : 'template';
    closeExportPicker();
    showToast(`Exported ${result.count} ${itemName}${result.count === 1 ? '' : 's'}`);
  } catch (error) {
    showAlert(error.message || 'Could not export items.');
  }
}

function exportProjects() {
  openExportPicker('projects');
}

function importResultDetail(result, duplicateType = '') {
  const label = duplicateType ? `${duplicateType[0].toUpperCase()}${duplicateType.slice(1)}` : '';
  const skipped = Number(result?.[label ? `skipped${label}DuplicateCount` : 'skippedDuplicateCount'] || 0);
  const replaced = Number(result?.[label ? `replaced${label}DuplicateCount` : 'replacedDuplicateCount'] || 0);
  const parts = [];
  if (replaced) parts.push(`${replaced} replaced`);
  if (skipped) parts.push(`${skipped} skipped`);
  return parts.length ? ` (${parts.join(', ')})` : '';
}

async function importProjects() {
  try {
    const result = await window.deployerx.importProjects();
    if (result?.canceled) return;
    state.projects = (result.projects || []).map(normalizeProject);
    if (state.activeProject) {
      state.activeProject = state.projects.find((project) => project.id === state.activeProject.id) || state.activeProject;
    }
    renderProjects();
    showToast(`Imported ${result.count} server${result.count === 1 ? '' : 's'}${importResultDetail(result)}`);
  } catch (error) {
    showAlert(error.message || 'Could not import servers.');
  }
}

async function exportAccount() {
  try {
    const result = await window.deployerx.exportAccount();
    if (result?.canceled) return;
    addBackupHistory('Account exported', `${result.projectCount} servers, ${result.templateCount} templates`);
    showToast(`Exported ${result.projectCount} server${result.projectCount === 1 ? '' : 's'} and ${result.templateCount} template${result.templateCount === 1 ? '' : 's'}`);
  } catch (error) {
    showAlert(error.message || 'Could not export account.');
  }
}

async function importAccount() {
  try {
    const result = await window.deployerx.importAccount();
    if (result?.canceled) return;
    await refreshProjectsAndTemplates();
    closeTemplateEditor();
    renderProjects();
    renderTemplates();
    renderTemplateSelect();
    const projectDetail = importResultDetail(result, 'server');
    const templateDetail = importResultDetail(result, 'template');
    addBackupHistory('Account imported', `${result.projectCount} servers, ${result.templateCount} templates`);
    showToast(
      `Imported ${result.projectCount} server${result.projectCount === 1 ? '' : 's'}${projectDetail} and ${result.templateCount} template${result.templateCount === 1 ? '' : 's'}${templateDetail}`
    );
  } catch (error) {
    showAlert(error.message || 'Could not import account.');
  }
}

async function saveTemplate(event) {
  event.preventDefault();
  if (pendingActions.has('template:save')) return;
  const activeTemplate = getTemplateById(state.activeTemplateId);
  const template = {
    id: isBuiltInTemplate(activeTemplate) ? '' : state.activeTemplateId,
    name: els.templateName.value.trim(),
    category: els.templateCategory.value,
    commands: normalizeCommands(els.templateCommands.value),
    variables: extractTemplateVariables(els.templateCommands.value)
  };

  if (!template.name || !template.category || !template.commands.length) {
    els.templatePageForm.reportValidity();
    return;
  }

  try {
    const result = await withButtonLoading('template:save', els.templatePageSaveButton, () =>
      window.deployerx.saveTemplate(template)
    );
    if (!result) return;
  } catch (error) {
    showAlert(error.message || 'Could not save template.');
    return;
  }

  await refreshProjectsAndTemplates();
  closeTemplateEditor();
  showToast(isBuiltInTemplate(activeTemplate) ? 'Library template saved as custom copy' : 'Template saved');
}

async function deleteTemplate() {
  if (!state.activeTemplateId || pendingActions.has('template:delete')) return;
  const templateId = state.activeTemplateId;
  const template = getTemplateById(templateId);
  if (isBuiltInTemplate(template)) {
    showAlert('Library templates cannot be deleted. Duplicate one to customize it.');
    return;
  }
  const ok = await confirmDangerousAction(
    `Delete template "${template?.name || 'Untitled template'}"?`,
    'This action cannot be undone.',
    'Delete'
  );
  if (!ok || pendingActions.has('template:delete')) return;
  try {
    await withButtonLoading('template:delete', els.deleteTemplateButton, () => window.deployerx.deleteTemplate(templateId));
  } catch (error) {
    showAlert(error.message || 'Could not delete template.');
    return;
  }

  await refreshProjectsAndTemplates();
  closeTemplateEditor();
}

function closeDuplicateTemplateModal() {
  state.duplicateTemplateDraft = null;
  els.duplicateTemplateName.value = '';
  els.duplicateTemplateCategory.value = '';
  setModalVisible(false, els.duplicateTemplateModal);
}

function openDuplicateTemplateModal() {
  if (!state.activeTemplateId) return;

  const commands = normalizeCommands(els.templateCommands.value);
  if (!commands.length) return;
  if (!els.templateCategory.value) {
    els.templatePageForm.reportValidity();
    return;
  }

  const currentName = els.templateName.value.trim() || 'Untitled template';
  state.duplicateTemplateDraft = {
    commands,
    variables: extractTemplateVariables(commands)
  };
  els.duplicateTemplateName.value = `${currentName} (copy)`;
  els.duplicateTemplateCategory.value = els.templateCategory.value;
  setModalVisible(true, els.duplicateTemplateModal);
  els.duplicateTemplateName.focus();
  els.duplicateTemplateName.select();
}

async function duplicateTemplate(event) {
  event.preventDefault();
  if (pendingActions.has('template:duplicate')) return;
  const name = els.duplicateTemplateName.value.trim();
  const category = els.duplicateTemplateCategory.value;
  const draft = state.duplicateTemplateDraft;
  if (!name || !category || !draft) {
    els.duplicateTemplateForm.reportValidity();
    return;
  }

  try {
    const result = await withButtonLoading('template:duplicate', els.duplicateTemplateSaveButton, () =>
      window.deployerx.saveTemplate({
        name,
        category,
        commands: draft.commands,
        variables: draft.variables
      })
    );
    if (!result) return;
    const saved = normalizeTemplate(result);
    await refreshProjectsAndTemplates();
    closeDuplicateTemplateModal();
    selectTemplate(saved.id);
    showToast('Template duplicated');
  } catch (error) {
    showAlert(error.message || 'Could not duplicate template.');
  }
}

function exportTemplates() {
  openExportPicker('templates');
}

async function importTemplates() {
  try {
    const result = await window.deployerx.importTemplates();
    if (result?.canceled) return;
    await refreshProjectsAndTemplates();
    closeTemplateEditor();
    showToast(`Imported ${result.count} template${result.count === 1 ? '' : 's'}${importResultDetail(result)}`);
  } catch (error) {
    showAlert(error.message || 'Could not import templates.');
  }
}

async function openProject(projectId) {
  const project = state.projects.find((item) => item.id === projectId);
  if (!project) return;
  if (project.serverType === 'rdp' && state.rdpSessionId && state.rdpProjectId !== project.id) {
    await disconnectRdp({ confirm: false });
  }
  populateProjectView(normalizeProject(project));
}

function openCreateModal() {
  state.modalMode = 'create';
  state.modalDraft = blankProject();
  els.projectModalTitle.textContent = 'Add server';
  fillModal(state.modalDraft);
  setProjectModalStep(0, { focus: false });
  setModalVisible(true, els.projectModal);
  requestAnimationFrame(() => els.modalProjectName.focus());
}

function openEditModal() {
  if (!state.activeProject) return;
  state.modalMode = 'edit';
  els.projectModalTitle.textContent = 'Edit server';
  fillModal(state.activeProject);
  setProjectModalStep(0, { focus: false });
  setModalVisible(true, els.projectModal);
  requestAnimationFrame(() => els.modalProjectName.focus());
}

async function commitModalProject(event) {
  event.preventDefault();
  if (pendingActions.has('project:save')) return;
  if (state.modalStep < getProjectModalSteps().panels.length - 1) {
    navigateProjectModalStep(state.modalStep + 1);
    return;
  }

  for (let step = 0; step < getProjectModalSteps().panels.length; step += 1) {
    if (!validateProjectModalStep(step)) return;
  }

  let project = readModalProject();

  let saved;
  try {
    saved = await withButtonLoading('project:save', els.projectModalSaveButton, async () => {
      const hydratedProject = await ensureProjectVariables(project, project.commands, {
        title: 'Set server variables',
        detail: 'This template needs a few values before the server can be saved.',
        confirmLabel: 'Save server'
      });
      if (!hydratedProject) return null;

      project = normalizeProject(hydratedProject);
      project.commands = resolveTemplateCommands(project.commands, project);
      return saveProject(project);
    });
    if (!saved) return;
  } catch (error) {
    showAlert(error.message || 'Could not save server.');
    return;
  }

  const shouldOpenRdp = saved.serverType === 'rdp';
  if (shouldOpenRdp && state.rdpSessionId && state.rdpProjectId === saved.id) {
    await disconnectRdp({ confirm: false });
  }
  state.activeProject = saved;
  renderProjects();
  populateProjectView(saved);
  setModalVisible(false, els.projectModal);
  if (shouldOpenRdp) requestAnimationFrame(() => connectRdp());
}

async function saveCommands() {
  if (!state.activeProject || pendingActions.has('project:commands')) return;
  const updated = {
    ...state.activeProject,
    commands: normalizeCommands(els.commands.value)
  };
  let saved;
  try {
    saved = await withButtonLoading('project:commands', els.saveCommandsButton, () => saveProject(updated));
    if (!saved) return;
  } catch (error) {
    showAlert(error.message || 'Could not save server commands.');
    return;
  }

  state.activeProject = saved;
  renderDetailsSummary(saved);
  renderProjects();
}

async function deleteCurrentProject() {
  if (!state.activeProject || pendingActions.has('project:delete')) return;
  const projectId = state.activeProject.id;
  const projectName = state.activeProject.name;
  const ok = await confirmDangerousAction(
    `Delete server "${projectName}"?`,
    'This action cannot be undone.',
    'Delete'
  );
  if (!ok || pendingActions.has('project:delete')) return;
  try {
    await withButtonLoading('project:delete', els.deleteProjectButton, () => window.deployerx.deleteProject(projectId));
  } catch (error) {
    showAlert(error.message || 'Could not delete server.');
    return;
  }

  await disconnectProjectConnections(projectId);
  state.projects = state.projects.filter((project) => project.id !== projectId);
  state.activeProject = state.projects[0] || null;
  renderProjects();
  if (state.activeProject) {
    populateProjectView(state.activeProject);
  } else {
    showView('servers');
  }
}

function openRunModal() {
  if (!state.activeProject) return;
  els.runNeedsUpload.checked = false;
  els.uploadLocalPath.value = '';
  els.uploadRemotePath.value = '';
  updateUploadFields();
  setModalVisible(true, els.uploadModal);
}

async function startDeployment(event) {
  if (event?.preventDefault) event.preventDefault();
  if (!state.activeProject) return;

  const rawCommands = normalizeCommands(els.commands.value);
  let hydratedProject;
  try {
    hydratedProject = await ensureProjectVariables(state.activeProject, rawCommands, {
      persist: true,
      title: 'Set deployment variables',
      detail: 'This deployment script needs a few variable values before it can run.',
      confirmLabel: 'Save and deploy'
    });
  } catch (error) {
    showAlert(error.message || 'Could not save project variables.');
    return;
  }
  if (!hydratedProject) return;
  state.activeProject = structuredClone(normalizeProject(hydratedProject));
  renderDetailsSummary(state.activeProject);
  renderProjects();

  const project = {
    ...state.activeProject,
    commands: resolveTemplateCommands(rawCommands, state.activeProject)
  };

  if (!project.commands.length) return;

  const upload = els.runNeedsUpload.checked
    ? {
        localPath: els.uploadLocalPath.value,
        remotePath: els.uploadRemotePath.value.trim()
      }
    : null;

  if (els.runNeedsUpload.checked && (!upload.localPath || !upload.remotePath)) return;

  const response = await window.deployerx.runDeployment({
    runId: `${Date.now()}`,
    project,
    upload
  });
  state.activeRunId = response.runId;
  terminal.clear();
  appendLog(`Starting deployment: ${project.name}\n`);
  setModalVisible(false, els.uploadModal);
}

function appendLog(message, kind = 'log') {
  const prefix = kind === 'error' ? '[stderr] ' : '';
  const rendered = `${prefix}${message}`.replace(/\n/g, '\r\n');
  const needsBreak = !String(message).endsWith('\n') && !String(message).endsWith('\r');
  const terminalSession = getTerminalSession();
  appendTerminalSessionOutput(terminalSession, rendered);
  if (needsBreak) appendTerminalSessionOutput(terminalSession, '\r\n');
}

function writeTerminalData(data) {
  appendTerminalSessionOutput(getTerminalSession(), data);
}

function stripTerminalControls(data) {
  return String(data ?? '')
    .replace(/\x1B\][^\x07]*(?:\x07|\x1B\\)/g, '')
    .replace(/\x1B\[[0-?]*[ -/]*[@-~]/g, '')
    .replace(/\x1B[()][A-Za-z0-9]/g, '')
    .replace(/\x0f/g, '');
}

function applyTerminalBackspaces(text) {
  const output = [];

  for (const char of String(text ?? '')) {
    if (char === '\b') {
      const lastChar = output[output.length - 1];
      if (lastChar && lastChar !== '\n') output.pop();
    } else {
      output.push(char);
    }
  }

  return output.join('');
}

function appendTerminalOutputBuffer(data, terminalSession = getTerminalSession()) {
  const rawText = String(data ?? '');
  const visibleText = applyTerminalBackspaces(stripTerminalControls(rawText).replace(/\r/g, '\n'));

  if (!terminalSession) {
    state.terminalRawBuffer = `${state.terminalRawBuffer}${rawText}`.slice(-4000);
    state.terminalOutputBuffer = `${state.terminalOutputBuffer}${visibleText}`.slice(-4000);
    return;
  }

  terminalSession.rawBuffer = `${terminalSession.rawBuffer || ''}${rawText}`.slice(-4000);
  terminalSession.outputBuffer = `${terminalSession.outputBuffer || ''}${visibleText}`.slice(-4000);
  const directoryMarkerConsumed = consumeTerminalDirectoryMarkers(rawText, terminalSession);
  if (!directoryMarkerConsumed) syncTerminalDirectoryFromOutput(terminalSession.outputBuffer, terminalSession);
  if (isVisibleTerminalSession(terminalSession)) {
    state.terminalRawBuffer = terminalSession.rawBuffer;
    state.terminalOutputBuffer = terminalSession.outputBuffer;
  }
}

function lastTerminalLine(terminalSession = getTerminalSessionById(state.scriptTerminalSessionId) || getTerminalSession()) {
  const lines = String(terminalSession?.outputBuffer || '').split('\n');
  return lines[lines.length - 1] || '';
}

function isShellPromptLine(line) {
  const prompt = String(line ?? '').trimEnd();
  if (!prompt || prompt.endsWith('?')) return false;

  return (
    /^\[[^\]\r\n]{1,160}\]\s*[#$]\s*$/.test(prompt) ||
    /^[A-Za-z0-9_.-]+@[\w.-]+:[^\r\n]{0,160}[#$]\s*$/.test(prompt) ||
    /^[A-Za-z0-9_.-]+@[\w.-]+\s+[^\r\n]{0,160}[#$]\s*$/.test(prompt)
  );
}

function clearScriptPromptTimer() {
  if (!state.scriptPromptTimer) return;
  clearTimeout(state.scriptPromptTimer);
  state.scriptPromptTimer = null;
}

function stopScriptQueue() {
  clearScriptPromptTimer();
  state.scriptCommandQueue = [];
  state.scriptRunnerActive = false;
  state.scriptWaitingForPrompt = false;
  state.scriptReadyMarker = '';
  state.scriptPromptMarkerActive = false;
  state.scriptTerminalSessionId = '';
}

function updateScriptStatus() {
  const terminalSession = getTerminalSessionById(state.scriptTerminalSessionId) || getTerminalSession();
  if (!state.scriptRunnerActive) {
    setTerminalSessionStatus(terminalSession, 'Connected', true);
    return;
  }

  setTerminalSessionStatus(terminalSession, `Running script (${state.scriptCommandQueue.length} queued)`, true);
}

async function runNextScriptCommand() {
  clearScriptPromptTimer();

  const terminalSession = getTerminalSessionById(state.scriptTerminalSessionId);
  if (!state.scriptRunnerActive || state.scriptWaitingForPrompt || !terminalSession?.connected) return;

  const command = state.scriptCommandQueue.shift();
  if (!command) {
    stopScriptQueue();
    setTerminalSessionStatus(terminalSession, 'Connected', true);
    return;
  }

  state.scriptWaitingForPrompt = true;
  terminalSession.outputBuffer = '';
  terminalSession.rawBuffer = '';
  if (isVisibleTerminalSession(terminalSession)) {
    state.terminalOutputBuffer = '';
    state.terminalRawBuffer = '';
  }
  updateScriptStatus();
  await sendTerminalInput(`${command}\n`, terminalSession.sessionId);
}

function createScriptPromptSetupCommand() {
  const marker = state.scriptReadyMarker;
  return `export PROMPT_COMMAND='printf "\\033]1337;${marker}\\007"'; if [ -n "$ZSH_VERSION" ]; then precmd() { printf "\\033]1337;${marker}\\007"; }; fi\n`;
}

async function prepareScriptQueue() {
  const terminalSession = getTerminalSessionById(state.scriptTerminalSessionId);
  if (!state.scriptRunnerActive || !terminalSession?.connected) return;

  state.scriptWaitingForPrompt = true;
  terminalSession.outputBuffer = '';
  terminalSession.rawBuffer = '';
  if (isVisibleTerminalSession(terminalSession)) {
    state.terminalOutputBuffer = '';
    state.terminalRawBuffer = '';
  }
  setTerminalSessionStatus(terminalSession, 'Preparing script runner', true);
  await sendTerminalInput(createScriptPromptSetupCommand(), terminalSession.sessionId);
}

function hasScriptReadyMarker(terminalSession = getTerminalSessionById(state.scriptTerminalSessionId) || getTerminalSession()) {
  if (!state.scriptReadyMarker) return false;

  return (
    String(terminalSession?.rawBuffer || '').includes(`\x1b]1337;${state.scriptReadyMarker}\x07`) ||
    String(terminalSession?.rawBuffer || '').includes(`\x1b]1337;${state.scriptReadyMarker}\x1b\\`)
  );
}

function maybeContinueScriptQueue(terminalSession = getTerminalSessionById(state.scriptTerminalSessionId)) {
  if (!state.scriptRunnerActive || !state.scriptWaitingForPrompt || !terminalSession || terminalSession.sessionId !== state.scriptTerminalSessionId) return;

  const markerSeen = hasScriptReadyMarker(terminalSession);
  if (markerSeen) state.scriptPromptMarkerActive = true;

  const promptSeen = !state.scriptPromptMarkerActive && isShellPromptLine(lastTerminalLine(terminalSession));
  if (!markerSeen && !promptSeen) return;

  clearScriptPromptTimer();
  state.scriptPromptTimer = setTimeout(() => {
    state.scriptPromptTimer = null;
    if (!state.scriptRunnerActive || !state.scriptWaitingForPrompt) return;
    if (!hasScriptReadyMarker(terminalSession) && !(!state.scriptPromptMarkerActive && isShellPromptLine(lastTerminalLine(terminalSession)))) return;

    state.scriptWaitingForPrompt = false;
    runNextScriptCommand().catch((error) => appendLog(error.message, 'error'));
  }, 150);
}

function handleTerminalData(data, terminalSession = getTerminalSession()) {
  appendTerminalSessionOutput(terminalSession, data);
  appendTerminalOutputBuffer(data, terminalSession);
  maybeContinueScriptQueue(terminalSession);
}

function resetTerminalView() {
  const terminalSession = getTerminalSession();
  if (terminalSession) {
    terminalSession.sessionId = null;
    terminalSession.connected = false;
    terminalSession.status = 'Not connected';
    terminalSession.pendingInput = '';
    terminalSession.outputBuffer = '';
    terminalSession.rawBuffer = '';
    terminalSession.commandBuffer = '';
    terminalSession.pendingDirectoryCandidate = '';
    terminalSession.awaitingPwd = false;
    terminalSession.directoryMarkerBuffer = '';
    terminalSession.directoryPromptMarkerSeen = false;
    terminalSession.upload = blankTerminalUploadState();
  }
  state.activeTerminalSessionId = null;
  state.terminalConnected = false;
  state.pendingTerminalInput = '';
  state.terminalOutputBuffer = '';
  state.terminalRawBuffer = '';
  stopScriptQueue();
  renderVisibleTerminalSession(terminalSession);
  updateTerminalStatus('Not connected', false);
}

async function startRun(event) {
  if (!state.activeProject) return;

  if (event?.preventDefault) event.preventDefault();
  const rawCommands = normalizeCommands(els.commands.value);
  let hydratedProject;
  try {
    hydratedProject = await ensureProjectVariables(state.activeProject, rawCommands, {
      persist: true,
      title: 'Set script variables',
      detail: 'This script needs a few variable values before it can run in the SSH terminal.',
      confirmLabel: 'Save and run'
    });
  } catch (error) {
    showAlert(error.message || 'Could not save project variables.');
    return;
  }
  if (!hydratedProject) return;
  state.activeProject = structuredClone(normalizeProject(hydratedProject));
  renderDetailsSummary(state.activeProject);
  renderProjects();

  const commands = resolveTemplateCommands(rawCommands, state.activeProject);
  if (!commands.length) return;

  if (!state.terminalConnected) {
    updateTerminalStatus('Connect SSH to run scripts', false);
    return;
  }

  stopScriptQueue();
  state.scriptCommandQueue = [...commands];
  state.scriptRunnerActive = true;
  state.scriptWaitingForPrompt = false;
  state.scriptReadyMarker = `__DEPLOYERX_READY_${Date.now()}_${Math.random().toString(36).slice(2)}__`;
  state.scriptPromptMarkerActive = false;
  state.scriptTerminalSessionId = state.activeTerminalSessionId || '';
  state.terminalOutputBuffer = '';
  state.terminalRawBuffer = '';

  await prepareScriptQueue();
}

async function ensureTerminal(terminalSession, project) {
  if (!project || !terminalSession) return false;
  if (terminalSession.connected) return true;
  if (terminalSession.sessionId) return false;
  if (isVisibleTerminalSession(terminalSession)) fitTerminal();

  const startupPath = String(terminalSession.startupDirectory || '').trim();
  const startupDirectory = startupPath ? normalizeRemoteShellPath(startupPath) : '';
  const sessionId = `terminal-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  terminalSession.sessionId = sessionId;
  terminalSession.connected = false;
  terminalSession.status = 'Connecting...';
  terminalSession.output = 'Ready.\r\n';
  terminalSession.pendingInput = startupDirectory ? `cd -- ${quoteShellPath(startupDirectory)}\r` : '';
  terminalSession.outputBuffer = '';
  terminalSession.rawBuffer = '';
  terminalSession.currentDirectory = '';
  terminalSession.homeDirectory = '';
  terminalSession.previousDirectory = '';
  terminalSession.directoryPath = '';
  terminalSession.directoryParentPath = '';
  terminalSession.directoryEntries = [];
  terminalSession.directorySelectedPath = '';
  terminalSession.directoryLoading = false;
  terminalSession.directoryError = '';
  terminalSession.directoryMarkerBuffer = '';
  terminalSession.directoryPromptMarkerSeen = false;
  state.terminalSessionProjectIds[sessionId] = project.id;
  if (isVisibleTerminalSession(terminalSession)) {
    state.activeTerminalSessionId = sessionId;
    state.pendingTerminalInput = terminalSession.pendingInput;
    renderVisibleTerminalSession(terminalSession);
    updateTerminalStatus('Connecting...');
  } else {
    renderTerminalTabs(project.id);
    renderProjects();
  }
  appendLog(`Opening terminal: ${project.name}\n`);

  const response = await window.deployerx.startTerminal({
    sessionId,
    project,
    cols: terminal.cols,
    rows: terminal.rows
  });
  const nextSessionId = response.sessionId || sessionId;
  if (nextSessionId !== sessionId) {
    removeTerminalSessionRegistration(sessionId);
    state.terminalSessionProjectIds[nextSessionId] = project.id;
  }
  terminalSession.sessionId = nextSessionId;
  if (isVisibleTerminalSession(terminalSession)) {
    state.activeTerminalSessionId = nextSessionId;
    updateTerminalStatus('Connecting...');
  } else {
    renderTerminalTabs(project.id);
  }
  setTimeout(() => {
    if (!isVisibleTerminalSession(terminalSession)) return;
    fitTerminal();
    resizeActiveTerminal();
  }, 250);
  return false;
}

async function sendTerminalInput(input, sessionId = state.activeTerminalSessionId) {
  if (!input) return;
  const terminalSession = getTerminalSessionById(sessionId) || getTerminalSession();
  const targetConnected = Boolean(terminalSession?.connected);

  if (!targetConnected) {
    if (sessionId && terminalSession && sessionId === terminalSession.sessionId && isVisibleTerminalSession(terminalSession)) {
      state.pendingTerminalInput = `${state.pendingTerminalInput || ''}${input}`;
      terminalSession.pendingInput = state.pendingTerminalInput;
    } else {
      updateTerminalStatus('Connect SSH first', false);
    }
    return;
  }

  trackTerminalInputChunk(input, sessionId);
  window.deployerx.sendTerminalInput({
    sessionId,
    input
  });
}

async function disconnectTerminal() {
  if (!state.activeTerminalSessionId) return;
  const sessionId = state.activeTerminalSessionId;
  const ok = await confirmDangerousAction(
    'Disconnect the active terminal session?',
    'Running shell commands in this terminal session will be stopped.',
    'Disconnect'
  );
  if (!ok) return;
  stopScriptQueue();
  await window.deployerx.stopTerminal(sessionId);
}

async function connectTerminal() {
  const project = state.activeProject;
  const terminalSession = getTerminalSession(project?.id, true);
  if (!project || !terminalSession || terminalSession.sessionId || terminalSession.connected) return;
  try {
    await ensureTerminal(terminalSession, project);
  } catch (error) {
    removeTerminalSessionRegistration(terminalSession.sessionId);
    terminalSession.sessionId = null;
    terminalSession.connected = false;
    terminalSession.status = 'Connection failed';
    if (isVisibleTerminalSession(terminalSession)) {
      state.activeTerminalSessionId = null;
      state.terminalConnected = false;
      updateTerminalStatus('Connection failed', false);
    } else {
      renderTerminalTabs(project.id);
      renderProjects();
    }
    appendLog(`${error.message}\n`, 'error');
  }
}

async function uploadFileToCurrentSshPath() {
  const terminalSession = getTerminalSession();
  if (!terminalSession?.sessionId || !terminalSession.connected || pendingActions.has('terminal:upload')) return;
  if (terminalSession.pendingDirectoryCandidate) {
    showAlert('Wait for the current directory to finish updating, then upload.');
    return;
  }

  let remoteDirectory = String(terminalSession.currentDirectory || '').trim();
  if (!remoteDirectory) {
    try {
      await ensureTerminalHomeDirectory(terminalSession.sessionId);
    } catch {}
    remoteDirectory = String(terminalSession.currentDirectory || terminalSession.homeDirectory || '').trim();
  }
  if (!remoteDirectory) {
    showAlert('Current SSH path is not ready yet. Try again in a moment.');
    return;
  }

  const localPath = await window.deployerx.selectUpload();
  if (!localPath) return;

  const fileName = fileNameFromPath(localPath);
  const remotePath = joinRemoteShellPath(remoteDirectory, fileName);
  setTerminalUploadState(terminalSession, {
    active: true,
    fileName,
    remotePath,
    transferredBytes: 0,
    totalBytes: 0,
    percent: 0,
    cancelRequested: false
  });

  try {
    await withButtonLoading('terminal:upload', els.sshUploadButton, () =>
      window.deployerx.uploadTerminalFile({
        sessionId: terminalSession.sessionId,
        localPath,
        remoteDirectory
      })
    );
  } catch (error) {
    const canceled = Boolean(terminalSession.upload?.cancelRequested);
    setTerminalUploadState(terminalSession, blankTerminalUploadState());
    if (canceled || /canceled/i.test(String(error?.message || ''))) {
      showToast('Upload canceled');
      return;
    }
    showAlert(error.message || 'Could not upload file.');
  }
}

async function cancelCurrentSshUpload() {
  const terminalSession = getTerminalSession();
  if (!terminalSession?.sessionId || !terminalSession.upload?.active || terminalSession.upload.cancelRequested) return;

  setTerminalUploadState(terminalSession, {
    ...terminalSession.upload,
    cancelRequested: true
  });

  try {
    const canceled = await window.deployerx.cancelTerminalUpload(terminalSession.sessionId);
    if (!canceled) {
      setTerminalUploadState(terminalSession, {
        ...terminalSession.upload,
        cancelRequested: false
      });
    }
  } catch (error) {
    setTerminalUploadState(terminalSession, {
      ...terminalSession.upload,
      cancelRequested: false
    });
    showAlert(error.message || 'Could not cancel upload.');
  }
}

async function emergencyStop() {
  const ok = await confirmDangerousAction(
    'Emergency stop active connections?',
    'Deployments, terminal sessions, file connections, and Remote Desktop will be stopped immediately.',
    'Stop'
  );
  if (!ok) return;
  const rdpClient = activeRdpClient;
  activeRdpClient = null;
  rdpClient?.disconnect();
  await window.deployerx.emergencyStop();
  state.activeRunId = null;
  const activeProjectId = state.activeProject?.id || '';
  state.terminalSessions = {};
  state.terminalSessionProjectIds = {};
  state.activeTerminalTabIds = {};
  state.terminalTabCounters = {};
  state.ftpSessions = {};
  state.activeTerminalSessionId = null;
  state.terminalConnected = false;
  state.rdpSessionId = null;
  state.rdpProjectId = '';
  state.rdpStatus = 'disconnected';
  state.ftpSessionId = null;
  state.ftpConnected = false;
  state.ftpCurrentPath = '.';
  state.ftpParentPath = '.';
  state.ftpEntries = [];
  state.ftpSelectedPath = '';
  state.ftpBackStack = [];
  state.ftpForwardStack = [];
  state.pendingTerminalInput = '';
  state.terminalOutputBuffer = '';
  state.terminalRawBuffer = '';
  stopScriptQueue();
  if (activeProjectId) {
    const terminalSession = createTerminalTabSession(activeProjectId);
    state.terminalSessions[activeProjectId] = [terminalSession];
    state.activeTerminalTabIds[activeProjectId] = terminalSession.tabId;
    state.ftpSessions[activeProjectId] = blankFtpSession(activeProjectId);
    if (!isRdpProject()) {
      applyTerminalSessionToState(activeProjectId);
      renderVisibleTerminalSession(terminalSession);
      updateTerminalStatus('Not connected', false);
    }
  }
  appendLog('Emergency stop requested.\n', 'error');
  renderFtpBrowser();
  if (isRdpProject()) setRdpStatus('disconnected', 'Not connected');
}

