function isEditableShortcutTarget(target) {
  return (
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement ||
    (target instanceof HTMLElement && target.isContentEditable)
  );
}

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape' && state.rdpFullscreen) {
    event.preventDefault();
    event.stopImmediatePropagation();
    if (!event.repeat) toggleRdpFullscreen().catch((error) => showAlert(error.message || 'Could not exit full view.'));
    return;
  }
  if (els.terminal?.contains(event.target)) return;
  const primaryModifier = event.ctrlKey || event.metaKey;
  const key = event.key.toLowerCase();
  if (
    primaryModifier &&
    !event.shiftKey &&
    key === 'z' &&
    state.activeProjectTab === 'ftp' &&
    !els.ftpWorkspace.classList.contains('hidden') &&
    !isEditableShortcutTarget(event.target)
  ) {
    event.preventDefault();
    undoLastFtpTransfer().catch((error) => showAlert(error.message || 'Could not undo the file transfer.'));
    return;
  }
  if (primaryModifier && key === 'r') {
    event.preventDefault();
    refreshCurrentPage();
  }
});
