els.databaseNotebookCells.addEventListener('input', (event) => {
  const cell = state.databaseManager.notebooks.cells.find((item) => item.id === event.target.dataset.databaseNotebookContent);
  if (!cell) return;
  cell.content = event.target.value;
  state.databaseManager.notebooks.dirty = true;
  const preview = els.databaseNotebookCells.querySelector(`[data-database-notebook-preview="${CSS.escape(cell.id)}"]`);
  if (preview) preview.innerHTML = databaseNotebookMarkdown(cell.content);
});
els.databaseNotebookCells.addEventListener('change', (event) => {
  const control = event.target.closest('[data-database-notebook-chart]');
  if (!control) return;
  const cell = state.databaseManager.notebooks.cells.find((item) => item.id === control.dataset.databaseNotebookChart && item.type === 'chart');
  const field = control.dataset.chartField;
  if (!cell?.chart || !['sourceCellId', 'chartType', 'categoryColumn', 'valueColumn'].includes(field)) return;
  cell.chart[field] = control.value;
  if (field === 'sourceCellId') { cell.chart.categoryColumn = ''; cell.chart.valueColumn = ''; }
  state.databaseManager.notebooks.dirty = true;
  renderDatabaseNotebook();
});
els.databaseNotebookCells.addEventListener('click', (event) => {
  const run = event.target.closest('[data-database-notebook-run]');
  const cancel = event.target.closest('[data-database-notebook-cancel]');
  const format = event.target.closest('[data-database-notebook-format]');
  const remove = event.target.closest('[data-database-notebook-remove]');
  const move = event.target.closest('[data-database-notebook-move]');
  const collapse = event.target.closest('[data-database-notebook-collapse]');
  if (format) formatDatabaseNotebookCell(format.dataset.databaseNotebookFormat);
  else if (run) runDatabaseNotebookCell(run.dataset.databaseNotebookRun).catch((error) => showAlert(error.message || 'Could not run the notebook cell.'));
  else if (cancel) cancelDatabaseNotebookCell().catch((error) => showAlert(error.message || 'Could not cancel the notebook cell.'));
  else if (collapse) {
    const cell = state.databaseManager.notebooks.cells.find((item) => item.id === collapse.dataset.databaseNotebookCollapse);
    if (cell) { cell.collapsed = !cell.collapsed; state.databaseManager.notebooks.dirty = true; renderDatabaseNotebook(); }
  }
  else if (remove) {
    const cells = state.databaseManager.notebooks.cells;
    const index = cells.findIndex((item) => item.id === remove.dataset.databaseNotebookRemove);
    const removed = cells[index];
    if (index >= 0 && cells.length > 1) cells.splice(index, 1);
    if (removed?.type === 'sql') {
      const replacement = cells.find((item) => item.type === 'sql');
      for (const chartCell of cells.filter((item) => item.type === 'chart' && item.chart?.sourceCellId === removed.id)) chartCell.chart.sourceCellId = replacement?.id || '';
    }
    state.databaseManager.notebooks.dirty = true;
    renderDatabaseNotebook();
  } else if (move) {
    moveDatabaseNotebookCell(move.dataset.databaseNotebookMove, move.dataset.direction);
  }
});
els.databaseNotebookCells.addEventListener('keydown', (event) => {
  if (!event.altKey || !['ArrowUp', 'ArrowDown'].includes(event.key)) return;
  const cell = event.target.closest('[data-database-notebook-cell]');
  if (!cell) return;
  event.preventDefault();
  moveDatabaseNotebookCell(cell.dataset.databaseNotebookCell, event.key === 'ArrowUp' ? -1 : 1);
});
