els.databaseProfileList.addEventListener('click', (event) => {
  const keepLocalButton = event.target.closest('[data-database-profile-conflict-local]');
  const useCloudButton = event.target.closest('[data-database-profile-conflict-cloud]');
  const bindButton = event.target.closest('[data-database-profile-bind]');
  const backupButton = event.target.closest('[data-database-profile-backup]');
  const connectionButton = event.target.closest('[data-database-profile-connection]');
  const testButton = event.target.closest('[data-database-profile-test]');
  const editButton = event.target.closest('[data-database-profile-edit]');
  const deleteButton = event.target.closest('[data-database-profile-delete]');
  if (keepLocalButton) {
    const profile = state.databaseManager.profiles.find((item) => item.id === keepLocalButton.dataset.databaseProfileConflictLocal);
    if (profile) resolveDatabaseProfileCloudConflict(profile, 'keep-local', keepLocalButton).catch((error) => showAlert(error.message || 'Could not keep this device metadata.'));
  }
  if (useCloudButton) {
    const profile = state.databaseManager.profiles.find((item) => item.id === useCloudButton.dataset.databaseProfileConflictCloud);
    if (profile) resolveDatabaseProfileCloudConflict(profile, 'use-cloud', useCloudButton).catch((error) => showAlert(error.message || 'Could not apply cloud metadata.'));
  }
  if (bindButton) {
    const profile = state.databaseManager.profiles.find((item) => item.id === bindButton.dataset.databaseProfileBind);
    if (profile) bindDatabaseProfileLocalResource(profile, bindButton).catch((error) => showAlert(error.message || 'Could not link the local database file.'));
  }
  if (backupButton) {
    const profile = state.databaseManager.profiles.find((item) => item.id === backupButton.dataset.databaseProfileBackup);
    if (profile) protectDatabaseProfileWithBackupManager(profile, backupButton).catch((error) => showAlert(error.message || 'Could not open this profile in Backup Manager.'));
  }
  if (connectionButton) {
    const profile = state.databaseManager.profiles.find((item) => item.id === connectionButton.dataset.databaseProfileConnection);
    if (profile) toggleDatabaseConnection(profile, connectionButton).catch((error) => showAlert(error.message || 'Could not change the database connection.'));
  }
  if (testButton) {
    const profile = state.databaseManager.profiles.find((item) => item.id === testButton.dataset.databaseProfileTest);
    if (profile) testDatabaseProfile(profile, testButton).catch((error) => showAlert(error.message || 'Could not test the database connection.'));
  }
  if (editButton) {
    const profile = state.databaseManager.profiles.find((item) => item.id === editButton.dataset.databaseProfileEdit);
    if (profile) openDatabaseProfileModal(profile);
  }
  if (deleteButton) {
    const profile = state.databaseManager.profiles.find((item) => item.id === deleteButton.dataset.databaseProfileDelete);
    if (profile) deleteDatabaseProfile(profile).catch((error) => showAlert(error.message || 'Could not delete the database profile.'));
  }
});
