els.backupRecoveryEntryList.addEventListener('click', (event) => {
  const selection = event.target.closest('[data-backup-recovery-select]');
  if (selection) {
    if (selection.checked) state.backupRecovery.selectedPaths.add(selection.dataset.backupRecoverySelect);
    else state.backupRecovery.selectedPaths.delete(selection.dataset.backupRecoverySelect);
    renderBackupRecoveryEntries();
    return;
  }
  const button = event.target.closest('[data-backup-recovery-entry]');
  if (!button) return;
  const path = button.dataset.backupRecoveryEntry;
  if (button.dataset.backupRecoveryEntryType === 'directory') {
    loadBackupRecoveryDirectory(path, { resetSearch: true }).catch((error) => showAlert(error.message || 'Could not open this snapshot folder.'));
  } else {
    openBackupFileVersions(path).catch((error) => {
      closeBackupFileVersions();
      showAlert(error.message || 'Could not load file versions.');
    });
  }
});
els.backupRecoveryEntriesMoreButton.addEventListener('click', () => loadMoreBackupRecoveryEntries().catch((error) => showAlert(error.message || 'Could not load more snapshot entries.')));
els.backupRecoveryRestoreButton.addEventListener('click', () => {
  if (recoveryDatabaseEngine() === 'cockroachdb') openBackupCockroachDbRestore().catch((error) => showAlert(error.message || 'Could not prepare the CockroachDB alternate recovery.'));
  else if (recoveryDatabaseEngine() === 'influxdb3-enterprise') (influxDb3EnterpriseRecoveryTier() === 'legacy-filesystem' ? openBackupInfluxDb3EnterpriseLegacyRestore() : openBackupInfluxDb3EnterpriseRestore()).catch((error) => showAlert(error.message || 'Could not prepare the Enterprise recovery.'));
  else if (['influxdb', 'influxdb3-core'].includes(recoveryDatabaseEngine())) openBackupInfluxDbRestore().catch((error) => showAlert(error.message || 'Could not prepare the InfluxDB recovery.'));
  else if (recoveryDatabaseEngine() === 'clickhouse') openBackupClickHouseRestore().catch((error) => showAlert(error.message || 'Could not prepare the ClickHouse recovery.'));
  else if (recoveryDatabaseEngine() === 'neo4j') openBackupNeo4jRestore().catch((error) => showAlert(error.message || 'Could not prepare the Neo4j recovery.'));
  else if (recoveryDatabaseEngine() === 'scylla-manager') openBackupScyllaManagerRestore().catch((error) => showAlert(error.message || 'Could not prepare the Manager restore.'));
  else if (recoveryDatabaseEngine() === 'search-snapshot') openBackupSearchSnapshotRestore().catch((error) => showAlert(error.message || 'Could not prepare the search restore.'));
  else if (recoveryDatabaseEngine() === 'redis') openBackupRedisRestore();
  else if (recoveryDatabaseEngine() === 'sqlite') openBackupSqliteRestore();
  else if (isDatabaseRecoveryPoint()) openBackupMysqlRestore();
  else openBackupFileRestore().catch((error) => showAlert(error.message || 'Could not prepare the restore.'));
});
els.backupRecoveryVerifyButton.addEventListener('click', () => {
  if (recoveryDatabaseEngine() === 'cockroachdb') startBackupCockroachDbMetadataTest().catch((error) => showAlert(error.message || 'CockroachDB metadata recovery test failed.'));
  else if (recoveryDatabaseEngine() === 'influxdb3-enterprise') (influxDb3EnterpriseRecoveryTier() === 'legacy-filesystem' ? openBackupInfluxDb3EnterpriseLegacyVerification() : openBackupInfluxDb3EnterpriseVerification()).catch((error) => showAlert(error.message || 'Could not prepare the Enterprise recovery test.'));
  else if (['influxdb', 'influxdb3-core'].includes(recoveryDatabaseEngine())) openBackupInfluxDbVerification().catch((error) => showAlert(error.message || 'Could not prepare the InfluxDB recovery test.'));
  else if (recoveryDatabaseEngine() === 'clickhouse') openBackupClickHouseVerification().catch((error) => showAlert(error.message || 'Could not prepare the ClickHouse recovery test.'));
  else if (recoveryDatabaseEngine() === 'neo4j') openBackupNeo4jVerification().catch((error) => showAlert(error.message || 'Could not prepare the Neo4j recovery test.'));
  else if (recoveryDatabaseEngine() === 'scylla-manager') openBackupScyllaManagerVerification().catch((error) => showAlert(error.message || 'Could not prepare the Manager recovery test.'));
  else if (recoveryDatabaseEngine() === 'search-snapshot') openBackupSearchSnapshotVerification().catch((error) => showAlert(error.message || 'Could not prepare the search recovery test.'));
  else openBackupVerification();
});
