els.backupJobList.addEventListener('click', (event) => {
  const runButton = event.target.closest('[data-backup-run-job]');
  const resumeButton = event.target.closest('[data-backup-resume-run]');
  const cancelButton = event.target.closest('[data-backup-cancel-run]');
  const retryButton = event.target.closest('[data-backup-retry-run]');
  const pauseJobButton = event.target.closest('[data-backup-job-pause]');
  const resumeJobButton = event.target.closest('[data-backup-job-resume]');
  const cloneJobButton = event.target.closest('[data-backup-job-clone]');
  const disableJobButton = event.target.closest('[data-backup-job-disable]');
  const deleteJobButton = event.target.closest('[data-backup-job-delete]');
  const cockroachScheduleButton = event.target.closest('[data-backup-cockroachdb-schedule]');
  if (runButton) runBackupJob(runButton.dataset.backupRunJob).catch((error) => showAlert(error.message || 'Could not start the backup.'));
  if (resumeButton) resumeBackupRun(resumeButton.dataset.backupResumeRun).catch((error) => showAlert(error.message || 'Could not resume the backup.'));
  if (cancelButton) cancelBackupRun(cancelButton.dataset.backupCancelRun).catch((error) => showAlert(error.message || 'Could not cancel the backup.'));
  if (retryButton) retryBackupRun(retryButton.dataset.backupRetryRun).catch((error) => showAlert(error.message || 'Could not retry the backup.'));
  if (pauseJobButton) changeBackupJobState(pauseJobButton.dataset.backupJobPause, 'pause').catch((error) => showAlert(error.message || 'Could not pause the backup job.'));
  if (resumeJobButton) changeBackupJobState(resumeJobButton.dataset.backupJobResume, 'resume').catch((error) => showAlert(error.message || 'Could not resume the backup job.'));
  if (cloneJobButton) cloneBackupJob(cloneJobButton.dataset.backupJobClone).catch((error) => showAlert(error.message || 'Could not clone the backup job.'));
  if (disableJobButton) disableBackupJob(disableJobButton.dataset.backupJobDisable).catch((error) => showAlert(error.message || 'Could not disable the backup job.'));
  if (deleteJobButton) deleteBackupJob(deleteJobButton.dataset.backupJobDelete).catch((error) => showAlert(error.message || 'Could not delete the backup job.'));
  if (cockroachScheduleButton) openBackupCockroachDbSchedule(cockroachScheduleButton.dataset.backupCockroachdbSchedule).catch((error) => showAlert(error.message || 'Could not prepare the CockroachDB native schedule.'));
});
