els.backupRepositoryList.addEventListener('click', (event) => {
  const policyButton = event.target.closest('[data-backup-repository-policy]');
  if (policyButton) {
    openBackupRepositoryPolicy(policyButton.dataset.backupRepositoryPolicy);
    return;
  }
  const pruneButton = event.target.closest('[data-backup-repository-prune]');
  if (pruneButton) {
    pruneBackupRepository(pruneButton.dataset.backupRepositoryPrune, pruneButton);
    return;
  }
  const testButton = event.target.closest('[data-backup-repository-test]');
  if (testButton) {
    testBackupRepository(testButton.dataset.backupRepositoryTest, testButton.dataset.backupRepositoryKind, testButton);
    return;
  }
  const button = event.target.closest('[data-backup-repository-delete]');
  if (!button) return;
  if (button.dataset.backupRepositoryKind === 'sftp') removeBackupSftpRepository(button.dataset.backupRepositoryDelete, button);
  else if (button.dataset.backupRepositoryKind === 's3') removeBackupS3Repository(button.dataset.backupRepositoryDelete, button);
  else removeBackupLocalRepository(button.dataset.backupRepositoryDelete, button);
});
els.backupSourceConnections.addEventListener('click', (event) => {
  const browseButton = event.target.closest('[data-backup-connection-browse]');
  if (browseButton) {
    const connection = allBackupConnections().find((item) => item.id === browseButton.dataset.backupConnectionBrowse && item.connectionKind === browseButton.dataset.backupConnectionKind);
    if (connection?.connectionKind === 'sqlite') {
      openBackupSqliteModal(connection);
      discoverBackupSqlite();
    } else if (connection?.connectionKind === 'redis') {
      openBackupRedisModal(connection);
      discoverBackupRedis();
    } else if (connection?.connectionKind === 'search-snapshot') {
      openBackupSearchSnapshotModal(connection);
      discoverBackupSearchSnapshot();
    } else if (connection?.connectionKind === 'scylla-manager') {
      openBackupScyllaManagerModal(connection);
      discoverBackupScyllaManager();
    } else if (connection?.connectionKind === 'neo4j') {
      openBackupNeo4jModal(connection);
      discoverBackupNeo4j();
    } else if (connection?.connectionKind === 'clickhouse') {
      openBackupClickHouseModal(connection);
      discoverBackupClickHouse();
    } else if (connection?.connectionKind === 'influxdb') {
      openBackupInfluxDbModal(connection);
      discoverBackupInfluxDb();
    } else if (connection?.connectionKind === 'influxdb3-core') {
      openBackupInfluxDb3CoreModal(connection);
      discoverBackupInfluxDb3Core();
    } else if (connection?.connectionKind === 'influxdb3-enterprise') {
      openBackupInfluxDb3EnterpriseModal(connection);
      discoverBackupInfluxDb3Enterprise();
    } else if (connection?.connectionKind === 'cockroachdb') {
      openBackupCockroachDbModal(connection);
      discoverBackupCockroachDb();
    } else if (['mysql', 'mariadb', 'postgresql', 'sqlserver', 'oracle', 'mongodb'].includes(connection?.connectionKind)) {
      openBackupMysqlModal(connection);
      discoverBackupMysql();
    } else openBackupBrowser(connection);
    return;
  }
  const diagnosticsButton = event.target.closest('[data-backup-connection-diagnostics]');
  if (diagnosticsButton) {
    const connection = allBackupConnections().find((item) => item.id === diagnosticsButton.dataset.backupConnectionDiagnostics && item.connectionKind === diagnosticsButton.dataset.backupConnectionKind);
    openBackupDiagnostics(connection);
    return;
  }
  const button = event.target.closest('[data-backup-connection-test]');
  if (!button) return;
  if (button.dataset.backupConnectionKind === 'ssh') testBackupSshConnection(button.dataset.backupConnectionTest, button);
  else if (['mysql', 'mariadb', 'postgresql', 'sqlserver', 'oracle', 'mongodb', 'neo4j', 'clickhouse', 'influxdb', 'influxdb3-core', 'influxdb3-enterprise', 'cockroachdb', 'redis', 'search-snapshot', 'scylla-manager', 'sqlite'].includes(button.dataset.backupConnectionKind)) testBackupDatabaseConnection(button.dataset.backupConnectionTest, button.dataset.backupConnectionKind, button);
  else testBackupLocalConnection(button.dataset.backupConnectionTest, button);
});
