els.backupBrowserEntries.addEventListener('change', (event) => {
  const checkbox = event.target.closest('[data-backup-browser-select]');
  if (!checkbox) return;
  const key = backupBrowserPathKey(checkbox.dataset.backupBrowserSelect);
  state.backupBrowser.selectedRoots = state.backupBrowser.selectedRoots.filter((root) => backupBrowserPathKey(root.path) !== key);
  if (checkbox.checked) {
    state.backupBrowser.selectedRoots.push({ path: checkbox.dataset.backupBrowserSelect, type: checkbox.dataset.backupBrowserSelectType });
  }
  renderBackupBrowser();
});
els.backupBrowserSelectedPaths.addEventListener('click', (event) => {
  const button = event.target.closest('[data-backup-selected-path-remove]');
  if (!button) return;
  const key = backupBrowserPathKey(button.dataset.backupSelectedPathRemove);
  state.backupBrowser.selectedRoots = state.backupBrowser.selectedRoots.filter((root) => backupBrowserPathKey(root.path) !== key);
  renderBackupBrowser();
});
