for (const config of uptimeTableFilterDropdowns()) {
  config.button.addEventListener('click', () => {
    if (config.button.getAttribute('aria-expanded') === 'true') closeUptimeMonitorFilterMenu(config);
    else openUptimeMonitorFilterMenu(config);
  });
  config.button.addEventListener('keydown', (event) => {
    if (!['ArrowDown', 'ArrowUp'].includes(event.key)) return;
    event.preventDefault();
    openUptimeMonitorFilterMenu(config);
  });
  config.menu.addEventListener('click', (event) => {
    const option = event.target.closest('.workspace-switcher-option');
    if (!option) return;
    config.select.value = option.dataset.uptimeFilterValue ?? '';
    config.select.dispatchEvent(new Event('change', { bubbles: true }));
    config.button.focus();
  });
  config.menu.addEventListener('keydown', (event) => {
    const options = Array.from(config.menu.querySelectorAll('.workspace-switcher-option'));
    if (!options.length) return;
    const currentIndex = options.indexOf(document.activeElement);
    let nextIndex = currentIndex;
    if (event.key === 'ArrowDown') nextIndex = (currentIndex + 1) % options.length;
    else if (event.key === 'ArrowUp') nextIndex = (currentIndex - 1 + options.length) % options.length;
    else if (event.key === 'Home') nextIndex = 0;
    else if (event.key === 'End') nextIndex = options.length - 1;
    else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      document.activeElement?.click();
      return;
    } else if (event.key === 'Escape' || event.key === 'Tab') {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
      }
      closeUptimeMonitorFilterMenu(config, { focusTrigger: event.key === 'Escape' });
      return;
    } else return;
    event.preventDefault();
    options[nextIndex]?.focus();
  });
}
