els.uptimeWorkspace.addEventListener('click', async (event) => {
  const selectMonitor = event.target.closest('[data-uptime-select-monitor]');
  const selectIncident = event.target.closest('[data-uptime-select-incident]');
  const runButton = event.target.closest('[data-uptime-run-monitor]');
  const editButton = event.target.closest('[data-uptime-edit-monitor]');
  const acknowledgeButton = event.target.closest('[data-uptime-acknowledge]');
  const editMaintenance = event.target.closest('[data-uptime-edit-maintenance]');
  const deleteMaintenance = event.target.closest('[data-uptime-delete-maintenance]');
  try {
    if (selectMonitor) {
      state.uptime.selectedMonitorId = selectMonitor.dataset.uptimeSelectMonitor;
      setUptimeTab('monitors');
      renderUptimeMonitorTable();
      await loadSelectedUptimeMonitorHistory();
    } else if (selectIncident) {
      const incident = state.uptime.incidents.find((item) => item.id === selectIncident.dataset.uptimeSelectIncident);
      state.uptime.selectedIncidentId = selectIncident.dataset.uptimeSelectIncident;
      if (incident) state.uptime.selectedMonitorId = incident.monitorId;
      setUptimeTab('incidents');
      renderUptimeIncidents();
    } else if (runButton) {
      await window.deployerx.runUptimeMonitorNow(runButton.dataset.uptimeRunMonitor);
      showToast('Run queued');
    } else if (editButton) openUptimeMonitorModal('edit', editButton.dataset.uptimeEditMonitor);
    else if (acknowledgeButton) {
      const incident = state.uptime.incidents.find((item) => item.id === acknowledgeButton.dataset.uptimeAcknowledge);
      if (incident) await window.deployerx.acknowledgeUptimeIncident(incident.id, incident.revision, 'Acknowledged from Uptime Monitor');
      await refreshUptimeProjectState({ preserveSelection: true });
      showToast('Incident acknowledged');
    } else if (editMaintenance) openUptimeMaintenanceModal(editMaintenance.dataset.uptimeEditMaintenance);
    else if (deleteMaintenance) {
      const windowItem = state.uptime.maintenance.find((item) => item.id === deleteMaintenance.dataset.uptimeDeleteMaintenance);
      if (windowItem && await confirmDangerousAction(`Delete "${windowItem.name}"?`, 'Historical checks remain unchanged.', 'Delete')) {
        await window.deployerx.deleteUptimeMaintenance(windowItem.id, windowItem.revision);
        await refreshUptimeProjectState({ preserveSelection: true });
        showToast('Maintenance deleted');
      }
    }
  } catch (error) { showAlert(error.message || 'Could not complete the Uptime action.'); }
});
