function setScriptRailCollapsed(collapsed, { persist = true } = {}) {
  els.sshWorkspace.classList.toggle('script-rail-collapsed', collapsed);
  els.sshWorkspace.classList.toggle('script-rail-expanded', !collapsed);
  els.scriptRailToggle.setAttribute('aria-expanded', String(!collapsed));
  els.scriptRailToggle.setAttribute('aria-label', collapsed ? 'Expand side panel' : 'Collapse side panel');
  els.scriptRailToggle.title = collapsed ? 'Expand side panel' : 'Collapse side panel';
  if (persist) localStorage.setItem('deployerx-script-rail-collapsed', String(collapsed));
}

let scriptRailWasCompact = window.innerWidth <= 1180;
let sidebarCollapsedBeforeScriptRailOpen = null;
function syncResponsivePanels({ initial = false } = {}) {
  const isCompact = window.innerWidth <= 1180;
  if (['team', 'profile'].includes(state.currentView)) {
    setSidebarCollapsed(true, { persist: false });
    scriptRailWasCompact = isCompact;
    return;
  }
  let prefersSidebarCollapsed = false;
  try {
    prefersSidebarCollapsed = window.localStorage.getItem('deployerx.sidebarCollapsed') === 'true';
  } catch {}
  if (isCompact) {
    // Compact layouts keep the saved sidebar state and start with Scripts closed.
    if (initial || !scriptRailWasCompact) {
      sidebarCollapsedBeforeScriptRailOpen = null;
      setSidebarCollapsed(prefersSidebarCollapsed, { persist: false });
      setScriptRailCollapsed(true, { persist: false });
    }
  } else if (initial || scriptRailWasCompact) {
    // A wide window has room for both sections; restore them after resizing.
    sidebarCollapsedBeforeScriptRailOpen = null;
    setSidebarCollapsed(prefersSidebarCollapsed, { persist: false });
    setScriptRailCollapsed(false, { persist: false });
  }
  scriptRailWasCompact = isCompact;
}
syncResponsivePanels({ initial: true });
window.addEventListener('resize', () => {
  syncResponsivePanels();
  requestAnimationFrame(fitTerminal);
});
els.scriptRailToggle.addEventListener('click', () => {
  const shouldCollapse = !els.sshWorkspace.classList.contains('script-rail-collapsed');
  if (window.innerWidth <= 1180 && !shouldCollapse) {
    sidebarCollapsedBeforeScriptRailOpen = els.appShell.classList.contains('sidebar-collapsed');
    setSidebarCollapsed(true, { persist: false });
  }
  setScriptRailCollapsed(shouldCollapse);
  if (window.innerWidth <= 1180 && shouldCollapse && sidebarCollapsedBeforeScriptRailOpen !== null) {
    setSidebarCollapsed(sidebarCollapsedBeforeScriptRailOpen, { persist: false });
    sidebarCollapsedBeforeScriptRailOpen = null;
  }
  requestAnimationFrame(fitTerminal);
});
